window.TREE={"subject":"Area IV · Individual Taxation","key":"reg_area4_individuals","brand":"Terra Prep","area":"IV","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area IV · Individual Taxation","chs":["1-01","1-02","1-03","1-04","1-05","1-06"],"color":"--mint"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Gross income","grp":"A","nodes":[1]},{"key":"1-02","part":1,"no":2,"name":"Pass-through items","grp":"B","nodes":[2]},{"key":"1-03","part":1,"no":3,"name":"Adjustments and deductions","grp":"C","nodes":[3]},{"key":"1-04","part":1,"no":4,"name":"Loss limitations","grp":"D","nodes":[4]},{"key":"1-05","part":1,"no":5,"name":"Filing status","grp":"E","nodes":[5]},{"key":"1-06","part":1,"no":6,"name":"Computation of tax and credits","grp":"F","nodes":[6]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Gross income (inclusions and exclusions)","name":"Gross income (inclusions and exclusions)","vol":34,"q":34,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":2,"title":"Reporting of items from pass-through entities","name":"Reporting of items from pass-through entities","vol":15,"q":15,"cs":0,"law":0,"grp":"B"},{"no":3,"part":1,"ch":3,"title":"Adjustments and deductions to AGI and taxable income","name":"Adjustments and deductions to AGI and taxable income","vol":37,"q":37,"cs":0,"law":0,"grp":"C"},{"no":4,"part":1,"ch":4,"title":"Loss limitations","name":"Loss limitations","vol":26,"q":26,"cs":0,"law":0,"grp":"D"},{"no":5,"part":1,"ch":5,"title":"Filing status","name":"Filing status","vol":18,"q":18,"cs":0,"law":0,"grp":"E"},{"no":6,"part":1,"ch":6,"title":"Computation of tax and credits","name":"Computation of tax and credits","vol":30,"q":30,"cs":0,"law":0,"grp":"F"}],"stat":{"parts":1,"chs":6,"nodes":6,"q":160}};
window.QBANK={"1":[{"i":"REG-IV-A-0001","t":"Nina Ortega, a cash-basis taxpayer, received the following amounts in 2026. Which amount must she include in gross income?","mc":{"s":"Nina Ortega, a cash-basis taxpayer, received the following amounts in 2026. Which amount must she include in gross income?","d":"","o":["A $4,000 cash gift from her aunt","$150,000 of life insurance proceeds paid on the death of her father","$1,200 of interest on a bond issued by her home state's water authority","$3,000 of unemployment compensation paid by her state"],"a":4,"cite":"IRC §61(a); IRC §85(a); Pub 525","rat":"Unemployment compensation is taxable income and is reported on Schedule 1, even though it is a government benefit and not pay for services.","ex":["Gifts are excluded from the recipient's gross income. The donor may owe gift tax, but the recipient does not report the gift.","Life insurance proceeds paid by reason of the insured's death are excluded, unless the policy was transferred for value, which is not the case here.","Interest on state and local government bonds is excluded from regular gross income.","Unemployment compensation is taxable income and is reported on Schedule 1, even though it is a government benefit and not pay for services."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Unemployment compensation is taxable; gifts, life insurance proceeds and state or local bond interest are excluded.","from":"2026-01-01","gd":[["Which receipts are excluded from gross income by statute?","Gifts, life insurance death proceeds, and state and local bond interest."],["Which listed receipt has no exclusion even though it is a government benefit?","Unemployment compensation, which is taxable."]]}},{"i":"REG-IV-A-0002","t":"Leo Brandt earned $58,000 of salary in 2026. His employer also paid $7,000 of his graduate tuition under a written educational assistance program that meets all legal requirements and allows up to $5,250 per year to be excluded. What total amount of these items is included in Leo's gross income?","mc":{"s":"Leo Brandt earned $58,000 of salary in 2026. His employer also paid $7,000 of his graduate tuition under a written educational assistance program that meets all legal requirements and allows up to $5,250 per year to be excluded. What total amount of these items is included in Leo's gross income?","d":"","o":["$52,750","$58,000","$59,750","$65,000"],"a":3,"cite":"IRC §127(a)(2); Pub 15-B; Pub 970","rat":"Employer educational assistance is excluded only up to $5,250.","ex":["Subtracts the exclusion from salary. The exclusion applies to the tuition benefit, and the salary is fully taxable.","Excludes the entire $7,000 of tuition. The exclusion stops at $5,250, so $1,750 is taxable.","Employer educational assistance is excluded only up to $5,250. The $1,750 excess is wages: $58,000 + ($7,000 - $5,250) = $59,750.","Includes the full tuition benefit and ignores the $5,250 exclusion for educational assistance programs."],"wt":["calc","limit","","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Employer educational assistance is excluded only up to $5,250 per year; the excess is wages.","from":"2026-01-01","calc":1,"steps":["Salary 58,000 is fully included","Tuition paid 7,000 - exclusion limit 5,250 = 1,750 included","58,000 + 1,750 = 59,750"],"gd":[["Is the salary fully included?","Yes, 58,000."],["How much tuition assistance is excluded and how much is included?","Exclusion capped at 5,250, so 7,000 - 5,250 = 1,750 is wages."],["What is the total?","58,000 + 1,750 = 59,750."]]}},{"i":"REG-IV-A-0003","t":"Sam Whitfield is a partner in Whitfield & Cole, a calendar-year partnership. For 2026 the partnership paid Sam $40,000 for services, determined without regard to partnership income. Sam's share of partnership ordinary income, after all partnership deductions including that payment, was $15,000. The partnership also distributed $30,000 in cash to Sam during the year. Assume Sam's basis in his partnership interest is sufficient to absorb the distribution. What amount does Sam include in gross income from the partnership for 2026?","mc":{"s":"Sam Whitfield is a partner in Whitfield & Cole, a calendar-year partnership. For 2026 the partnership paid Sam $40,000 for services, determined without regard to partnership income. Sam's share of partnership ordinary income, after all partnership deductions including that payment, was $15,000. The partnership also distributed $30,000 in cash to Sam during the year. Assume Sam's basis in his partnership interest is sufficient to absorb the distribution. What amount does Sam include in gross income from the partnership for 2026?","d":"","o":["$40,000","$55,000","$70,000","$85,000"],"a":2,"cite":"IRC §707(c); IRC §702(a); IRC §731(a); Pub 541","rat":"The guaranteed payment ($40,000) is ordinary income to Sam.","ex":["Counts only the guaranteed payment. The partner is also taxed on the distributive share of partnership income.","The guaranteed payment ($40,000) is ordinary income to Sam. His distributive share ($15,000) is taxed whether or not it is distributed. The $30,000 cash distribution is a return of basis, not income.","Adds the cash distribution to the guaranteed payment. A distribution is not income unless it exceeds the partner's basis.","Also adds the $30,000 distribution. Distributions reduce basis; only the guaranteed payment and the distributive share are taxed."],"wt":["calc","","calc","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A partner is taxed on guaranteed payments and the distributive share; cash distributions reduce basis and are not income.","from":"2026-01-01","calc":1,"steps":["Guaranteed payment 40,000 (ordinary income)","Distributive share 15,000 (taxed as earned by the partnership)","Cash distribution 30,000 is not income (basis recovery)","40,000 + 15,000 = 55,000"],"gd":[["How is the guaranteed payment treated?","Ordinary income of 40,000."],["What about the distributive share and the cash distribution?","The 15,000 share is taxed as earned; the 30,000 distribution is a basis recovery, not income."],["What is the total?","40,000 + 15,000 = 55,000."]]}},{"i":"REG-IV-A-0004","t":"Maria Santos received $900 of interest from a savings account, $1,100 of interest on an Ohio school district bond, and $1,500 of interest on a qualified private activity bond issued by an Ohio airport authority. The private activity bond interest is exempt from regular income tax but is an AMT preference item. What amount of interest is included in Maria's 2026 regular taxable income?","mc":{"s":"Maria Santos received $900 of interest from a savings account, $1,100 of interest on an Ohio school district bond, and $1,500 of interest on a qualified private activity bond issued by an Ohio airport authority. The private activity bond interest is exempt from regular income tax but is an AMT preference item. What amount of interest is included in Maria's 2026 regular taxable income?","d":"","o":["$900","$2,000","$2,400","$3,500"],"a":1,"cite":"IRC §103(a); IRC §57(a)(5); Pub 550","rat":"Only the bank interest is taxable.","ex":["Only the bank interest is taxable. Interest on state and local bonds, including qualified private activity bonds, is excluded for regular tax; the private activity bond interest matters only for the AMT.","Includes the school district bond interest. Interest on state and local government bonds is excluded from gross income.","Includes the private activity bond interest. It is excluded from regular tax and is only a preference item for the AMT.","Treats all interest as taxable. Bank interest is taxable, but interest on state and local bonds is excluded."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Interest on state and local bonds, including private activity bonds, is excluded from regular income; private activity bond interest is only an AMT preference.","from":"2026-01-01","calc":1,"steps":["Bank interest 900 is taxable","School district bond interest 1,100 is excluded","Private activity bond interest 1,500 is excluded for regular tax (AMT preference)","Taxable = 900"],"gd":[["Which of the three interest items is taxable for regular tax?","Only the bank interest of 900."],["What about the school district bond and the private activity bond?","Both are excluded for regular tax; the private activity bond is only an AMT preference item."]]}},{"i":"REG-IV-A-0005","t":"Rina Kapoor, age 68, began receiving $800 per month from a commercial annuity in 2025. She bought the annuity with $48,000 of after-tax money, and her expected return under the IRS tables is $80,000. She received $9,600 during 2026. What amount of the 2026 payments is included in gross income?","mc":{"s":"Rina Kapoor, age 68, began receiving $800 per month from a commercial annuity in 2025. She bought the annuity with $48,000 of after-tax money, and her expected return under the IRS tables is $80,000. She received $9,600 during 2026. What amount of the 2026 payments is included in gross income?","d":"","o":["$0","$3,840","$5,760","$9,600"],"a":2,"cite":"IRC §72(b); Pub 575","rat":"The exclusion ratio is $48,000 / $80,000 = 60%.","ex":["Treats all payments as a recovery of her $48,000 investment first. That basis-first rule applies only to annuities that started before 1987.","The exclusion ratio is $48,000 / $80,000 = 60%. Excluded: $9,600 x 60% = $5,760. Taxable: $9,600 - $5,760 = $3,840.","This is the excluded portion ($5,760), not the taxable portion.","Treats every payment as taxable. Part of each payment is a tax-free return of the after-tax investment."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An annuity's taxable part is the payment less the exclusion ratio of investment divided by expected return.","from":"2026-01-01","calc":1,"steps":["Exclusion ratio = 48,000 / 80,000 = 60%","Excluded = 9,600 x 60% = 5,760","Taxable = 9,600 - 5,760 = 3,840"],"gd":[["What is the exclusion ratio?","48,000 / 80,000 = 60%."],["How much of the 9,600 is excluded?","9,600 x 60% = 5,760."],["What is taxable?","9,600 - 5,760 = 3,840."]]}},{"i":"REG-IV-A-0006","t":"Robert Hale, a single taxpayer, received $20,000 of Social Security benefits in 2026. His other income included in AGI was $30,000, and he also received $2,000 of tax-exempt municipal bond interest. What amount of his Social Security benefits is included in gross income?","mc":{"s":"Robert Hale, a single taxpayer, received $20,000 of Social Security benefits in 2026. His other income included in AGI was $30,000, and he also received $2,000 of tax-exempt municipal bond interest. What amount of his Social Security benefits is included in gross income?","d":"","o":["$6,800","$10,000","$11,300","$17,000"],"a":3,"cite":"IRC §86(a), (c); Pub 915","rat":"Provisional income = $30,000 + $2,000 + 50% x $20,000 = $42,000.","ex":["Applies 85% only to provisional income above $34,000 and omits the first tier of $4,500 taxed at 50%.","Includes just 50% of benefits, which is the maximum only when provisional income is between the $25,000 and $34,000 base amounts.","Provisional income = $30,000 + $2,000 + 50% x $20,000 = $42,000. Above $34,000 the taxable amount is the lesser of 85% of benefits or: lesser of 50% of benefits or $4,500, plus 85% x ($42,000 - $34,000) = $4,500 + $6,800 = $11,300.","Includes the maximum 85%. His provisional income is not high enough to reach the 85% cap."],"wt":["calc","limit","","limit"],"tags":{"area":"IV","group":"A","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Social Security benefits are taxable up to 85% based on provisional income and the $25,000 and $34,000 base amounts.","from":"2026-01-01","calc":1,"steps":["Provisional income = 30,000 + 2,000 + 10,000 = 42,000","Tier 1 = lesser of 50% x 20,000 = 10,000 or 50% x (34,000 - 25,000) = 4,500","Tier 2 = 85% x (42,000 - 34,000) = 6,800","4,500 + 6,800 = 11,300 (below the 85% cap of 17,000)"],"gd":[["What is provisional income?","30,000 + 2,000 + 50% x 20,000 = 42,000."],["What is the first-tier amount for a single filer and the second tier?","4,500 for the first tier, and 85% x (42,000 - 34,000) = 6,800."],["What is the taxable benefit?","4,500 + 6,800 = 11,300, below the 17,000 cap."]]}},{"i":"REG-IV-A-0007","t":"Dan Roe's credit card issuer canceled $20,000 of his debt in 2026 and issued a Form 1099-C. Immediately before the cancellation, Dan's liabilities totaled $162,000 and the fair market value of his assets totaled $150,000. Dan was not in bankruptcy. What amount of canceled debt must Dan include in 2026 gross income?","mc":{"s":"Dan Roe's credit card issuer canceled $20,000 of his debt in 2026 and issued a Form 1099-C. Immediately before the cancellation, Dan's liabilities totaled $162,000 and the fair market value of his assets totaled $150,000. Dan was not in bankruptcy. What amount of canceled debt must Dan include in 2026 gross income?","d":"","o":["$0","$8,000","$12,000","$20,000"],"a":2,"cite":"IRC §61(a)(11); IRC §108(a)(1)(B), (a)(3); Pub 4681","rat":"Canceled debt is income unless an exclusion applies.","ex":["Excludes the entire $20,000. The insolvency exclusion is limited to the amount by which liabilities exceed the fair market value of assets ($12,000).","Canceled debt is income unless an exclusion applies. Dan was insolvent by $12,000 immediately before the cancellation, so he may exclude up to $12,000. Income = $20,000 - $12,000 = $8,000.","This is the amount of the insolvency, which is the excluded amount, not the amount included.","Includes the full canceled amount and ignores the insolvency exclusion."],"wt":["limit","","calc","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Canceled debt is income except to the extent of insolvency immediately before cancellation.","from":"2026-01-01","calc":1,"steps":["Insolvency = 162,000 - 150,000 = 12,000","Exclusion = lesser of 20,000 or 12,000 = 12,000","Included = 20,000 - 12,000 = 8,000"],"gd":[["What is Dan's insolvency amount?","162,000 - 150,000 = 12,000."],["How much may be excluded?","The lesser of 20,000 canceled or 12,000 insolvency, so 12,000."],["What is included?","20,000 - 12,000 = 8,000."]]}},{"i":"REG-IV-A-0008","t":"Which of the following amounts received in settlement of a lawsuit may be excluded from the recipient's gross income?","mc":{"s":"Which of the following amounts received in settlement of a lawsuit may be excluded from the recipient's gross income?","d":"","o":["Punitive damages awarded in the same physical injury case","Back pay received in an employment discrimination settlement","Damages for emotional distress from a defamation claim with no physical injury","Compensatory damages for medical costs and pain caused by a physical injury in a car accident"],"a":4,"cite":"IRC §104(a)(2); Pub 525","rat":"Damages received on account of personal physical injury or physical sickness are excluded, whether received as a lump sum or as periodic payments.","ex":["Punitive damages are taxable, even when the underlying claim is for a physical injury.","Back pay replaces wages and is taxable as wages, not as damages for physical injury.","Emotional distress is not a physical injury. Such damages are taxable, except for the amount that reimburses medical care for the distress.","Damages received on account of personal physical injury or physical sickness are excluded, whether received as a lump sum or as periodic payments."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Damages for personal physical injury or sickness are excluded; punitive, back pay and non-physical emotional distress damages are taxable.","from":"2026-01-01","gd":[["Which settlement amounts are excluded?","Damages received on account of personal physical injury or physical sickness."],["Which listed receipt is that?","Compensatory damages for medical costs and pain from a car-accident injury; punitive, back pay and non-physical emotional distress are taxable."]]}},{"i":"REG-IV-A-0009","t":"Kay Morgan was seriously injured in a collision with a delivery truck. In 2026 she received a judgment of $100,000 consisting of $60,000 compensatory damages for her physical injuries, $25,000 punitive damages, and $15,000 of interest on the judgment. What amount must Kay include in gross income for 2026?","mc":{"s":"Kay Morgan was seriously injured in a collision with a delivery truck. In 2026 she received a judgment of $100,000 consisting of $60,000 compensatory damages for her physical injuries, $25,000 punitive damages, and $15,000 of interest on the judgment. What amount must Kay include in gross income for 2026?","d":"","o":["$15,000","$25,000","$40,000","$100,000"],"a":3,"cite":"IRC §104(a)(2); Reg §1.104-1(c); Pub 525","rat":"Compensatory damages for physical injury are excluded.","ex":["Includes only the interest. Punitive damages are also taxable.","Includes only punitive damages. Interest on a judgment is taxable as well.","Compensatory damages for physical injury are excluded. Punitive damages ($25,000) and interest on the judgment ($15,000) are taxable: $40,000.","Includes the compensatory damages, which are excluded because they are received on account of physical injury."],"wt":["calc","calc","","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Compensatory damages for physical injury are excluded, but punitive damages and interest on the judgment are taxable.","from":"2026-01-01","calc":1,"steps":["Compensatory 60,000: excluded","Punitive 25,000 + interest 15,000: included","25,000 + 15,000 = 40,000"],"gd":[["Which parts of the judgment are excluded?","Compensatory damages for physical injury, 60,000."],["Which parts are taxable?","Punitive damages 25,000 and interest 15,000."],["What is the total inclusion?","25,000 + 15,000 = 40,000."]]}},{"i":"REG-IV-A-0010","t":"Ken Ruiz bought 500 shares of stock on January 20, 2025 for $20,000 and sold all of the shares on March 25, 2026 for $28,000. How should Ken report the sale?","mc":{"s":"Ken Ruiz bought 500 shares of stock on January 20, 2025 for $20,000 and sold all of the shares on March 25, 2026 for $28,000. How should Ken report the sale?","d":"","o":["An $8,000 short-term capital gain","An $8,000 ordinary gain","A $28,000 long-term capital gain","An $8,000 long-term capital gain"],"a":4,"cite":"IRC §1222(3); IRC §1001(a); Pub 550","rat":"Ken held the shares for more than one year (about 14 months), so the $8,000 gain ($28,000 - $20,000) is long-term.","ex":["Short-term applies only to a holding period of one year or less. Ken held the shares for about 14 months.","Gain on investment stock is a capital gain, not ordinary income.","Uses the sales price as the gain. Gain is the amount realized less adjusted basis.","Ken held the shares for more than one year (about 14 months), so the $8,000 gain ($28,000 - $20,000) is long-term."],"wt":["limit","concept","calc",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Stock held more than one year produces long-term capital gain equal to amount realized less basis.","from":"2026-01-01","gd":[["How long was the stock held?","From January 20, 2025 to March 25, 2026, more than a year."],["What is the gain and its character?","28,000 - 20,000 = 8,000, long-term."]]}},{"i":"REG-IV-A-0011","t":"Alicia Torres inherited 300 shares of stock when her uncle died on June 1, 2026. Her uncle's basis was $12,000, and the shares were worth $50,000 on the date of death. Alicia sold all of the shares on August 15, 2026 for $54,000. How should she report the sale?","mc":{"s":"Alicia Torres inherited 300 shares of stock when her uncle died on June 1, 2026. Her uncle's basis was $12,000, and the shares were worth $50,000 on the date of death. Alicia sold all of the shares on August 15, 2026 for $54,000. How should she report the sale?","d":"","o":["A $4,000 short-term capital gain","A $42,000 long-term capital gain","A $42,000 short-term capital gain","A $4,000 long-term capital gain"],"a":4,"cite":"IRC §1014(a); IRC §1223(9); Pub 551","rat":"Inherited property takes the date-of-death value ($50,000) as basis and is treated as long-term regardless of how long the heir held it: $54,000 - $50,000 = $4,000 long-term.","ex":["Uses the right gain but the wrong holding period. Property acquired from a decedent is automatically long-term.","Uses the uncle's $12,000 basis. Inherited property generally takes a basis equal to fair market value at death.","Makes both errors: it carries over the decedent's basis and treats the holding period as only a few months.","Inherited property takes the date-of-death value ($50,000) as basis and is treated as long-term regardless of how long the heir held it: $54,000 - $50,000 = $4,000 long-term."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Inherited property takes FMV at death as basis and is automatically long-term.","from":"2026-01-01","gd":[["What basis does an heir take?","Date-of-death value, 50,000."],["What is the holding period treatment?","Long-term regardless of how long the heir held it."],["What is the result?","54,000 - 50,000 = 4,000 long-term gain."]]}},{"i":"REG-IV-A-0012","t":"Wen Zhao received 1,000 shares of stock as a gift from her father in 2026. Her father's adjusted basis was $50,000, and the fair market value on the gift date was $30,000. No gift tax was paid. Wen later sold all the shares in 2026 for $26,000. What loss does Wen recognize on the sale?","mc":{"s":"Wen Zhao received 1,000 shares of stock as a gift from her father in 2026. Her father's adjusted basis was $50,000, and the fair market value on the gift date was $30,000. No gift tax was paid. Wen later sold all the shares in 2026 for $26,000. What loss does Wen recognize on the sale?","d":"","o":["$4,000","$20,000","$24,000","$26,000"],"a":1,"cite":"IRC §1015(a); Reg §1.1015-1(a)(2); Pub 551","rat":"For a loss, the donee's basis is the lower of the donor's basis or fair market value at the gift date: $30,000.","ex":["For a loss, the donee's basis is the lower of the donor's basis or fair market value at the gift date: $30,000. Loss = $30,000 - $26,000 = $4,000.","This is the built-in loss ($20,000) at the gift date, which stays with the donor's basis and is never recognized by the donee.","Uses the donor's $50,000 basis. That carryover basis applies only for computing gain, not loss, when value has declined.","Reports the entire sale price as the loss. The loss is the basis, as limited, less the amount realized."],"wt":["","concept","concept","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A donee's loss basis is the lower of the donor's basis or FMV at the gift date.","from":"2026-01-01","calc":1,"steps":["Sale price 26,000 is below FMV at gift 30,000 and below donor basis 50,000","Loss basis = lower of 50,000 or 30,000 = 30,000","Loss = 30,000 - 26,000 = 4,000"],"gd":[["Which basis applies to a loss on gift property when FMV is below the donor's basis?","The lower of the donor's basis or FMV at the gift date, 30,000."],["What is the loss?","30,000 - 26,000 = 4,000."]]}},{"i":"REG-IV-A-0013","t":"Bea Lindgren bought 2 units of a virtual currency for $10,000 in total ($5,000 each) in 2025. In 2026, when one unit was worth $9,000, she used that unit to buy furniture for her home. What gain must Bea report on the transaction?","mc":{"s":"Bea Lindgren bought 2 units of a virtual currency for $10,000 in total ($5,000 each) in 2025. In 2026, when one unit was worth $9,000, she used that unit to buy furniture for her home. What gain must Bea report on the transaction?","d":"","o":["$0","$4,000","$5,000","$9,000"],"a":2,"cite":"IRC §1001(a); IRC §1222(3); Notice 2014-21; Pub 544","rat":"Virtual currency is property.","ex":["There is no exception for using virtual currency on personal purchases. The disposition is taxable even though the furniture is personal.","Virtual currency is property. Paying for a personal purchase with it is a sale or exchange: amount realized $9,000 less basis $5,000 = $4,000 long-term gain (held over one year).","Reports the cost of the unit as the gain. Gain is the value received less the cost.","Reports the value received as gain and ignores the $5,000 basis in the unit used."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Paying for a personal purchase with virtual currency is a taxable disposition of property; gain is value received less basis.","from":"2026-01-01","calc":1,"steps":["Basis of the unit used = 10,000 / 2 = 5,000","Amount realized = fair market value of the unit, 9,000","Gain = 9,000 - 5,000 = 4,000, long-term"],"gd":[["What is virtual currency for tax purposes and what is the basis of the unit spent?","Property; 10,000 / 2 = 5,000."],["What is the amount realized in buying furniture?","The unit's FMV, 9,000."],["What is the gain and its character?","9,000 - 5,000 = 4,000, long-term."]]}},{"i":"REG-IV-A-0014","t":"Marta Ibarra inherited a duplex from her aunt in 2026. The duplex was worth $300,000 on the date of death. Marta rented it out and collected $8,000 of rent for the rest of the year. Ignore any rental deductions. What amount does Marta include in 2026 gross income for the duplex?","mc":{"s":"Marta Ibarra inherited a duplex from her aunt in 2026. The duplex was worth $300,000 on the date of death. Marta rented it out and collected $8,000 of rent for the rest of the year. Ignore any rental deductions. What amount does Marta include in 2026 gross income for the duplex?","d":"","o":["$0","$8,000","$300,000","$308,000"],"a":2,"cite":"IRC §102(a); IRC §61(a)(5); Pub 525","rat":"Property received by inheritance is excluded from gross income, but income the property later produces, such as rent, is taxable: $8,000.","ex":["Excludes the rent too. Only the inheritance itself is excluded; later income from the property is taxable.","Property received by inheritance is excluded from gross income, but income the property later produces, such as rent, is taxable: $8,000.","Includes the value of the inherited property, which is excluded from gross income.","Includes both the inheritance and the rent. The inheritance is excluded."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Inheritance is excluded from gross income, but rent the inherited property produces afterward is taxable.","from":"2026-01-01","gd":[["Is inherited property itself income?","No, it is excluded."],["Is the rent it produces income?","Yes, the 8,000 of rent is taxable."]]}},{"i":"REG-IV-A-0015","t":"Carla Denton's father died in 2026. Carla, the beneficiary of his $90,000 life insurance policy, chose to receive the proceeds in ten equal annual installments of $10,000. The insurer credits extra amounts, which are the interest, so each installment is $1,000 more than one-tenth of the proceeds. She received the first installment in 2026. What amount must Carla include in gross income for 2026?","mc":{"s":"Carla Denton's father died in 2026. Carla, the beneficiary of his $90,000 life insurance policy, chose to receive the proceeds in ten equal annual installments of $10,000. The insurer credits extra amounts, which are the interest, so each installment is $1,000 more than one-tenth of the proceeds. She received the first installment in 2026. What amount must Carla include in gross income for 2026?","d":"","o":["$0","$1,000","$9,000","$10,000"],"a":2,"cite":"IRC §101(a), (d); Pub 525","rat":"The proration excludes $9,000 of each installment as death benefit.","ex":["Excludes the interest. Life insurance proceeds are excluded, but interest earned on proceeds held by the insurer is taxable.","The proration excludes $9,000 of each installment as death benefit. The $1,000 extra is interest and is taxable.","Includes the death benefit part and excludes the interest, which reverses the rule.","Includes the whole installment. Only the interest element is taxable."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Life insurance proceeds are excluded, but interest added to installment payments is taxable.","from":"2026-01-01","calc":1,"steps":["Excluded part of each installment = 90,000 / 10 = 9,000","Interest element = 10,000 - 9,000 = 1,000","Included in 2026 = 1,000"],"gd":[["How much of each installment is the excluded death benefit?","90,000 / 10 = 9,000."],["What is the interest element in the first installment?","10,000 - 9,000 = 1,000."],["What is included in 2026?","1,000."]]}},{"i":"REG-IV-A-0016","t":"Ed Marlow, a cash-basis taxpayer, died on September 30, 2026. Through that date he had received $70,000 of salary. In November 2026, his employer paid Ed's estate $6,000 of wages that Ed had earned but had not been paid before death. What amount of these items is reported on Ed's final Form 1040 for 2026?","mc":{"s":"Ed Marlow, a cash-basis taxpayer, died on September 30, 2026. Through that date he had received $70,000 of salary. In November 2026, his employer paid Ed's estate $6,000 of wages that Ed had earned but had not been paid before death. What amount of these items is reported on Ed's final Form 1040 for 2026?","d":"","o":["$0","$6,000","$70,000","$76,000"],"a":3,"cite":"IRC §451(a); IRC §691(a); Pub 559","rat":"A cash-basis decedent reports only income actually or constructively received before death: $70,000.","ex":["Reports nothing, but the $70,000 of salary already received is income on the final return.","Reports only the unpaid wages. Those are income in respect of a decedent taxed to the estate, not to Ed.","A cash-basis decedent reports only income actually or constructively received before death: $70,000. The $6,000 is income in respect of a decedent, taxed to the estate or heir who receives it.","Accrues the $6,000 on the final return. A cash-basis decedent does not report income received after death."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A cash-basis decedent's final return reports only income received before death; later wages are income in respect of a decedent taxed to the recipient.","from":"2026-01-01","calc":1,"steps":["Final return: income received through 9/30 = 70,000","Wages paid after death = income in respect of a decedent (estate or heir reports 6,000)"],"gd":[["What does a cash-basis decedent's final return report?","Income actually or constructively received before death, 70,000."],["How is the later wage payment classified?","Income in respect of a decedent, reported by the estate or heir, so 6,000 stays off the final return."]]}},{"i":"REG-IV-A-0017","t":"Frank Tull, a cash-basis taxpayer, sold land he had held as an investment for four years under an installment sale and reported long-term capital gain on the payments he received. He died before collecting the last installment, and his estate collected it. How does the estate treat the gain in that installment?","mc":{"s":"Frank Tull, a cash-basis taxpayer, sold land he had held as an investment for four years under an installment sale and reported long-term capital gain on the payments he received. He died before collecting the last installment, and his estate collected it. How does the estate treat the gain in that installment?","d":"","o":["As ordinary income, because it is income in respect of a decedent","As short-term capital gain, because the estate held the note only a short time","As excluded income, because the note received a stepped-up basis at death","As long-term capital gain, the same character it would have had in Frank's hands"],"a":4,"cite":"IRC §691(a)(3); IRC §1014(c); Pub 559","rat":"Income in respect of a decedent keeps the character it would have had if the decedent had lived, so the installment gain remains long-term capital gain.","ex":["IRD is not automatically ordinary. Its character follows the character it would have had for the decedent.","The estate does not restart the holding period. The character is determined as if the decedent had received the payment.","Installment notes are IRD assets and do not get a basis step-up. The estate or heir reports the gain as it is collected.","Income in respect of a decedent keeps the character it would have had if the decedent had lived, so the installment gain remains long-term capital gain."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Income in respect of a decedent keeps the character it would have had for the decedent and gets no basis step-up.","from":"2026-01-01","gd":[["What is the installment note gain when collected by an estate called?","Income in respect of a decedent."],["What character does it keep?","The character it would have had for the decedent, so long-term capital gain."]]}},{"i":"REG-IV-A-0018","t":"Gina Pratt divorced in 2022 under a decree that requires her former spouse to pay $1,500 per month of alimony and $800 per month of child support. She received all payments in 2026. What amount of these payments is included in Gina's 2026 gross income?","mc":{"s":"Gina Pratt divorced in 2022 under a decree that requires her former spouse to pay $1,500 per month of alimony and $800 per month of child support. She received all payments in 2026. What amount of these payments is included in Gina's 2026 gross income?","d":"","o":["$0","$9,600","$18,000","$27,600"],"a":1,"cite":"IRC §61(a)(8) (repealed by P.L. 115-97 for post-2018 instruments); Pub 504; IRC §71 (pre-2019 instruments)","rat":"For divorce instruments executed after 2018, alimony is neither deductible by the payer nor included in the recipient's income.","ex":["For divorce instruments executed after 2018, alimony is neither deductible by the payer nor included in the recipient's income. Child support is never income. Neither payment is included.","Includes only the child support. Child support is never included in the recipient's income.","Includes the alimony as under pre-2019 divorce rules. Alimony under a post-2018 instrument is not taxable to the recipient.","Includes both payments. Neither alimony under a post-2018 instrument nor child support is income to the recipient."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"For divorce instruments after 2018, alimony is not income to the recipient, and child support never is.","from":"2026-01-01","calc":1,"steps":["Decree date 2022 = after 2018: alimony not included","Child support is never included","Included amount = 0"],"gd":[["Is alimony taxable under a decree executed after 2018?","No, neither deductible by the payer nor income to the recipient."],["What about child support?","Never income, so the included amount is 0."]]}},{"i":"REG-IV-A-0019","t":"Hal Perez, a plumber, repaired the pipes in a dentist's office in 2026 in exchange for dental work. Both services would normally cost $1,200. What amount must Hal include in gross income from the exchange?","mc":{"s":"Hal Perez, a plumber, repaired the pipes in a dentist's office in 2026 in exchange for dental work. Both services would normally cost $1,200. What amount must Hal include in gross income from the exchange?","d":"","o":["$0","$600","$1,200","$2,400"],"a":3,"cite":"Reg §1.61-2(d)(1); Pub 525","rat":"Bartering creates income equal to the fair market value of the property or services received: $1,200.","ex":["No cash changed hands, but barter income is taxable at the fair market value of what is received.","Splits the value between the two parties. Each party reports the full value of what he receives.","Bartering creates income equal to the fair market value of the property or services received: $1,200.","Adds the value of both services. Hal reports only the dental work he received."],"wt":["concept","calc","","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Bartering income equals the FMV of the property or services received.","from":"2026-01-01","gd":[["Is barter income?","Yes."],["How is the amount measured?","At the FMV of what is received, 1,200 of dental work."]]}},{"i":"REG-IV-A-0020","t":"Two students each received a $6,000 scholarship in 2026. Ann, a degree candidate at a university, used hers entirely for tuition and required books. Bob, also a degree candidate, used his entirely for room and board. What is the tax treatment of the two scholarships?","mc":{"s":"Two students each received a $6,000 scholarship in 2026. Ann, a degree candidate at a university, used hers entirely for tuition and required books. Bob, also a degree candidate, used his entirely for room and board. What is the tax treatment of the two scholarships?","d":"","o":["Both students exclude the full amount","Both students include the full amount","Ann includes hers; Bob excludes his","Ann excludes hers; Bob includes his"],"a":4,"cite":"IRC §117(a), (b); Pub 970","rat":"A degree candidate excludes the part of a scholarship used for tuition, fees, books, and required supplies.","ex":["Room and board is a personal cost that is not a qualified education expense, so Bob's scholarship is taxable.","Ann's scholarship is used for qualified tuition and required books, so it is excluded.","Reverses the rule. Qualified education expenses are excluded; room and board is not.","A degree candidate excludes the part of a scholarship used for tuition, fees, books, and required supplies. Amounts used for room and board are taxable."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Scholarship amounts used for tuition, fees, books and required supplies are excluded; amounts for room and board are taxable.","from":"2026-01-01","gd":[["Which scholarship uses are excluded for a degree candidate?","Tuition, fees, books and required supplies."],["How do the two students' uses compare?","Ann used it all for tuition and books, so she excludes it; Bob used it for room and board, so he includes it."]]}},{"i":"REG-IV-A-0021","t":"Priya, an employee, received two items from her employer in December 2026. First, a $100 holiday turkey given to all employees. Second, a $100 gift card redeemable at any store, also given to all employees. How should Priya treat the items?","mc":{"s":"Priya, an employee, received two items from her employer in December 2026. First, a $100 holiday turkey given to all employees. Second, a $100 gift card redeemable at any store, also given to all employees. How should Priya treat the items?","d":"","o":["Both items are excluded as de minimis fringe benefits","Both items are included in wages","The gift card is excluded and the turkey is included in wages","The turkey is excluded as a de minimis fringe benefit; the gift card is included in wages"],"a":4,"cite":"IRC §132(a)(4), (e)(1); Reg §1.132-6; Pub 15-B","rat":"Occasional low-value property such as a holiday turkey is a de minimis fringe benefit.","ex":["Cash equivalents, including general-use gift cards, are always taxable regardless of amount.","The turkey is a small item of property that is difficult to account for, so it qualifies as a de minimis fringe benefit.","Reverses the rule. Cash equivalents are taxable; occasional low-value property is not.","Occasional low-value property such as a holiday turkey is a de minimis fringe benefit. Cash and cash equivalents such as general gift cards are never de minimis and are taxable wages."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Occasional low-value property is a de minimis fringe benefit, but cash and cash equivalents such as general gift cards are taxable wages.","from":"2026-01-01","gd":[["What makes a fringe benefit de minimis?","Occasional, low-value property or services that are hard to account for."],["Which item can never be de minimis?","Cash and cash equivalents such as a general gift card, which are taxable wages; the holiday turkey is de minimis."]]}},{"i":"REG-IV-A-0022","t":"Which of the following is included in the gross income of an individual who receives it in 2026?","mc":{"s":"Which of the following is included in the gross income of an individual who receives it in 2026?","d":"","o":["A $2,500 birthday gift from a grandparent","A $2,500 inheritance from a great-aunt's will","A $2,500 reimbursement of an employee's business travel under an accountable plan","A $2,500 prize won on a television game show"],"a":4,"cite":"IRC §74(a); IRC §102(a); Pub 525","rat":"Prizes and awards, including game show winnings, are included in gross income at fair market value.","ex":["Gifts are excluded from the recipient's gross income.","Property received by inheritance is excluded from gross income.","Reimbursements under an accountable plan are not wages and are excluded.","Prizes and awards, including game show winnings, are included in gross income at fair market value."],"wt":["trap","trap","trap",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Prizes and game show winnings are included in gross income, while gifts, inheritances and accountable plan reimbursements are excluded.","from":"2026-01-01","gd":[["Which receipts are excluded?","Gifts, inheritances, and accountable plan reimbursements."],["Which receipt is a prize with no exclusion?","The game show prize, included at FMV."]]}},{"i":"REG-IV-A-0023","t":"Owen Blake, a cash-basis taxpayer, receives a $5,000 bonus on January 3, 2027 for work performed in 2026. The bonus check was available to him on December 30, 2026 in his employer's payroll office, but Owen chose not to pick it up until January 3. In which year is the bonus income?","mc":{"s":"Owen Blake, a cash-basis taxpayer, receives a $5,000 bonus on January 3, 2027 for work performed in 2026. The bonus check was available to him on December 30, 2026 in his employer's payroll office, but Owen chose not to pick it up until January 3. In which year is the bonus income?","d":"","o":["2027, because Owen did not receive the check until January 3","2026 and 2027, split equally, because the work was in 2026 and payment in 2027","2027, because the bonus was earned by services performed in 2026","2026, because the bonus was constructively received when it was made available"],"a":4,"cite":"IRC §451(a); Reg §1.451-2(a); Pub 538","rat":"Under constructive receipt, a cash-basis taxpayer reports income when it is credited or set apart and available without substantial restriction, even if he does not take possession.","ex":["A cash-basis taxpayer cannot postpone income by choosing not to collect an amount that is available to him.","Income is not allocated by service period. It is reported in the year actually or constructively received.","The year the work was performed is irrelevant to a cash-basis taxpayer. Receipt controls.","Under constructive receipt, a cash-basis taxpayer reports income when it is credited or set apart and available without substantial restriction, even if he does not take possession."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A cash-basis taxpayer reports income when it is constructively received, meaning available without substantial restriction.","from":"2026-01-01","gd":[["What is the constructive receipt test for a cash-basis taxpayer?","Income is reported when credited or set apart and available without substantial restriction."],["Was the check available on December 30?","Yes, and Owen simply chose not to pick it up, so the income belongs to 2026."]]}},{"i":"REG-IV-A-0024","t":"Kyle, a self-employed web designer, completed a project in 2026 for a customer who paid him in virtual currency worth $2,000 on the date he received it. Which statement about how Kyle reports the payment is correct?","mc":{"s":"Kyle, a self-employed web designer, completed a project in 2026 for a customer who paid him in virtual currency worth $2,000 on the date he received it. Which statement about how Kyle reports the payment is correct?","d":"","o":["He reports nothing until he converts the currency to U.S. dollars","He reports it as a long-term capital gain, because virtual currency is property","He reports it as wages subject to withholding, because the customer is an employer","He reports the fair market value in U.S. dollars of the currency, on the date received, as self-employment income"],"a":4,"cite":"IRC §61(a)(1); Notice 2014-21; Pub 544","rat":"Virtual currency received for services is income at its fair market value on the receipt date.","ex":["Income is recognized when the currency is received, not when it is converted.","Receiving currency for services is ordinary compensation. Capital gain arises only on a later sale or exchange of the currency.","Kyle is an independent contractor, so the income is self-employment income reported on Schedule C, not wages.","Virtual currency received for services is income at its fair market value on the receipt date. The value becomes the basis in the currency."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Virtual currency received for services is self-employment income at its FMV on the receipt date.","from":"2026-01-01","gd":[["How is virtual currency received for services treated?","As income at its FMV on the date received."],["What type of income is it for a self-employed designer?","Self-employment income of 2,000, and that value becomes the basis in the currency."]]}},{"i":"REG-IV-A-0025","t":"Review the exhibit, which compares Kevin Shah's source documents with his draft 2026 Form 1040. Which correction is required?","mc":{"s":"Review the exhibit, which compares Kevin Shah's source documents with his draft 2026 Form 1040. Which correction is required?","d":"","o":["Add $800 to taxable interest","Increase wages by $3,000 of 401(k) elective deferrals","Reduce interest by $1,200 because the bank is in another state","Add $4,000 of unemployment compensation to income"],"a":4,"cite":"IRC §85(a); IRC §61(a)(4); Pub 525","rat":"Form 1099-G box 1 unemployment compensation is taxable and is missing from the draft return.","ex":["Box 8 is tax-exempt interest, which is excluded from taxable interest. The draft correctly leaves it out, although it is reported on the return as a memo item.","Box 1 of the Form W-2 already excludes elective deferrals. The draft wages match box 1, which is correct.","Interest on bank deposits is taxable regardless of where the bank is located.","Form 1099-G box 1 unemployment compensation is taxable and is missing from the draft return."],"wt":["trap","trap","trap",""],"tags":{"area":"IV","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Form 1099-G unemployment compensation is taxable and must be reported, while tax-exempt interest and 401(k) deferrals are already excluded correctly.","tb":[["Source document","Amount","Draft 1040"],["W-2 box 1 (wages; box 12 code D shows $3,000 401(k) deferral)","$65,000","Wages: $65,000"],["1099-INT box 1 (taxable interest)","$1,200","Interest: $1,200"],["1099-INT box 8 (tax-exempt interest)","$800","Not in taxable interest"],["1099-G box 1 (unemployment compensation)","$4,000","Not reported"]],"from":"2026-01-01","gd":[["Which source document shows a taxable item missing from the draft?","The 1099-G showing 4,000 in box 1 that the draft omits."],["Are the tax-exempt interest and the 401(k) deferral to be added?","No, both are outside taxable interest and already excluded from box 1 wages, so the unemployment compensation must be added."]]}},{"i":"REG-IV-A-0026","t":"Review the exhibit for Marcus Bell's 2026 return. Which statement identifies the correct treatment of the distribution from his employer's 401(k) plan?","mc":{"s":"Review the exhibit for Marcus Bell's 2026 return. Which statement identifies the correct treatment of the distribution from his employer's 401(k) plan?","d":"","o":["The taxable amount is $30,000, and a 10% additional tax also applies because Marcus is under 59 1/2","The taxable amount is $30,000, but the 10% additional tax is waived because of the rollover","The taxable amount is $15,000, because only half of a rollover is tax-free","The taxable amount is $0, because the distribution was a direct rollover from the plan to an IRA"],"a":4,"cite":"IRC §402(c); IRC §408(d)(3); Pub 575","rat":"A direct rollover from a qualified plan to an IRA is not a taxable distribution.","ex":["A rollover made directly from the plan to an IRA is not taxable and does not trigger the early distribution additional tax.","The rollover means there is no taxable distribution at all. The 10% tax is not the issue.","There is no partial exclusion for rollovers. A rollover is tax-free in full.","A direct rollover from a qualified plan to an IRA is not a taxable distribution. Code G in box 7 identifies a direct rollover to an IRA or another eligible plan."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A direct rollover from a qualified plan to an IRA is not a taxable distribution and draws no early distribution tax.","tb":[["Form 1099-R item","Amount / entry"],["Box 1 gross distribution","$30,000"],["Box 2a taxable amount","$30,000 (taxable amount not determined box checked)"],["Box 7 distribution code","G (direct rollover to an IRA)"],["Draft 1040 line 5b (pensions and annuities, taxable)","$30,000"]],"from":"2026-01-01","gd":[["What does code G in box 7 mean?","A direct rollover to an IRA or another eligible plan."],["What is the taxable amount?","0, since a direct rollover is not a taxable distribution and no additional tax applies."]]}},{"i":"REG-IV-A-0027","t":"An automated check flags a mismatch on Priscilla Wong's 2026 return: her Form 1099-B shows $48,000 of proceeds from stock she held for three years, and the basis box is blank (noncovered security). Her brokerage statements and purchase confirmations show she paid $40,000. The draft Schedule D reports no sale. What gain should the corrected Schedule D report?","mc":{"s":"An automated check flags a mismatch on Priscilla Wong's 2026 return: her Form 1099-B shows $48,000 of proceeds from stock she held for three years, and the basis box is blank (noncovered security). Her brokerage statements and purchase confirmations show she paid $40,000. The draft Schedule D reports no sale. What gain should the corrected Schedule D report?","d":"","o":["$0","$8,000","$40,000","$48,000"],"a":2,"cite":"IRC §1001(a); IRC §6045(g); Pub 550","rat":"The IRS has the proceeds, so the sale must be reported.","ex":["Keeps the draft. The 1099-B proceeds were reported to the IRS, so omitting the sale creates a mismatch and understated income.","The IRS has the proceeds, so the sale must be reported. Basis is not reported for a noncovered security, so Priscilla reports the documented $40,000: gain = $48,000 - $40,000 = $8,000, long-term.","This is the basis, not the gain.","Treats the proceeds as gain because the basis box is blank. She may use her own records to establish basis."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Proceeds reported on Form 1099-B must be reported; with basis blank, the taxpayer reports documented basis from her own records.","from":"2026-01-01","calc":1,"steps":["Proceeds per 1099-B = 48,000","Basis from taxpayer's records = 40,000","Long-term gain = 8,000"],"gd":[["Which proceeds and basis figures apply?","Proceeds of 48,000 from the 1099-B and basis of 40,000 from her own records, since basis is not reported for a noncovered security."],["What is the gain and character?","48,000 - 40,000 = 8,000 long-term."]]}},{"i":"REG-IV-A-0028","t":"Two taxpayers each own 1,000 shares of the same stock that were worth $60,000 when transferred. Aaron received the shares by gift from his mother, whose basis was $20,000. Bella inherited the shares from her father, who died on the transfer date and whose basis was $20,000. Each later sold the shares for $65,000. By how much does Aaron's recognized gain exceed Bella's recognized gain?","mc":{"s":"Two taxpayers each own 1,000 shares of the same stock that were worth $60,000 when transferred. Aaron received the shares by gift from his mother, whose basis was $20,000. Bella inherited the shares from her father, who died on the transfer date and whose basis was $20,000. Each later sold the shares for $65,000. By how much does Aaron's recognized gain exceed Bella's recognized gain?","d":"","o":["$0","$20,000","$40,000","$45,000"],"a":3,"cite":"IRC §1014(a); IRC §1015(a); Pub 551","rat":"Aaron takes the donor's $20,000 basis: gain $45,000.","ex":["Assumes the same basis for both. A gift carries over the donor's basis while an inheritance is stepped up to fair market value.","Uses the father's original basis as the difference. The gap is the appreciation before the transfer ($60,000 - $20,000 = $40,000).","Aaron takes the donor's $20,000 basis: gain $45,000. Bella takes the date-of-death value: gain $5,000. The difference is $40,000.","Adds the two gains instead of subtracting them."],"wt":["concept","calc","","calc"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A gift carries over the donor's basis while an inheritance is stepped up to FMV, so the donee's gain is larger.","from":"2026-01-01","calc":1,"steps":["Aaron: 65,000 - 20,000 = 45,000","Bella: 65,000 - 60,000 = 5,000","45,000 - 5,000 = 40,000"],"gd":[["What is Aaron's gain?","Donor basis 20,000, so 65,000 - 20,000 = 45,000."],["What is Bella's gain?","Date-of-death basis 60,000, so 65,000 - 60,000 = 5,000."],["What is the difference?","45,000 - 5,000 = 40,000."]]}},{"i":"REG-IV-A-0029","t":"Compare two taxpayers in 2026. Anna has $20,000 of credit card debt canceled while her liabilities exceed the value of her assets by $30,000 immediately before the cancellation. Ben has $20,000 of credit card debt canceled while he is solvent, with assets exceeding liabilities by $50,000 immediately before the cancellation. Neither is in bankruptcy. Which statement is correct?","mc":{"s":"Compare two taxpayers in 2026. Anna has $20,000 of credit card debt canceled while her liabilities exceed the value of her assets by $30,000 immediately before the cancellation. Ben has $20,000 of credit card debt canceled while he is solvent, with assets exceeding liabilities by $50,000 immediately before the cancellation. Neither is in bankruptcy. Which statement is correct?","d":"","o":["Both exclude the entire $20,000, because credit card debt is consumer debt","Anna includes $10,000 and Ben includes $20,000","Both include the entire $20,000, because neither filed for bankruptcy","Anna excludes the entire $20,000; Ben includes the entire $20,000"],"a":4,"cite":"IRC §61(a)(11); IRC §108(a)(1)(B), (a)(3); Pub 4681","rat":"Anna's insolvency ($30,000) is at least as large as the canceled debt, so all $20,000 is excluded.","ex":["Consumer debt receives no special exclusion. Cancellation is income unless an exclusion such as insolvency applies.","Anna's exclusion is limited by her insolvency of $30,000, which is greater than the $20,000 canceled, so she includes nothing.","Bankruptcy is only one exclusion. Insolvency outside bankruptcy also allows an exclusion up to the amount of insolvency.","Anna's insolvency ($30,000) is at least as large as the canceled debt, so all $20,000 is excluded. Ben is solvent and has no exclusion, so he has $20,000 of ordinary income."],"wt":["concept","calc","concept",""],"tags":{"area":"IV","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Canceled debt is excludable to the extent of insolvency immediately before cancellation; a solvent debtor includes it all.","from":"2026-01-01","gd":[["How much cancelled debt may an insolvent taxpayer exclude?","Up to the amount of insolvency."],["How do the two compare?","Anna's 30,000 insolvency covers all 20,000, so she excludes it; Ben is solvent and includes all 20,000."]]}},{"i":"REG-IV-A-0030","t":"Review the exhibit for Tanya Okoye's 2026 return. She received a Form 1099-NEC for freelance photography and reported nothing because she believes she is not an employee and no tax was withheld. Which correction is required?","mc":{"s":"Review the exhibit for Tanya Okoye's 2026 return. She received a Form 1099-NEC for freelance photography and reported nothing because she believes she is not an employee and no tax was withheld. Which correction is required?","d":"","o":["Report $6,000 as wages on Form 1040 line 1, subject to FICA withholding","Report nothing, because income under $10,000 does not need to be reported","Report $6,000 as other income with no self-employment tax","Report $6,000 as self-employment income on Schedule C and compute self-employment tax on the net profit"],"a":4,"cite":"IRC §61(a)(1); IRC §1402(a); Pub 334","rat":"Nonemployee compensation is income for services.","ex":["A 1099-NEC recipient is an independent contractor, not an employee, so the income is not wages.","There is no de minimis threshold for reporting income. Form 1099-NEC is issued at $600, but all income is taxable.","Business income from a trade or business is subject to self-employment tax when net earnings are $400 or more.","Nonemployee compensation is income for services. It is reported on Schedule C and, after expenses, is subject to self-employment tax whether or not tax was withheld."],"wt":["concept","limit","concept",""],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Form 1099-NEC income is self-employment income on Schedule C subject to SE tax, with no de minimis reporting threshold.","tb":[["Item","Detail"],["Form 1099-NEC box 1","$6,000 (photography services)"],["Federal income tax withheld","$0"],["Draft 1040","No Schedule C; no self-employment income reported"]],"from":"2026-01-01","gd":[["How is a Form 1099-NEC for freelance services reported?","On Schedule C as self-employment income."],["Does the lack of withholding matter and what tax follows?","No, and self-employment tax applies to the net profit."]]}},{"i":"REG-IV-A-0031","t":"Review the exhibit for the final 2026 Form 1040 of Walter Pierce, a cash-basis taxpayer who died on August 12, 2026. Which statement about the draft return is correct?","mc":{"s":"Review the exhibit for the final 2026 Form 1040 of Walter Pierce, a cash-basis taxpayer who died on August 12, 2026. Which statement about the draft return is correct?","d":"","o":["The $9,000 interest should be added to the final return, because it accrued before death","The $18,000 of pension distributions received before death should be removed from the final return","The final return must be filed as married filing separately because Walter died","The $9,000 interest is correctly excluded from the final return, and the estate reports it when collected"],"a":4,"cite":"IRC §451(a); IRC §691(a); IRC §6013(a)(2); Pub 559","rat":"Interest that a cash-basis decedent had earned but not received before death is income in respect of a decedent.","ex":["A cash-basis decedent does not accrue income on the final return. IRD is taxed to the estate or heir who collects it.","Amounts actually received by the decedent before death belong on the final return.","If Walter's spouse survives, they may file a joint return for the year of death.","Interest that a cash-basis decedent had earned but not received before death is income in respect of a decedent. It is reported by the person who receives it."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Income earned but unreceived by a cash-basis decedent is income in respect of a decedent reported by whoever collects it, not on the final return.","tb":[["Item","Amount / note"],["Pension distributions received before death","$18,000 (included)"],["Bank interest earned through August 11 but credited to Walter's account on August 30, after death","$9,000 (excluded)"],["Surviving spouse","Living; joint return filed"]],"from":"2026-01-01","gd":[["How is interest earned by a cash-basis decedent but not received before death classified?","Income in respect of a decedent."],["Who reports it?","The person who receives it, so it is correctly left off the final return."]]}},{"i":"REG-IV-A-0032","t":"Ravi sold two assets in 2026 that he had held for the periods shown in the exhibit. Which statement about the classification of his gains is correct?","mc":{"s":"Ravi sold two assets in 2026 that he had held for the periods shown in the exhibit. Which statement about the classification of his gains is correct?","d":"","o":["Both stocks are long-term","Both stocks are short-term","Stock A is short-term, and Stock B is long-term","Stock A is long-term, and Stock B is short-term"],"a":4,"cite":"IRC §1222(1), (3); Pub 550","rat":"The holding period starts the day after acquisition.","ex":["Stock B was bought on September 10, 2025 and sold on September 10, 2026, which is exactly one year. More than one year is required.","Stock A was acquired on January 15, 2025 and sold March 3, 2026, more than a year later.","Reverses the periods. The longer holding period is Stock A's.","The holding period starts the day after acquisition. Stock A was held more than one year on March 3, 2026; Stock B was sold exactly one year after purchase, so it was not held more than one year and is short-term."],"wt":["limit","concept","concept",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Long-term requires holding more than one year, with the holding period starting the day after acquisition.","tb":[["Asset","Acquired","Sold"],["Stock A","January 15, 2025","March 3, 2026"],["Stock B","September 10, 2025","September 10, 2026"]],"from":"2026-01-01","gd":[["When does the holding period start and how long must it be?","The day after acquisition, and more than one year for long-term."],["Compare the two stocks.","The first was held from January 15, 2025 to March 3, 2026, more than a year; the second was sold exactly one year after purchase, so it was not held more than a year."]]}},{"i":"REG-IV-A-0033","t":"An automated check flags Yuki Tanaka's return because it reports $10,000 on line 5b (pensions and annuities, taxable amount) while Form 1099-R box 2a is blank. The payments come from a commercial annuity contract she bought with $30,000 of after-tax premiums (her investment in the contract). It is not a qualified retirement plan, so the general method applies, and the expected return under the contract is $60,000. The annuity started in 2024 and she has recovered $12,000 of her investment through prior payments. She received $10,000 in 2026. What taxable amount should line 5b show?","mc":{"s":"An automated check flags Yuki Tanaka's return because it reports $10,000 on line 5b (pensions and annuities, taxable amount) while Form 1099-R box 2a is blank. The payments come from a commercial annuity contract she bought with $30,000 of after-tax premiums (her investment in the contract). It is not a qualified retirement plan, so the general method applies, and the expected return under the contract is $60,000. The annuity started in 2024 and she has recovered $12,000 of her investment through prior payments. She received $10,000 in 2026. What taxable amount should line 5b show?","d":"","o":["$0","$5,000","$6,000","$10,000"],"a":2,"cite":"IRC §72(b), (c); Pub 939; Pub 575","rat":"Under the general method the exclusion ratio is investment in the contract / expected return = $30,000 / $60,000 = 50%, so $5,000 of the $10,000 is a return of contributions.","ex":["Treats the payment as recovery of basis only. The exclusion ratio method applies to annuity starting dates after 1986.","Under the general method the exclusion ratio is investment in the contract / expected return = $30,000 / $60,000 = 50%, so $5,000 of the $10,000 is a return of contributions. The $12,000 already recovered leaves $18,000 of basis, so the full 50% exclusion applies. Taxable amount: $5,000.","Uses the fraction of basis already recovered ($12,000 / $30,000) as the ratio. The exclusion ratio is total contributions over expected return.","Reports the entire distribution. Part of each payment recovers after-tax employee contributions."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Under the general method, the exclusion ratio is investment in the contract divided by expected return, applied to each payment.","from":"2026-01-01","calc":1,"steps":["Exclusion ratio = 30,000 / 60,000 = 50%","Excluded = 10,000 x 50% = 5,000","Remaining unrecovered basis before 2026 = 30,000 - 12,000 = 18,000 (enough)","Taxable = 10,000 - 5,000 = 5,000"],"gd":[["What is the exclusion ratio?","30,000 / 60,000 = 50%."],["How much of the 10,000 is excluded, and is enough basis left?","10,000 x 50% = 5,000, and 30,000 - 12,000 = 18,000 of unrecovered basis remains."],["What is taxable?","10,000 - 5,000 = 5,000."]]}},{"i":"REG-IV-A-0034","t":"Review the exhibit for Nolan Reeves's 2026 return, which reports $70,000 of taxable gain on the sale of his main home. Nolan is single. He sold the home after owning and living in it for 18 months because his employer transferred him to a new city. What taxable gain should be reported?","mc":{"s":"Review the exhibit for Nolan Reeves's 2026 return, which reports $70,000 of taxable gain on the sale of his main home. Nolan is single. He sold the home after owning and living in it for 18 months because his employer transferred him to a new city. What taxable gain should be reported?","d":"","o":["$70,000","$132,500","$195,000","$320,000"],"a":2,"cite":"IRC §121(a), (b)(1), (c); Reg §1.121-3; Pub 523","rat":"A job transfer allows a reduced exclusion: $250,000 x 18/24 = $187,500.","ex":["Applies the full $250,000 exclusion. Nolan did not satisfy the two-year test, so the exclusion is prorated for the unforeseen job change.","A job transfer allows a reduced exclusion: $250,000 x 18/24 = $187,500. Taxable gain = $320,000 - $187,500 = $132,500, so the draft understates the gain.","Prorates using 12 months. Nolan owned and used the home for 18 months, so the fraction is 18/24.","Allows no exclusion. A reduced maximum exclusion applies when the sale is due to a change in employment."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"A","skill":"Application","diff":3},"asof":"2026-09-29","rl":"A home sale due to a job change allows a prorated exclusion of $250,000 times months of use over 24.","tb":[["Item","Amount"],["Amount realized less selling expenses","$620,000"],["Adjusted basis","$300,000"],["Gain realized","$320,000"],["Draft taxable gain reported","$70,000 (used full $250,000 exclusion)"]],"from":"2026-01-01","calc":1,"steps":["Gain 320,000","Reduced exclusion = 250,000 x 18/24 = 187,500","Taxable gain = 320,000 - 187,500 = 132,500"],"gd":[["What exclusion is allowed for a job transfer after 18 months?","A reduced exclusion of 250,000 x 18/24 = 187,500."],["What is the taxable gain?","320,000 - 187,500 = 132,500."]]}}],"2":[{"i":"REG-IV-B-0001","t":"Which of the following items of a partnership must be passed through to the partners as a separately stated item, rather than being netted into the partnership's ordinary business income?","mc":{"s":"Which of the following items of a partnership must be passed through to the partners as a separately stated item, rather than being netted into the partnership's ordinary business income?","d":"","o":["Depreciation expense on the partnership's equipment","Wages paid to the partnership's employees","Rent paid on the partnership's office lease","Long-term capital gain from the sale of investment securities"],"a":4,"cite":"IRC §702(a); Reg §1.702-1(a)(8); Pub 541","rat":"Items that could affect partners differently, such as capital gains and losses, are separately stated so each partner applies his own limits and rates.","ex":["Depreciation used in the trade or business is deducted in computing ordinary business income (although a section 179 deduction is separately stated).","Ordinary operating expenses reduce ordinary business income and are not separately stated.","Ordinary and necessary rent is deducted in computing the ordinary business income reported in box 1.","Items that could affect partners differently, such as capital gains and losses, are separately stated so each partner applies his own limits and rates."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Items that could affect partners differently, such as capital gains, are separately stated; ordinary operating expenses net into ordinary income.","from":"2026-01-01","gd":[["What must a partnership pass through separately?","Items that could affect partners differently, such as capital gains and losses."],["Which listed item is that rather than an ordinary operating deduction?","Long-term capital gain from selling investment securities."]]}},{"i":"REG-IV-B-0002","t":"Northgate Partners earned $150,000 of ordinary business income for 2026 and had no separately stated items or guaranteed payments. Dee owns 20% of profits, losses, and capital, and received a $10,000 cash distribution during the year. What amount of ordinary business income does Dee report from Northgate for 2026?","mc":{"s":"Northgate Partners earned $150,000 of ordinary business income for 2026 and had no separately stated items or guaranteed payments. Dee owns 20% of profits, losses, and capital, and received a $10,000 cash distribution during the year. What amount of ordinary business income does Dee report from Northgate for 2026?","d":"","o":["$10,000","$30,000","$40,000","$150,000"],"a":2,"cite":"IRC §702(a); IRC §704(a); Pub 541","rat":"A partner reports her distributive share of income, $150,000 x 20% = $30,000, regardless of the cash distributed.","ex":["Reports only the cash she received. Partners are taxed on their share of income, not on distributions.","A partner reports her distributive share of income, $150,000 x 20% = $30,000, regardless of the cash distributed.","Adds the distribution to her share. The distribution is a return of basis and is not additional income.","Reports all partnership income. Dee reports only her 20% share."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A partner reports her distributive share of partnership income regardless of cash distributed.","from":"2026-01-01","calc":1,"steps":["Distributive share = 150,000 x 20% = 30,000","The 10,000 distribution reduces basis and is not income"],"gd":[["What does a partner report from ordinary income?","Her distributive share."],["What is the share?","150,000 x 20% = 30,000, regardless of the 10,000 distribution."]]}},{"i":"REG-IV-B-0003","t":"Iris Kowal owns 100% of Redwood Inc., a calendar-year S corporation. Her stock basis on January 1, 2026 was $20,000. For 2026, Redwood reported $15,000 of ordinary income, $4,000 of long-term capital gain, $1,000 of tax-exempt interest, and $2,000 of nondeductible expenses, and it distributed $30,000 to Iris. What is Iris's stock basis on December 31, 2026?","mc":{"s":"Iris Kowal owns 100% of Redwood Inc., a calendar-year S corporation. Her stock basis on January 1, 2026 was $20,000. For 2026, Redwood reported $15,000 of ordinary income, $4,000 of long-term capital gain, $1,000 of tax-exempt interest, and $2,000 of nondeductible expenses, and it distributed $30,000 to Iris. What is Iris's stock basis on December 31, 2026?","d":"","o":["$7,000","$8,000","$10,000","$12,000"],"a":2,"cite":"IRC §1367(a); IRC §1368(b); Pub 542; Form 7203 instructions","rat":"Basis increases for income items, including tax-exempt income ($20,000 + $15,000 + $4,000 + $1,000 = $40,000), then decreases for distributions ($30,000) and nondeductible expenses ($2,000): $8,000.","ex":["Omits the increase for tax-exempt interest. It increases basis so that it is not taxed later on a sale.","Basis increases for income items, including tax-exempt income ($20,000 + $15,000 + $4,000 + $1,000 = $40,000), then decreases for distributions ($30,000) and nondeductible expenses ($2,000): $8,000.","Omits the reduction for nondeductible expenses. They reduce stock basis even though they are not deductible.","Adds the nondeductible expenses instead of subtracting them."],"wt":["calc","","calc","calc"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"S corporation stock basis increases for income including tax-exempt income and decreases for distributions and nondeductible expenses.","from":"2026-01-01","calc":1,"steps":["Increases: 15,000 + 4,000 + 1,000 = 20,000","Basis before distribution = 20,000 + 20,000 = 40,000","Less distributions 30,000 and nondeductible expenses 2,000","40,000 - 30,000 - 2,000 = 8,000"],"gd":[["Which items increase S corporation stock basis?","Ordinary income, capital gain and tax-exempt income."],["What is the basis before distributions?","20,000 + 15,000 + 4,000 + 1,000 = 40,000."],["What reduces it, and what remains?","Distributions of 30,000 and nondeductible expenses of 2,000, leaving 8,000."]]}},{"i":"REG-IV-B-0004","t":"Dario Vega is the sole shareholder of Alder Inc., a calendar-year S corporation in which he materially participates. His stock basis is $8,000 and he has made no loans to Alder. His share of Alder's 2026 ordinary loss is $13,000. Ignoring the at-risk, passive activity, and excess business loss rules, what loss may Dario deduct on his 2026 return?","mc":{"s":"Dario Vega is the sole shareholder of Alder Inc., a calendar-year S corporation in which he materially participates. His stock basis is $8,000 and he has made no loans to Alder. His share of Alder's 2026 ordinary loss is $13,000. Ignoring the at-risk, passive activity, and excess business loss rules, what loss may Dario deduct on his 2026 return?","d":"","o":["$0","$5,000","$8,000","$13,000"],"a":3,"cite":"IRC §1366(d)(1); IRC §1366(d)(2); Pub 925; Form 7203 instructions","rat":"A shareholder may deduct S corporation losses only up to his stock basis plus basis in loans to the corporation.","ex":["Denies the loss entirely. He has $8,000 of basis, so the loss is deductible up to that amount.","This is the suspended portion ($5,000), not the deductible amount.","A shareholder may deduct S corporation losses only up to his stock basis plus basis in loans to the corporation. With $8,000 of basis and no loan basis, he deducts $8,000. The remaining $5,000 is suspended and carried forward.","Deducts the full loss. The loss is limited to stock and debt basis."],"wt":["concept","calc","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An S corporation shareholder may deduct losses only up to stock plus loan basis; the excess is suspended.","from":"2026-01-01","calc":1,"steps":["Deductible loss = lesser of loss 13,000 or basis 8,000 = 8,000","Excess 5,000 carries forward indefinitely"],"gd":[["What limits a shareholder's S corporation loss deduction?","Stock basis plus loan basis."],["What is Dario's limit and what happens to the excess?","8,000, and the excess 5,000 is suspended and carried forward."]]}},{"i":"REG-IV-B-0005","t":"Tess Rowe owns stock in Cedar Inc., an S corporation, with a basis of $3,000. She also lent Cedar $10,000 directly, and her basis in the loan is $10,000. Her share of Cedar's 2026 ordinary loss is $8,000. What is Tess's basis in the loan at the end of 2026?","mc":{"s":"Tess Rowe owns stock in Cedar Inc., an S corporation, with a basis of $3,000. She also lent Cedar $10,000 directly, and her basis in the loan is $10,000. Her share of Cedar's 2026 ordinary loss is $8,000. What is Tess's basis in the loan at the end of 2026?","d":"","o":["$2,000","$5,000","$8,000","$10,000"],"a":2,"cite":"IRC §1367(b)(2); IRC §1366(d)(1)(B); Pub 925; Form 7203 instructions","rat":"The loss first reduces stock basis to zero ($3,000 used).","ex":["Applies the full loss to the loan. The loss reduces stock basis first, and only the excess reduces debt basis.","The loss first reduces stock basis to zero ($3,000 used). The remaining $5,000 reduces her loan basis: $10,000 - $5,000 = $5,000.","Confuses the loss amount with the remaining loan basis.","Leaves the loan basis unchanged. It is reduced when the loss exceeds stock basis."],"wt":["calc","","calc","calc"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"S corporation losses reduce stock basis first, then loan basis for the excess.","from":"2026-01-01","calc":1,"steps":["Loss 8,000 first absorbs stock basis 3,000","Remaining loss 5,000 reduces loan basis","Loan basis = 10,000 - 5,000 = 5,000"],"gd":[["Which basis absorbs the loss first?","Stock basis, 3,000."],["How much loss reaches the loan?","8,000 - 3,000 = 5,000."],["What is the loan basis afterward?","10,000 - 5,000 = 5,000."]]}},{"i":"REG-IV-B-0006","t":"Lena Cho owns 100% of a single-member LLC that has made no entity classification election. The LLC operates a bakery and earned a $50,000 net profit in 2026. How does Lena report the LLC's income?","mc":{"s":"Lena Cho owns 100% of a single-member LLC that has made no entity classification election. The LLC operates a bakery and earned a $50,000 net profit in 2026. How does Lena report the LLC's income?","d":"","o":["On a Form 1120 filed by the LLC, taxed at the entity level","On a Schedule K-1 issued by the LLC as a partnership","On Schedule C of her Form 1040, with self-employment tax on the net profit","On Schedule E as passive income that is not subject to self-employment tax"],"a":3,"cite":"Reg §301.7701-3(b)(1)(ii); Reg §301.7701-2(c)(2); Pub 334","rat":"A single-member LLC is disregarded by default.","ex":["The LLC is not a corporation unless it elects to be one. By default it is disregarded, with no entity-level return.","A partnership requires at least two owners. A single-member LLC is disregarded, not a partnership.","A single-member LLC is disregarded by default. Its owner reports the activity on her own return, and a trade or business is reported on Schedule C.","Operating a bakery is a trade or business, so the income is reported on Schedule C and is subject to self-employment tax."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A single-member LLC is disregarded by default and its owner reports the business on Schedule C with SE tax.","from":"2026-01-01","gd":[["How is a single-member LLC with no election classified?","As a disregarded entity."],["Where does the owner report a business's income?","On Schedule C of her own return, with self-employment tax."]]}},{"i":"REG-IV-B-0007","t":"Marcus Ames contributed $50,000 in cash to Oakline LP for a general partner interest. At year end, his share of partnership recourse liabilities was $20,000, his share of partnership ordinary income was $10,000, and he received a cash distribution of $15,000. What is Marcus's outside basis in his partnership interest at year end?","mc":{"s":"Marcus Ames contributed $50,000 in cash to Oakline LP for a general partner interest. At year end, his share of partnership recourse liabilities was $20,000, his share of partnership ordinary income was $10,000, and he received a cash distribution of $15,000. What is Marcus's outside basis in his partnership interest at year end?","d":"","o":["$45,000","$55,000","$65,000","$80,000"],"a":3,"cite":"IRC §705(a); IRC §722; IRC §752(a); Pub 541","rat":"Outside basis = contribution $50,000 + share of liabilities $20,000 + share of income $10,000 - distribution $15,000 = $65,000.","ex":["Leaves out the share of partnership liabilities. A partner's share of entity liabilities is treated as a contribution of cash and increases basis.","Omits the income allocation. Partnership income increases basis.","Outside basis = contribution $50,000 + share of liabilities $20,000 + share of income $10,000 - distribution $15,000 = $65,000.","Ignores the $15,000 distribution, which reduces basis."],"wt":["calc","calc","","calc"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Outside partnership basis equals contribution plus liability share plus income allocated minus distributions.","from":"2026-01-01","calc":1,"steps":["50,000 + 20,000 + 10,000 = 80,000","80,000 - 15,000 = 65,000"],"gd":[["Which items increase outside basis?","Contribution 50,000, share of recourse liabilities 20,000, and share of income 10,000."],["What is the sum before the distribution?","50,000 + 20,000 + 10,000 = 80,000."],["What is the basis after the distribution?","80,000 - 15,000 = 65,000."]]}},{"i":"REG-IV-B-0008","t":"Bram Ellis is a general partner in a service partnership. His 2026 Schedule K-1 shows ordinary business income of $40,000, guaranteed payments of $25,000, interest income of $3,000, and long-term capital gain of $5,000. What is Bram's net earnings from self-employment from the partnership before applying the 92.35% factor?","mc":{"s":"Bram Ellis is a general partner in a service partnership. His 2026 Schedule K-1 shows ordinary business income of $40,000, guaranteed payments of $25,000, interest income of $3,000, and long-term capital gain of $5,000. What is Bram's net earnings from self-employment from the partnership before applying the 92.35% factor?","d":"","o":["$40,000","$65,000","$68,000","$73,000"],"a":2,"cite":"IRC §1402(a)(2); IRC §1402(a)(3); Pub 334","rat":"A general partner's self-employment earnings include ordinary business income and guaranteed payments for services: $40,000 + $25,000 = $65,000.","ex":["Leaves out the guaranteed payments, which are subject to self-employment tax for a general partner.","A general partner's self-employment earnings include ordinary business income and guaranteed payments for services: $40,000 + $25,000 = $65,000. Interest and capital gains are excluded.","Includes interest income, which is excluded from net earnings from self-employment.","Includes all K-1 items. Interest and capital gains are not net earnings from self-employment."],"wt":["calc","","concept","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A general partner's SE earnings include ordinary business income and guaranteed payments, but not interest or capital gains.","from":"2026-01-01","calc":1,"steps":["Ordinary income 40,000 + guaranteed payments 25,000 = 65,000","Interest and capital gain are excluded"],"gd":[["Which K-1 items are self-employment earnings for a general partner?","Ordinary business income and guaranteed payments for services."],["Which are excluded?","Interest and capital gain."],["What is the total?","40,000 + 25,000 = 65,000."]]}},{"i":"REG-IV-B-0009","t":"Which statement about compensation of an S corporation shareholder who works full time in the business is correct?","mc":{"s":"Which statement about compensation of an S corporation shareholder who works full time in the business is correct?","d":"","o":["An S corporation shareholder is subject to self-employment tax on the full ordinary income on Schedule K-1","An S corporation need not pay wages to a shareholder who performs substantial services","Wages paid to a 5% shareholder-employee are exempt from payroll tax","The IRS may recharacterize distributions as wages if the shareholder-employee is paid unreasonably low compensation for services"],"a":4,"cite":"Rev. Rul. 74-44; IRC §3121(a); Pub 542","rat":"Reasonable compensation must be paid as wages.","ex":["K-1 ordinary income of an S corporation is not subject to self-employment tax. Wages are subject to FICA.","A shareholder-employee who performs substantial services is an employee and must receive reasonable compensation.","Wages to shareholder-employees are subject to FICA. Exemption does not depend on ownership percentage.","Reasonable compensation must be paid as wages. Distributions in place of a reasonable salary can be recharacterized as wages subject to payroll tax."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"An S corporation must pay shareholder-employees reasonable compensation as wages, or the IRS may recharacterize distributions as wages.","from":"2026-01-01","gd":[["What must an S corporation pay a shareholder who works full time?","Reasonable compensation as wages."],["What may the IRS do with distributions instead of a reasonable salary?","Recharacterize them as wages subject to payroll tax."]]}},{"i":"REG-IV-B-0010","t":"A shareholder materially participates in an S corporation and has a loss from it. In which order are the limitations on deducting the loss applied?","mc":{"s":"A shareholder materially participates in an S corporation and has a loss from it. In which order are the limitations on deducting the loss applied?","d":"","o":["At-risk, then basis, then passive activity loss rules","Passive activity loss rules, then basis, then at-risk","Basis, then at-risk, then passive activity loss rules","Passive activity loss rules, then at-risk, then basis"],"a":3,"cite":"IRC §1366(d); IRC §465; IRC §469; Pub 925","rat":"The loss is first limited by stock and debt basis, then by the amount at risk, then by the passive activity rules (with the excess business loss limit applied after those).","ex":["Basis is the first hurdle. At-risk is computed from basis with adjustments for nonrecourse and protected amounts.","The passive rules apply last among these three, after basis and at-risk, since they limit only losses that survive them.","The loss is first limited by stock and debt basis, then by the amount at risk, then by the passive activity rules (with the excess business loss limit applied after those).","The order is reversed. Basis comes first, passive activity rules last."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"S corporation loss limits apply in order: basis, then at-risk, then passive activity, then excess business loss.","from":"2026-01-01","gd":[["Which limit looks first at stock and debt basis?","The basis limitation."],["What follows and what comes last?","The at-risk rules, then the passive activity rules."]]}},{"i":"REG-IV-B-0011","t":"A sole proprietor and an S corporation shareholder each expect $100,000 of net business income for 2026 from performing personal services, and each has no other earnings. The S corporation shareholder will take a $40,000 salary and receive the remaining $60,000 as distributions. Ignoring income tax, the deduction for half of self-employment tax, and unemployment taxes, by how much does the S corporation structure reduce total Social Security and Medicare taxes, assuming all amounts are under the Social Security wage base?","mc":{"s":"A sole proprietor and an S corporation shareholder each expect $100,000 of net business income for 2026 from performing personal services, and each has no other earnings. The S corporation shareholder will take a $40,000 salary and receive the remaining $60,000 as distributions. Ignoring income tax, the deduction for half of self-employment tax, and unemployment taxes, by how much does the S corporation structure reduce total Social Security and Medicare taxes, assuming all amounts are under the Social Security wage base?","d":"","o":["$6,120","$8,010","$11,070","$14,130"],"a":2,"cite":"IRC §1401; IRC §3101; IRC §3111; IRC §1402(a)","rat":"Sole proprietor: $100,000 x 92.35% x 15.3% = $14,130.","ex":["This is the payroll tax on the salary, not the reduction. The savings equals the proprietor's tax less the S corporation payroll tax.","Sole proprietor: $100,000 x 92.35% x 15.3% = $14,130. S corporation: 15.3% (employer and employee shares) x $40,000 = $6,120. Difference: about $8,010.","Counts only the employee half of FICA on the salary and ignores the employer half, which the S corporation also owes.","Assumes the S corporation structure eliminates all employment tax. Wages of $40,000 are still subject to FICA."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"S corporation K-1 income is not subject to SE tax, but reasonable wages still bear FICA; savings equal the SE tax difference.","from":"2026-01-01","calc":1,"steps":["Sole proprietor: 100,000 x 0.9235 x 0.153 = 14,130","S corporation: 40,000 x 0.153 = 6,120","14,130 - 6,120 = about 8,010"],"gd":[["What is the sole proprietor's tax?","100,000 x 0.9235 x 0.153 = 14,130."],["What is the S corporation tax on the 40,000 salary?","40,000 x 0.153 = 6,120."],["What is the saving?","14,130 - 6,120 = about 8,010."]]}},{"i":"REG-IV-B-0012","t":"Review the exhibit, which shows Schedule K-1 (Form 1065) amounts for Hana Ito, a general partner, and the entries on her draft 2026 return. Which correction is required?","mc":{"s":"Review the exhibit, which shows Schedule K-1 (Form 1065) amounts for Hana Ito, a general partner, and the entries on her draft 2026 return. Which correction is required?","d":"","o":["Report the $1,500 of interest income as ordinary business income on Schedule E","Remove the $2,000 charitable contribution from Schedule A and net it against Schedule E income","Report the $6,000 long-term capital gain as ordinary income on Schedule E","Report the $12,000 guaranteed payment as ordinary income and include it in net earnings from self-employment"],"a":4,"cite":"IRC §707(c); IRC §702(a); IRC §1402(a); Pub 541","rat":"A guaranteed payment for services is ordinary income to the partner and, for a general partner, is subject to self-employment tax.","ex":["Interest income is separately stated and belongs on Schedule B, as the draft correctly shows.","The partner's share of charitable contributions is separately stated and is deductible on Schedule A, not netted into business income.","Long-term capital gain keeps its character and is reported on Schedule D.","A guaranteed payment for services is ordinary income to the partner and, for a general partner, is subject to self-employment tax. The draft return omits it."],"wt":["trap","trap","trap",""],"tags":{"area":"IV","group":"B","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A general partner's guaranteed payment for services is ordinary income and net earnings from self-employment.","tb":[["K-1 box","Item","Amount","Draft 1040"],["1","Ordinary business income","$22,000","Schedule E: $22,000"],["4","Guaranteed payments","$12,000","Not reported"],["5","Interest income","$1,500","Schedule B: $1,500"],["9a","Net long-term capital gain","$6,000","Schedule D: $6,000"],["13","Charitable contributions","$2,000","Schedule A: $2,000"]],"from":"2026-01-01","gd":[["Which K-1 item is missing from the draft return?","The guaranteed payment of 12,000 in box 4."],["How is it treated?","As ordinary income and, for a general partner, self-employment earnings; the other items are already reported on the right forms."]]}},{"i":"REG-IV-B-0013","t":"Two investors each contribute $10,000 to a venture. Priya invests as a general partner in a partnership that has $60,000 of recourse liabilities, of which $30,000 is allocated to her. Sam invests in an S corporation that has $60,000 of bank debt owed to unrelated lenders, and he has not loaned any money to the corporation. Each is allocated a $25,000 ordinary loss. Considering only the basis limitation, how much more of the loss can Priya deduct than Sam?","mc":{"s":"Two investors each contribute $10,000 to a venture. Priya invests as a general partner in a partnership that has $60,000 of recourse liabilities, of which $30,000 is allocated to her. Sam invests in an S corporation that has $60,000 of bank debt owed to unrelated lenders, and he has not loaned any money to the corporation. Each is allocated a $25,000 ordinary loss. Considering only the basis limitation, how much more of the loss can Priya deduct than Sam?","d":"","o":["$0","$15,000","$25,000","$30,000"],"a":2,"cite":"IRC §752(a); IRC §704(d); IRC §1366(d); Reg §1.752-1","rat":"A partner's basis includes her share of partnership liabilities ($10,000 + $30,000 = $40,000), so Priya deducts the full $25,000.","ex":["Assumes both use the same basis rules. Entity-level debt increases a partner's basis but not a shareholder's.","A partner's basis includes her share of partnership liabilities ($10,000 + $30,000 = $40,000), so Priya deducts the full $25,000. An S corporation shareholder's basis does not include corporate debt owed to others, so Sam deducts only $10,000. Difference: $15,000.","Treats Sam as deducting nothing. He can deduct losses up to his $10,000 stock basis.","Uses the liability share as the difference. Priya's deduction is capped at her $25,000 allocated loss."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A partner's basis includes her share of partnership liabilities, but an S shareholder's basis excludes corporate debt owed to others.","from":"2026-01-01","calc":1,"steps":["Priya basis = 10,000 + 30,000 = 40,000; deduction = 25,000","Sam basis = 10,000; deduction = 10,000","25,000 - 10,000 = 15,000"],"gd":[["What is Priya's basis?","10,000 + 30,000 of allocated recourse liabilities = 40,000, so she deducts the full 25,000."],["What is Sam's basis?","10,000, since corporate debt owed to others does not add to it, so he deducts 10,000."],["What is the difference?","25,000 - 10,000 = 15,000."]]}},{"i":"REG-IV-B-0014","t":"Review the exhibit for Petra Lund, a sole shareholder of an S corporation who materially participates. Her draft 2026 return deducts the entire $9,000 ordinary loss from Schedule K-1. What loss is allowed in 2026, considering only the basis limitation?","mc":{"s":"Review the exhibit for Petra Lund, a sole shareholder of an S corporation who materially participates. Her draft 2026 return deducts the entire $9,000 ordinary loss from Schedule K-1. What loss is allowed in 2026, considering only the basis limitation?","d":"","o":["$2,000","$5,000","$6,000","$9,000"],"a":1,"cite":"IRC §1366(d)(1); IRC §1367(a)(2); IRC §1368(b); Pub 925; Form 7203 instructions","rat":"Basis is increased and then reduced by distributions before losses: $6,000 - $4,000 = $2,000 of basis remains, so only $2,000 of the loss is allowed.","ex":["Basis is increased and then reduced by distributions before losses: $6,000 - $4,000 = $2,000 of basis remains, so only $2,000 of the loss is allowed. The other $7,000 is suspended.","Subtracts the distribution from the loss, which is not how the basis limit works.","Uses beginning basis and ignores the $4,000 distribution, which reduces basis before the loss is applied.","This is the draft return's deduction, which ignores the basis limitation."],"wt":["","calc","calc","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"S corporation shareholder basis is reduced by distributions before losses are applied, limiting the deductible loss.","tb":[["Item","Amount"],["Stock basis, January 1, 2026","$6,000"],["Loan basis (loans from Petra)","$0"],["Schedule K-1 ordinary loss (box 1)","($9,000)"],["Distributions during 2026 (box 16D)","$4,000"]],"from":"2026-01-01","calc":1,"steps":["Basis before loss = 6,000 - 4,000 distributions = 2,000","Loss allowed = lesser of 9,000 or 2,000 = 2,000","Suspended = 7,000"],"gd":[["How does basis change before a loss is applied?","Distributions reduce it first."],["What basis remains and how much loss is allowed?","6,000 - 4,000 = 2,000, so 2,000 of loss is allowed."],["What happens to the remainder?","9,000 - 2,000 = 7,000 is suspended."]]}},{"i":"REG-IV-B-0015","t":"Jon Pike has held stock in Pine Inc., an S corporation, for five years. After all 2026 income and loss adjustments, his stock basis before distributions was $22,000. Pine distributed $30,000 to Jon during 2026, and Pine has no accumulated earnings and profits. How is the distribution treated?","mc":{"s":"Jon Pike has held stock in Pine Inc., an S corporation, for five years. After all 2026 income and loss adjustments, his stock basis before distributions was $22,000. Pine distributed $30,000 to Jon during 2026, and Pine has no accumulated earnings and profits. How is the distribution treated?","d":"","o":["The entire $30,000 is a tax-free return of basis","$22,000 is a tax-free return of basis and $8,000 is ordinary dividend income","$22,000 is a tax-free return of basis and $8,000 is long-term capital gain","$30,000 is a long-term capital gain"],"a":3,"cite":"IRC §1368(b); IRC §1368(c); Pub 542","rat":"S corporation distributions with no earnings and profits are tax-free up to stock basis, and the excess is treated as gain from the sale of stock, here long-term.","ex":["Distributions reduce basis only to zero. The amount above basis is taxable gain.","With no accumulated earnings and profits there is no dividend. The excess is capital gain.","S corporation distributions with no earnings and profits are tax-free up to stock basis, and the excess is treated as gain from the sale of stock, here long-term.","Only the excess over basis ($8,000) is gain. The first $22,000 is a return of basis."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"S corporation distributions without E&P are tax-free up to stock basis, and the excess is capital gain.","from":"2026-01-01","gd":[["How much of the 30,000 is tax-free?","Up to stock basis, 22,000."],["How is the excess treated with no earnings and profits?","As gain from the sale of stock, long-term after five years, so 8,000 long-term capital gain."]]}}],"3":[{"i":"REG-IV-C-0001","t":"Nora Fitch, single and age 40, is covered by her employer's retirement plan. Her 2026 modified AGI is $86,000. She contributed $7,500 to a traditional IRA, which is the 2026 contribution limit. For 2026 the deduction phase-out range for a single taxpayer covered by a workplace plan is $81,000 to $91,000. What IRA deduction may Nora claim?","mc":{"s":"Nora Fitch, single and age 40, is covered by her employer's retirement plan. Her 2026 modified AGI is $86,000. She contributed $7,500 to a traditional IRA, which is the 2026 contribution limit. For 2026 the deduction phase-out range for a single taxpayer covered by a workplace plan is $81,000 to $91,000. What IRA deduction may Nora claim?","d":"","o":["$0","$2,500","$3,750","$7,500"],"a":3,"cite":"IRC §219(g); Pub 590-A; Notice 2025-67","rat":"The deductible amount phases out ratably across the $10,000 range.","ex":["Assumes the deduction is fully phased out. Her MAGI is inside the range, not above $91,000.","Uses a $15,000 range instead of the $10,000 phase-out range.","The deductible amount phases out ratably across the $10,000 range. Nora's MAGI is $5,000 into the range, so she loses half: $7,500 x ($91,000 - $86,000) / $10,000 = $3,750.","Ignores the phase-out for a taxpayer covered by a workplace plan."],"wt":["limit","limit","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A traditional IRA deduction for a plan-covered taxpayer phases out ratably across the MAGI range.","from":"2026-01-01","calc":1,"steps":["Excess over the bottom of the range = 86,000 - 81,000 = 5,000","Reduction = 7,500 x 5,000 / 10,000 = 3,750","Deduction = 7,500 - 3,750 = 3,750"],"gd":[["How far into the phase-out range is Nora?","86,000 - 81,000 = 5,000 of a 10,000 range."],["What is the reduction?","7,500 x 5,000 / 10,000 = 3,750."],["What is the deduction?","7,500 - 3,750 = 3,750."]]}},{"i":"REG-IV-C-0002","t":"Carl Weiss, age 57, had family coverage under a qualifying high-deductible health plan for all of 2026. For 2026 the family-coverage limit is $8,750, and the catch-up contribution for an individual age 55 or older is $1,000. Carl's employer contributed $2,000 to his health savings account (HSA), and Carl contributed $9,000 of his own money. What HSA deduction may Carl claim?","mc":{"s":"Carl Weiss, age 57, had family coverage under a qualifying high-deductible health plan for all of 2026. For 2026 the family-coverage limit is $8,750, and the catch-up contribution for an individual age 55 or older is $1,000. Carl's employer contributed $2,000 to his health savings account (HSA), and Carl contributed $9,000 of his own money. What HSA deduction may Carl claim?","d":"","o":["$7,750","$8,750","$9,000","$9,750"],"a":1,"cite":"IRC §223(b); Pub 969","rat":"The annual limit is $8,750 + $1,000 catch-up = $9,750, reduced by the $2,000 employer contribution: $7,750.","ex":["The annual limit is $8,750 + $1,000 catch-up = $9,750, reduced by the $2,000 employer contribution: $7,750. The $1,250 excess of Carl's $9,000 is subject to the excess contribution tax unless withdrawn.","Uses the base family limit only, omitting the catch-up and the employer contribution.","Deducts the amount contributed without applying the limit.","Applies the $9,750 limit but does not subtract the $2,000 the employer already contributed."],"wt":["","calc","concept","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The HSA annual limit is the family limit plus catch-up if 55 or older, reduced by employer contributions.","from":"2026-01-01","calc":1,"steps":["Limit = 8,750 + 1,000 = 9,750","Less employer contribution 2,000 = 7,750","Deduction = lesser of 9,000 or 7,750 = 7,750"],"gd":[["What is Carl's annual limit including catch-up?","8,750 + 1,000 = 9,750."],["How does the employer contribution affect it?","9,750 - 2,000 = 7,750."],["What is the deduction?","The lesser of 9,000 or 7,750, so 7,750, with the excess subject to tax unless withdrawn."]]}},{"i":"REG-IV-C-0003","t":"For 2026, which of the following individuals is eligible to make deductible contributions to a health savings account (HSA)?","mc":{"s":"For 2026, which of the following individuals is eligible to make deductible contributions to a health savings account (HSA)?","d":"","o":["Ben, who has a qualifying high-deductible plan and is also covered by his spouse's general-purpose health flexible spending arrangement","Cora, age 67, who has a qualifying high-deductible plan and is enrolled in Medicare Part A","Dev, age 24, who has a qualifying high-deductible plan but is claimed as a dependent on his parents' return","Tara, age 40, who is covered only by a qualifying high-deductible health plan and cannot be claimed as a dependent"],"a":4,"cite":"IRC §223(c)(1); Pub 969","rat":"An eligible individual must have qualifying high-deductible health plan coverage, no other disqualifying health coverage, no Medicare enrollment, and not be claimable as a dependent.","ex":["Other disqualifying coverage, such as a general-purpose health FSA, makes him ineligible.","Individuals enrolled in Medicare cannot contribute to an HSA.","A person who can be claimed as a dependent by another taxpayer is not an eligible individual.","An eligible individual must have qualifying high-deductible health plan coverage, no other disqualifying health coverage, no Medicare enrollment, and not be claimable as a dependent."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"HSA eligibility needs a qualifying high-deductible plan, no other disqualifying coverage, no Medicare enrollment and no dependent status.","from":"2026-01-01","gd":[["What must an HSA-eligible individual have and not have?","Qualifying HDHP coverage, no other disqualifying coverage, no Medicare enrollment, and not claimable as a dependent."],["Which person meets all of those?","The one with only a qualifying HDHP who cannot be claimed as a dependent; an FSA, Medicare or dependent status each disqualify."]]}},{"i":"REG-IV-C-0004","t":"Priya Shah, a sole proprietor, had $80,000 of net earnings from self-employment from her Schedule C before any adjustment for self-employment tax in 2026. She had no wages. What deduction may Priya claim on Schedule 1 for the deductible part of her self-employment tax?","mc":{"s":"Priya Shah, a sole proprietor, had $80,000 of net earnings from self-employment from her Schedule C before any adjustment for self-employment tax in 2026. She had no wages. What deduction may Priya claim on Schedule 1 for the deductible part of her self-employment tax?","d":"","o":["$5,652","$6,120","$11,304","$12,240"],"a":1,"cite":"IRC §164(f); IRC §1402(a)(12); Pub 334","rat":"SE tax = $80,000 x 92.35% x 15.3% = $11,303.","ex":["SE tax = $80,000 x 92.35% x 15.3% = $11,303. The deduction is half of that, $5,652, and it is an adjustment to income, not an itemized deduction.","Applies 15.3% to the full $80,000 without the 92.35% reduction, then halves it.","Deducts the entire SE tax. Only the employer-equivalent half is deductible.","Uses the gross rate on the full profit and deducts all of it."],"wt":["","calc","concept","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Half of self-employment tax, computed on 92.35% of net earnings, is deductible as an adjustment to income.","from":"2026-01-01","calc":1,"steps":["Net earnings = 80,000 x 92.35% = 73,880","SE tax = 73,880 x 15.3% = 11,303","Deduction = half = 5,652"],"gd":[["What is the SE tax base and tax?","80,000 x 92.35% = 73,880, then 73,880 x 15.3% = 11,303."],["What is deductible?","Half, 5,652, as an adjustment to income."]]}},{"i":"REG-IV-C-0005","t":"Ivy Park had a $3,100 payment of interest on a qualified student loan in 2026. Her 2026 modified AGI is $90,000 and she files as single. Assume the maximum deduction is $2,500 and the phase-out range for single filers is $85,000 to $100,000. What student loan interest deduction may Ivy claim?","mc":{"s":"Ivy Park had a $3,100 payment of interest on a qualified student loan in 2026. Her 2026 modified AGI is $90,000 and she files as single. Assume the maximum deduction is $2,500 and the phase-out range for single filers is $85,000 to $100,000. What student loan interest deduction may Ivy claim?","d":"","o":["$833","$1,667","$2,500","$3,100"],"a":2,"cite":"IRC §221; Pub 970","rat":"The $2,500 maximum phases out ratably over the $15,000 range.","ex":["Computes the amount phased out ($833) instead of the amount remaining.","The $2,500 maximum phases out ratably over the $15,000 range. Her MAGI is $5,000 into the range: $2,500 x ($100,000 - $90,000) / $15,000 = $1,667.","Allows the full maximum and ignores the phase-out that applies at her income level.","Deducts all interest paid without applying the $2,500 cap or the phase-out."],"wt":["calc","","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The student loan interest deduction is capped and phases out ratably across the MAGI range.","from":"2026-01-01","calc":1,"steps":["Maximum 2,500","Fraction remaining = (100,000 - 90,000) / 15,000 = 2/3","Deduction = 2,500 x 2/3 = 1,667"],"gd":[["What is the phase-out fraction remaining?","(100,000 - 90,000) / 15,000 = 2/3."],["What is the deduction?","2,500 x 2/3 = 1,667."]]}},{"i":"REG-IV-C-0006","t":"Dan Reyes pays his former spouse $1,000 per month of alimony and $500 per month of child support under a divorce decree signed in 2016 that has never been modified. What is Dan's above-the-line deduction for these payments in 2026?","mc":{"s":"Dan Reyes pays his former spouse $1,000 per month of alimony and $500 per month of child support under a divorce decree signed in 2016 that has never been modified. What is Dan's above-the-line deduction for these payments in 2026?","d":"","o":["$0","$6,000","$12,000","$18,000"],"a":3,"cite":"IRC §215 (repealed for post-2018 instruments); Pub 504; IRC §71 (pre-2019 instruments)","rat":"For divorce instruments executed before 2019 (and not modified to adopt the new rules), alimony is deductible by the payer: $1,000 x 12 = $12,000.","ex":["Applies the post-2018 rule that denies the alimony deduction. Dan's decree is from 2016.","Deducts only the child support, which is never deductible.","For divorce instruments executed before 2019 (and not modified to adopt the new rules), alimony is deductible by the payer: $1,000 x 12 = $12,000. Child support is never deductible.","Deducts child support along with the alimony. Child support is not deductible."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Alimony under a pre-2019 divorce instrument is deductible by the payer; child support never is.","from":"2026-01-01","calc":1,"steps":["Decree signed before 2019: alimony deductible","Alimony 1,000 x 12 = 12,000","Child support not deductible"],"gd":[["Is alimony under a 2016 decree deductible?","Yes, since the instrument was executed before 2019 and not modified."],["What is the annual amount, and child support?","1,000 x 12 = 12,000; child support is never deductible."]]}},{"i":"REG-IV-C-0007","t":"Wes Adler, a sole proprietor, has a 2026 Schedule C net profit of $100,000 before his deduction for half of self-employment tax and before any retirement contribution. He wants to make the maximum deductible contribution to his own SEP-IRA. The contribution rate for self-employed individuals is effectively 20% of net earnings after the deduction for half of self-employment tax. What is his maximum SEP contribution deduction?","mc":{"s":"Wes Adler, a sole proprietor, has a 2026 Schedule C net profit of $100,000 before his deduction for half of self-employment tax and before any retirement contribution. He wants to make the maximum deductible contribution to his own SEP-IRA. The contribution rate for self-employed individuals is effectively 20% of net earnings after the deduction for half of self-employment tax. What is his maximum SEP contribution deduction?","d":"","o":["$18,587","$20,000","$23,234","$25,000"],"a":1,"cite":"IRC §404(a)(8); IRC §401(c); Pub 560","rat":"For a self-employed person, the 25% plan rate works out to 20% of net earnings reduced by half of SE tax.","ex":["For a self-employed person, the 25% plan rate works out to 20% of net earnings reduced by half of SE tax. Half of SE tax = $7,065. ($100,000 - $7,065) x 20% = $18,587.","Applies 20% to profit before subtracting the deduction for half of SE tax.","Applies the 25% employee plan rate to net earnings, which overstates the limit for a self-employed owner.","Applies 25% to gross profit. The self-employed rate is 20% of net earnings after half of SE tax."],"wt":["","calc","limit","limit"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"A self-employed SEP contribution is effectively 20% of net earnings after the deduction for half of SE tax.","from":"2026-01-01","calc":1,"steps":["Half of SE tax = 100,000 x 0.9235 x 0.153 / 2 = 7,065","Net earnings = 100,000 - 7,065 = 92,935","Contribution = 92,935 x 20% = 18,587"],"gd":[["What is half of the self-employment tax?","100,000 x 0.9235 x 0.153 / 2 = 7,065."],["What are the net earnings for the plan?","100,000 - 7,065 = 92,935."],["What is the contribution at 20%?","92,935 x 20% = 18,587."]]}},{"i":"REG-IV-C-0008","t":"Ana Duarte, a sole proprietor, had a 2026 Schedule C net profit of $30,000 before adjustments. She paid $35,000 of health insurance premiums for her family and was not eligible for employer-subsidized coverage. She has no other self-employed adjustments except the deduction for half of self-employment tax. What is her self-employed health insurance deduction?","mc":{"s":"Ana Duarte, a sole proprietor, had a 2026 Schedule C net profit of $30,000 before adjustments. She paid $35,000 of health insurance premiums for her family and was not eligible for employer-subsidized coverage. She has no other self-employed adjustments except the deduction for half of self-employment tax. What is her self-employed health insurance deduction?","d":"","o":["$2,119","$27,881","$30,000","$35,000"],"a":2,"cite":"IRC §162(l)(1)–(2); Pub 535","rat":"The deduction cannot exceed net earnings from the business after subtracting the deduction for half of SE tax.","ex":["This is the deduction for half of SE tax, not the health insurance deduction.","The deduction cannot exceed net earnings from the business after subtracting the deduction for half of SE tax. Half of SE tax on $30,000 = $2,119, so the limit is $30,000 - $2,119 = $27,881.","Limits the deduction to profit without first subtracting the deduction for half of SE tax.","Deducts the full premiums. The deduction cannot exceed earned income from the business."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The self-employed health insurance deduction cannot exceed net earnings after the deduction for half of SE tax.","from":"2026-01-01","calc":1,"steps":["Half of SE tax = 30,000 x 0.9235 x 0.153 / 2 = 2,119","Limit = 30,000 - 2,119 = 27,881","Deduction = lesser of 35,000 or 27,881 = 27,881"],"gd":[["What is half of the SE tax on 30,000?","30,000 x 0.9235 x 0.153 / 2 = 2,119."],["What is the earnings limit?","30,000 - 2,119 = 27,881."],["Which is smaller, the premiums or the limit?","27,881 is less than 35,000, so the deduction is 27,881."]]}},{"i":"REG-IV-C-0009","t":"Which of the following is an adjustment in arriving at AGI (an above-the-line deduction) for an individual in 2026?","mc":{"s":"Which of the following is an adjustment in arriving at AGI (an above-the-line deduction) for an individual in 2026?","d":"","o":["Unreimbursed travel by an employee for work","Fees paid to prepare a personal income tax return","A penalty on early withdrawal of a certificate of deposit","Cost of moving to a new city for a private-sector job"],"a":3,"cite":"IRC §62(a)(9); IRC §67(g); Pub 550","rat":"The penalty forfeited on the early withdrawal of savings is an adjustment to income.","ex":["Unreimbursed employee expenses are not deductible in 2026; miscellaneous itemized deductions are not allowed.","Tax preparation fees are miscellaneous itemized deductions, which are not allowed.","The penalty forfeited on the early withdrawal of savings is an adjustment to income.","Moving expenses are deductible only for members of the Armed Forces (and certain intelligence community personnel) moving under orders."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Early withdrawal penalties are an above-the-line adjustment, while employee expenses, preparation fees and most moving costs are not deductible.","from":"2026-01-01","gd":[["What is an above-the-line deduction?","An adjustment in arriving at AGI, such as forfeited early-withdrawal penalties."],["Which listed item is it?","The penalty on early withdrawal of a certificate of deposit; employee expenses, return prep fees and moving costs for a private-sector job are not adjustments."]]}},{"i":"REG-IV-C-0010","t":"Luis and Rosa Vega file a joint return for 2026 with AGI of $60,000. They paid these unreimbursed costs: after-tax health insurance premiums $5,000, prescription medicines $1,800, dental treatment $3,000, hospital charges $2,500, cosmetic surgery not medically necessary $1,500, and a health club membership for general fitness $600. Assume the medical deduction is allowed to the extent expenses exceed 7.5% of AGI. What medical expense deduction may they claim on Schedule A?","mc":{"s":"Luis and Rosa Vega file a joint return for 2026 with AGI of $60,000. They paid these unreimbursed costs: after-tax health insurance premiums $5,000, prescription medicines $1,800, dental treatment $3,000, hospital charges $2,500, cosmetic surgery not medically necessary $1,500, and a health club membership for general fitness $600. Assume the medical deduction is allowed to the extent expenses exceed 7.5% of AGI. What medical expense deduction may they claim on Schedule A?","d":"","o":["$6,300","$7,800","$9,300","$12,300"],"a":2,"cite":"IRC §213(a), (d)(9); Pub 502","rat":"Qualifying expenses: $5,000 + $1,800 + $3,000 + $2,500 = $12,300.","ex":["Uses a 10% floor instead of 7.5%.","Qualifying expenses: $5,000 + $1,800 + $3,000 + $2,500 = $12,300. Cosmetic surgery (not medically necessary) and general fitness costs do not qualify. Subtract 7.5% x $60,000 = $4,500: $7,800.","Includes the cosmetic surgery, which is not medical care unless it corrects a deformity or disease.","Ignores the 7.5% of AGI floor."],"wt":["limit","","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Only qualifying medical expenses exceeding 7.5% of AGI are deductible; cosmetic surgery and general fitness costs do not qualify.","from":"2026-01-01","calc":1,"steps":["Qualifying = 5,000 + 1,800 + 3,000 + 2,500 = 12,300","Floor = 7.5% x 60,000 = 4,500","Deduction = 12,300 - 4,500 = 7,800"],"gd":[["Which expenses qualify as medical?","Premiums, prescriptions, dental and hospital: 5,000 + 1,800 + 3,000 + 2,500 = 12,300."],["Which are excluded?","Cosmetic surgery not medically necessary and general fitness membership."],["What is the floor and the deduction?","7.5% x 60,000 = 4,500, so 12,300 - 4,500 = 7,800."]]}},{"i":"REG-IV-C-0011","t":"Maya Chen bought her main home in 2024 with a single $900,000 mortgage that is her only debt secured by the home, and she paid $54,000 of interest on it in 2026. How much of the interest is deductible as qualified residence interest if she itemizes?","mc":{"s":"Maya Chen bought her main home in 2024 with a single $900,000 mortgage that is her only debt secured by the home, and she paid $54,000 of interest on it in 2026. How much of the interest is deductible as qualified residence interest if she itemizes?","d":"","o":["$9,000","$40,500","$45,000","$54,000"],"a":3,"cite":"IRC §163(h)(3); Pub 936","rat":"Interest is deductible only on acquisition debt up to $750,000 for debt incurred after December 15, 2017.","ex":["This is the nondeductible portion ($9,000), not the deductible amount.","Uses 75% instead of the ratio $750,000 / $900,000.","Interest is deductible only on acquisition debt up to $750,000 for debt incurred after December 15, 2017. Deductible = $54,000 x $750,000 / $900,000 = $45,000.","Deducts all interest. Interest on acquisition debt above $750,000 is not deductible."],"wt":["calc","limit","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Home mortgage interest is deductible only on acquisition debt up to $750,000 for debt incurred after December 15, 2017.","from":"2026-07-01","calc":1,"steps":["Deductible fraction = 750,000 / 900,000","54,000 x 5/6 = 45,000"],"gd":[["What debt limit applies to a mortgage taken out after December 15, 2017?","750,000 of acquisition debt."],["What fraction of interest is deductible?","750,000 / 900,000 = 5/6."],["What is the amount?","54,000 x 5/6 = 45,000."]]}},{"i":"REG-IV-C-0012","t":"Which of the following is deductible on Schedule A as a state or local tax in 2026, subject to the overall limit?","mc":{"s":"Which of the following is deductible on Schedule A as a state or local tax in 2026, subject to the overall limit?","d":"","o":["Federal income tax withheld from the taxpayer's wages","A special assessment for building a new sidewalk in front of the taxpayer's home","Homeowners association dues paid on the taxpayer's home","State income tax withheld from the taxpayer's wages"],"a":4,"cite":"IRC §164(a); Pub 17; Pub 530","rat":"State and local income taxes paid or withheld are deductible taxes on Schedule A, subject to the cap on state and local taxes.","ex":["Federal income tax is not deductible.","Assessments for local improvements that increase property value are added to basis, not deducted.","HOA dues are personal expenses and are not a tax.","State and local income taxes paid or withheld are deductible taxes on Schedule A, subject to the cap on state and local taxes."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"State and local income and property taxes are deductible on Schedule A up to the cap; federal income tax, assessments and HOA dues are not.","from":"2026-01-01","gd":[["Which taxes are deductible on Schedule A?","State and local income or property taxes, subject to the cap."],["Which listed item is such a tax?","State income tax withheld from wages; federal income tax, special improvement assessments and association dues are not."]]}},{"i":"REG-IV-C-0013","t":"Jordan and Mei Lin file a joint return for 2026 and itemize deductions. Their modified AGI is $560,000. They paid $30,000 of state income tax and $12,000 of real property tax on their home and no other state or local taxes. Assume the 2026 limit on state and local taxes is $40,400, reduced by 30% of modified AGI over $505,000, but not below $10,000. What amount may they deduct for state and local taxes?","mc":{"s":"Jordan and Mei Lin file a joint return for 2026 and itemize deductions. Their modified AGI is $560,000. They paid $30,000 of state income tax and $12,000 of real property tax on their home and no other state or local taxes. Assume the 2026 limit on state and local taxes is $40,400, reduced by 30% of modified AGI over $505,000, but not below $10,000. What amount may they deduct for state and local taxes?","d":"","o":["$10,000","$23,900","$40,400","$42,000"],"a":2,"cite":"IRC §164(b)(6); Pub 17","rat":"The limit is $40,400 - 30% x ($560,000 - $505,000) = $40,400 - $16,500 = $23,900.","ex":["Uses the pre-2025 cap of $10,000, which is only the floor of the new phase-down.","The limit is $40,400 - 30% x ($560,000 - $505,000) = $40,400 - $16,500 = $23,900. Taxes paid ($42,000) exceed it, so the deduction is $23,900.","Uses the full cap and ignores the reduction for modified AGI above $505,000.","Deducts all taxes paid without applying any limit."],"wt":["limit","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The SALT cap is reduced by 30% of modified AGI above the threshold, but not below the $10,000 floor.","from":"2026-07-01","calc":1,"steps":["Excess MAGI = 560,000 - 505,000 = 55,000","Reduction = 30% x 55,000 = 16,500","Limit = 40,400 - 16,500 = 23,900 (above the 10,000 floor)","Deduction = lesser of 42,000 or 23,900 = 23,900"],"gd":[["How much does MAGI exceed the threshold?","560,000 - 505,000 = 55,000."],["What is the reduced limit?","40,400 - 30% x 55,000 = 40,400 - 16,500 = 23,900, above the 10,000 floor."],["Which is smaller, taxes paid or the limit?","42,000 exceeds 23,900, so 23,900."]]}},{"i":"REG-IV-C-0014","t":"Hector and Alma Ruiz file jointly for 2026 with modified AGI of $640,000. They paid $36,000 of state and local income and property taxes. Assume the 2026 limit on state and local taxes is $40,400, reduced by 30% of modified AGI over $505,000, but not below $10,000. What may they deduct for these taxes?","mc":{"s":"Hector and Alma Ruiz file jointly for 2026 with modified AGI of $640,000. They paid $36,000 of state and local income and property taxes. Assume the 2026 limit on state and local taxes is $40,400, reduced by 30% of modified AGI over $505,000, but not below $10,000. What may they deduct for these taxes?","d":"","o":["$0","$10,000","$36,000","$40,400"],"a":2,"cite":"IRC §164(b)(6); Pub 17","rat":"The reduction is 30% x $135,000 = $40,500, which would reduce the limit below zero.","ex":["Allows the limit to fall to zero. The rules never reduce the limit below $10,000.","The reduction is 30% x $135,000 = $40,500, which would reduce the limit below zero. The floor keeps the limit at $10,000, so they deduct $10,000.","Deducts all taxes paid, ignoring the limit.","Uses the full cap without the phase-down."],"wt":["limit","","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The SALT cap phases down with income but never below a $10,000 floor.","from":"2026-07-01","calc":1,"steps":["Reduction = 30% x (640,000 - 505,000) = 40,500","40,400 - 40,500 < 0, so the floor of 10,000 applies","Deduction = 10,000"],"gd":[["What is the reduction?","30% x (640,000 - 505,000) = 40,500."],["What does that do to the limit?","40,400 - 40,500 falls below zero, so the 10,000 floor applies."],["What is the deduction?","10,000."]]}},{"i":"REG-IV-C-0015","t":"A hurricane in an area federally declared a disaster area destroyed part of Nikhil Rao's home in 2026. His adjusted basis in the home was $100,000, its fair market value was $140,000 before and $105,000 after the storm, and his insurance paid $5,000. Nikhil's 2026 AGI is $90,000 and he had no other casualty. What is his deductible personal casualty loss if he itemizes? The loss is reduced by $100 and by 10% of AGI.","mc":{"s":"A hurricane in an area federally declared a disaster area destroyed part of Nikhil Rao's home in 2026. His adjusted basis in the home was $100,000, its fair market value was $140,000 before and $105,000 after the storm, and his insurance paid $5,000. Nikhil's 2026 AGI is $90,000 and he had no other casualty. What is his deductible personal casualty loss if he itemizes? The loss is reduced by $100 and by 10% of AGI.","d":"","o":["$20,900","$21,000","$29,900","$35,000"],"a":1,"cite":"IRC §165(h); Pub 547","rat":"Loss = lesser of basis ($100,000) or decline in value ($35,000) = $35,000, less insurance $5,000 = $30,000.","ex":["Loss = lesser of basis ($100,000) or decline in value ($35,000) = $35,000, less insurance $5,000 = $30,000. Subtract $100 and 10% of AGI ($9,000): $20,900.","Omits the $100 per-event reduction.","Omits the 10% of AGI reduction.","Ignores insurance and both reductions."],"wt":["","calc","calc","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"A personal casualty loss is the lesser of basis or value decline, less insurance, less $100 and 10% of AGI.","from":"2026-01-01","calc":1,"steps":["Decline in value = 140,000 - 105,000 = 35,000 (less than basis 100,000)","Less insurance 5,000 = 30,000","Less $100 = 29,900; less 10% of AGI 9,000 = 20,900"],"gd":[["Which is smaller, basis or the decline in value?","Decline 140,000 - 105,000 = 35,000, less than basis 100,000."],["What is the loss after insurance?","35,000 - 5,000 = 30,000."],["What are the reductions and the result?","Less 100 and less 10% of AGI, 9,000: 30,000 - 100 - 9,000 = 20,900."]]}},{"i":"REG-IV-C-0016","t":"Which of the following personal losses is deductible on Schedule A as a personal casualty or theft loss in 2026?","mc":{"s":"Which of the following personal losses is deductible on Schedule A as a personal casualty or theft loss in 2026?","d":"","o":["Theft of personal jewelry from the taxpayer's home by a burglar","Damage to the taxpayer's personal car in a collision with another driver","Damage to the taxpayer's home caused by a hurricane in an area federally declared a disaster area","Loss of a diamond ring that slipped off the taxpayer's finger"],"a":3,"cite":"IRC §165(h)(5); Pub 547","rat":"Personal casualty losses are deductible only if attributable to a federally declared disaster (and, from 2026, certain state-declared disasters).","ex":["A personal theft that is not from a federally declared disaster is not deductible.","A car accident is not a federally declared disaster, so the loss is not deductible.","Personal casualty losses are deductible only if attributable to a federally declared disaster (and, from 2026, certain state-declared disasters).","A lost item is not a casualty and is not attributable to a federally declared disaster."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Personal casualty losses are deductible only if attributable to a federally declared disaster.","from":"2026-07-01","gd":[["When is a personal casualty loss deductible?","Only if attributable to a federally declared disaster or certain state-declared disasters."],["Which listed loss meets that?","Hurricane damage in a declared disaster area; burglary, a collision and a lost ring do not."]]}},{"i":"REG-IV-C-0017","t":"Pat Ellison itemizes deductions. In 2026 Pat had $20,000 of documented gambling winnings and $18,000 of documented gambling losses. Assume that for 2026 only 90% of gambling losses may be deducted, and the deduction cannot exceed winnings. What is Pat's gambling loss deduction?","mc":{"s":"Pat Ellison itemizes deductions. In 2026 Pat had $20,000 of documented gambling winnings and $18,000 of documented gambling losses. Assume that for 2026 only 90% of gambling losses may be deducted, and the deduction cannot exceed winnings. What is Pat's gambling loss deduction?","d":"","o":["$2,000","$16,200","$18,000","$20,000"],"a":2,"cite":"IRC §165(d); Pub 529","rat":"Deductible loss = 90% x $18,000 = $16,200, which is below the $20,000 winnings limit.","ex":["Nets the loss against winnings. Gross winnings are included and losses are a separate itemized deduction.","Deductible loss = 90% x $18,000 = $16,200, which is below the $20,000 winnings limit. The winnings are still fully included in income.","Deducts 100% of losses, which was the rule before 2026.","Uses the winnings as the deduction. The deduction is limited by 90% of losses and cannot exceed winnings, so the lesser is used."],"wt":["concept","","limit","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Gambling losses are an itemized deduction limited to winnings and, in 2026, to 90% of losses; winnings are fully included.","from":"2026-07-01","calc":1,"steps":["90% x 18,000 = 16,200","Limit = winnings 20,000","Deduction = lesser = 16,200"],"gd":[["What percentage of losses may be deducted in 2026?","90% x 18,000 = 16,200."],["What is the winnings limit?","20,000."],["What is the deduction?","The lesser of 16,200 and 20,000, so 16,200."]]}},{"i":"REG-IV-C-0018","t":"Ella Frost wrote a $300 check to a public charity in 2026, in exchange for nothing. What documentation must she have to claim the $300 deduction?","mc":{"s":"Ella Frost wrote a $300 check to a public charity in 2026, in exchange for nothing. What documentation must she have to claim the $300 deduction?","d":"","o":["Only the canceled check, because the amount is under $500","A qualified appraisal of the amount given","Form 8283 completed with the charity's signature","A bank record of the payment and a contemporaneous written acknowledgment from the charity"],"a":4,"cite":"IRC §170(f)(8); Pub 526","rat":"A contribution of $250 or more requires a written acknowledgment from the charity, in addition to a bank record for a cash gift.","ex":["For a gift of $250 or more, a canceled check alone is not enough.","Appraisals are for noncash property over $5,000, not cash.","Form 8283 is for noncash contributions over $500.","A contribution of $250 or more requires a written acknowledgment from the charity, in addition to a bank record for a cash gift."],"wt":["limit","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A contribution of $250 or more needs a contemporaneous written acknowledgment from the charity plus a bank record.","from":"2026-01-01","gd":[["What is required for a contribution of 250 or more?","A written acknowledgment from the charity."],["What else is needed for a cash gift?","A bank record of the payment."]]}},{"i":"REG-IV-C-0019","t":"For 2026, which taxpayer may deduct moving expenses?","mc":{"s":"For 2026, which taxpayer may deduct moving expenses?","d":"","o":["A member of the Armed Forces on active duty who moves under a military order for a permanent change of station","A software engineer who moves 500 miles for a new job with a private employer","A self-employed consultant who moves her office and home to a new city","A retired teacher who moves to be near family"],"a":1,"cite":"IRC §217(k); Pub 521","rat":"The moving expense deduction is limited to active-duty members of the Armed Forces moving under a military order (and certain intelligence community personnel).","ex":["The moving expense deduction is limited to active-duty members of the Armed Forces moving under a military order (and certain intelligence community personnel).","Employees generally cannot deduct moving expenses, even for a long-distance job move.","The deduction is not available to self-employed individuals unless they are in the eligible service categories.","A move for personal reasons is not deductible."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The moving expense deduction is limited to active-duty Armed Forces members moving under a military order and certain intelligence personnel.","from":"2026-07-01","gd":[["Who may deduct moving expenses now?","Active-duty Armed Forces members moving under a military order, and certain intelligence personnel."],["Which listed taxpayer is that?","The service member with a permanent change of station order."]]}},{"i":"REG-IV-C-0020","t":"Lee Warren paid $10,000 of margin interest in 2026 to buy taxable stocks and bonds. His net investment income for the year (taxable interest and nonqualified dividends, after related expenses) was $6,000. Lee itemizes. What investment interest expense may he deduct in 2026, and what is carried forward?","mc":{"s":"Lee Warren paid $10,000 of margin interest in 2026 to buy taxable stocks and bonds. His net investment income for the year (taxable interest and nonqualified dividends, after related expenses) was $6,000. Lee itemizes. What investment interest expense may he deduct in 2026, and what is carried forward?","d":"","o":["$10,000 is deductible and nothing is carried forward","$4,000 is deductible and $6,000 is carried forward","$6,000 is deductible and $4,000 is carried forward","$0 is deductible and $10,000 is carried forward"],"a":3,"cite":"IRC §163(d); Form 4952; Pub 550","rat":"Investment interest is deductible up to net investment income.","ex":["The deduction is limited to net investment income.","Reverses the two amounts.","Investment interest is deductible up to net investment income. The $4,000 excess carries forward indefinitely.","Investment interest is deductible up to net investment income in the current year."],"wt":["concept","calc","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Investment interest is deductible up to net investment income, with the excess carried forward indefinitely.","from":"2026-01-01","gd":[["What limits investment interest deductions?","Net investment income."],["What is deductible and what carries forward?","6,000 is deductible; 10,000 - 6,000 = 4,000 carries forward indefinitely."]]}},{"i":"REG-IV-C-0021","t":"Ken and Ruth Yates, a married couple filing jointly, are deciding whether to itemize in 2026. The 2026 standard deduction for married filing jointly is $32,200. Their itemized deductions would be: mortgage interest on acquisition debt $19,000 and state and local taxes of $22,000 (below the cap that applies to them). Their marginal rate is 22%. How much does itemizing reduce their tax compared to taking the standard deduction?","mc":{"s":"Ken and Ruth Yates, a married couple filing jointly, are deciding whether to itemize in 2026. The 2026 standard deduction for married filing jointly is $32,200. Their itemized deductions would be: mortgage interest on acquisition debt $19,000 and state and local taxes of $22,000 (below the cap that applies to them). Their marginal rate is 22%. How much does itemizing reduce their tax compared to taking the standard deduction?","d":"","o":["$1,936","$7,084","$8,800","$9,020"],"a":1,"cite":"IRC §63(b), (c), (d); Pub 17","rat":"Itemized deductions total $41,000, which exceeds the standard deduction by $8,800.","ex":["Itemized deductions total $41,000, which exceeds the standard deduction by $8,800. Tax savings = $8,800 x 22% = $1,936.","Applies the rate to the standard deduction rather than to the excess of itemized over standard.","Reports the extra deduction ($8,800) but does not convert it to tax savings.","Applies the rate to all itemized deductions. Only the excess over the standard deduction produces additional savings."],"wt":["","calc","calc","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Itemizing saves tax only on the excess of itemized deductions over the standard deduction times the marginal rate.","from":"2026-07-01","calc":1,"steps":["Itemized = 19,000 + 22,000 = 41,000","Excess over standard = 41,000 - 32,200 = 8,800","Savings = 8,800 x 22% = 1,936"],"gd":[["What are the total itemized deductions?","19,000 + 22,000 = 41,000."],["How much do they exceed the standard deduction?","41,000 - 32,200 = 8,800."],["What is the tax saving at 22%?","8,800 x 22% = 1,936."]]}},{"i":"REG-IV-C-0022","t":"Harold Boyd, a single filer, will be age 68 on December 31, 2026, and is legally blind. Assume the 2026 basic standard deduction for single filers is $16,100, with an additional $2,050 for age 65 or older and another $2,050 for blindness. What is Harold's standard deduction?","mc":{"s":"Harold Boyd, a single filer, will be age 68 on December 31, 2026, and is legally blind. Assume the 2026 basic standard deduction for single filers is $16,100, with an additional $2,050 for age 65 or older and another $2,050 for blindness. What is Harold's standard deduction?","d":"","o":["$16,100","$18,150","$20,200","$32,200"],"a":3,"cite":"IRC §63(c)(1), (c)(3), (f); Pub 501","rat":"The basic amount is increased by $2,050 for being 65 or older and by another $2,050 for blindness: $16,100 + $2,050 + $2,050 = $20,200.","ex":["Ignores both additional amounts.","Adds only one additional amount. Age and blindness each qualify for an additional amount.","The basic amount is increased by $2,050 for being 65 or older and by another $2,050 for blindness: $16,100 + $2,050 + $2,050 = $20,200.","Uses the married filing jointly standard deduction, which does not apply to a single filer."],"wt":["calc","calc","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The standard deduction increases by an additional amount for age 65 or older and another for blindness.","from":"2026-07-01","calc":1,"steps":["Basic 16,100","Age 65 or older +2,050; blind +2,050","16,100 + 4,100 = 20,200"],"gd":[["What is the basic single amount and the additions?","16,100, plus 2,050 for age 65 or older and 2,050 for blindness."],["What is the total?","16,100 + 4,100 = 20,200."]]}},{"i":"REG-IV-C-0023","t":"Walt and Edna Frank, both age 68 with valid Social Security numbers, file jointly for 2026 with modified AGI of $170,000. Assume that for 2025 through 2028 each qualifying individual age 65 or older may claim an additional deduction of $6,000, and that $6,000 amount is reduced separately for each qualifying individual by 6% of the amount by which modified AGI exceeds $150,000 (joint filers). What is the total additional senior deduction for Walt and Edna?","mc":{"s":"Walt and Edna Frank, both age 68 with valid Social Security numbers, file jointly for 2026 with modified AGI of $170,000. Assume that for 2025 through 2028 each qualifying individual age 65 or older may claim an additional deduction of $6,000, and that $6,000 amount is reduced separately for each qualifying individual by 6% of the amount by which modified AGI exceeds $150,000 (joint filers). What is the total additional senior deduction for Walt and Edna?","d":"","o":["$6,000","$9,600","$10,800","$12,000"],"a":2,"cite":"IRC §151(d)(5); Pub 501; Form Schedule 1-A instructions (Part V)","rat":"The $6,000 amount for each individual is reduced by 6% x ($170,000 - $150,000) = $1,200, leaving $4,800 per spouse.","ex":["Allows the deduction for only one spouse. Each spouse who is age 65 or older with a valid Social Security number is a qualifying individual and gets a separate deduction.","The $6,000 amount for each individual is reduced by 6% x ($170,000 - $150,000) = $1,200, leaving $4,800 per spouse. Two qualifying spouses: 2 x $4,800 = $9,600.","Reduces the combined $12,000 only once, by $1,200. The reduction applies to each individual's $6,000 amount, so each spouse loses $1,200 and the total reduction is $2,400.","Ignores the phase-out. Modified AGI of $170,000 exceeds the $150,000 joint threshold, so the deduction is reduced."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The senior deduction is per qualifying individual and phases out by 6% of MAGI above the threshold, applied separately to each.","from":"2026-07-01","calc":1,"steps":["Reduction per individual = 6% x (170,000 - 150,000) = 1,200","Deduction per individual = 6,000 - 1,200 = 4,800","Total = 2 x 4,800 = 9,600"],"gd":[["What is the reduction per individual?","6% x (170,000 - 150,000) = 1,200."],["What is the deduction per spouse?","6,000 - 1,200 = 4,800."],["What is the total for two?","2 x 4,800 = 9,600."]]}},{"i":"REG-IV-C-0024","t":"Luis Herrera is an hourly employee whose regular rate is $30 per hour. He worked 100 hours of overtime in 2026 for which his employer paid time and a half ($45 per hour), as required by federal wage law, and reported it on his W-2. For 2025 through 2028, a deduction is allowed for the premium (extra half) portion of qualifying overtime pay, up to $12,500 ($25,000 joint), phased out at higher income. Luis's income is well below the phase-out. What is his overtime deduction?","mc":{"s":"Luis Herrera is an hourly employee whose regular rate is $30 per hour. He worked 100 hours of overtime in 2026 for which his employer paid time and a half ($45 per hour), as required by federal wage law, and reported it on his W-2. For 2025 through 2028, a deduction is allowed for the premium (extra half) portion of qualifying overtime pay, up to $12,500 ($25,000 joint), phased out at higher income. Luis's income is well below the phase-out. What is his overtime deduction?","d":"","o":["$1,500","$3,000","$4,500","$12,500"],"a":1,"cite":"IRC §225; IRS Schedule 1-A instructions","rat":"Only the premium portion (the amount above the regular rate) is deductible: $15 x 100 hours = $1,500.","ex":["Only the premium portion (the amount above the regular rate) is deductible: $15 x 100 hours = $1,500.","Uses the regular-rate portion of the overtime hours, not the premium.","Uses the total overtime pay. Only the premium portion qualifies.","Uses the maximum. The deduction is the smaller of the premium pay or the maximum."],"wt":["","concept","concept","limit"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Only the premium half of qualifying overtime pay is deductible, up to the maximum.","from":"2026-07-01","calc":1,"steps":["Premium per hour = 45 - 30 = 15","15 x 100 = 1,500 (less than the 12,500 cap)"],"gd":[["Which portion of overtime pay is deductible?","Only the premium above the regular rate."],["What is the premium per hour and the total?","45 - 30 = 15, so 15 x 100 = 1,500, below the 12,500 cap."]]}},{"i":"REG-IV-C-0025","t":"Sofia Ruiz, a single filer, has $80,000 of qualified business income from a sole proprietorship that is not a specified service trade or business. Her taxable income before the QBI deduction is $120,000, including $10,000 of net capital gain. Her taxable income is below the threshold at which wage and property limits apply. What is her qualified business income deduction?","mc":{"s":"Sofia Ruiz, a single filer, has $80,000 of qualified business income from a sole proprietorship that is not a specified service trade or business. Her taxable income before the QBI deduction is $120,000, including $10,000 of net capital gain. Her taxable income is below the threshold at which wage and property limits apply. What is her qualified business income deduction?","d":"","o":["$14,000","$16,000","$22,000","$24,000"],"a":2,"cite":"IRC §199A(a); Pub 535","rat":"The deduction is 20% of the lesser of QBI ($80,000) or taxable income minus net capital gain ($110,000).","ex":["Subtracts the net capital gain from QBI. The capital gain reduces only the taxable income limit.","The deduction is 20% of the lesser of QBI ($80,000) or taxable income minus net capital gain ($110,000). The lesser is $80,000, so the deduction is $16,000.","Uses taxable income less capital gain instead of the smaller QBI.","Uses taxable income before the deduction, ignoring both QBI and the capital gain reduction."],"wt":["calc","","calc","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The QBI deduction is 20% of the lesser of QBI or taxable income minus net capital gain.","from":"2026-07-01","calc":1,"steps":["QBI = 80,000","Taxable income limit = 120,000 - 10,000 = 110,000","Deduction = 20% x lesser of 80,000 or 110,000 = 16,000"],"gd":[["What are the two figures compared for the QBI deduction?","QBI 80,000 and taxable income minus net capital gain, 120,000 - 10,000 = 110,000."],["Which is lower?","80,000."],["What is 20% of it?","16,000."]]}},{"i":"REG-IV-C-0026","t":"Tia Gomez, single, has $100,000 of qualified business income from a nonservice business. Her taxable income before the QBI deduction is $60,000, with no net capital gain, and she is below the threshold amount. What is her QBI deduction?","mc":{"s":"Tia Gomez, single, has $100,000 of qualified business income from a nonservice business. Her taxable income before the QBI deduction is $60,000, with no net capital gain, and she is below the threshold amount. What is her QBI deduction?","d":"","o":["$6,000","$12,000","$16,780","$20,000"],"a":2,"cite":"IRC §199A(a), (b)(1); Pub 535","rat":"The deduction is 20% of the lesser of QBI ($100,000) or taxable income before the deduction ($60,000): $12,000.","ex":["Uses 10% of taxable income. The rate is 20%.","The deduction is 20% of the lesser of QBI ($100,000) or taxable income before the deduction ($60,000): $12,000.","Subtracts the standard deduction from QBI. The taxable income limit already reflects it.","Applies 20% to QBI and ignores the taxable income limit."],"wt":["limit","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The QBI deduction is 20% of the lesser of QBI or taxable income before the deduction.","from":"2026-07-01","calc":1,"steps":["20% x QBI = 20,000","20% x taxable income = 12,000","Deduction = lesser = 12,000"],"gd":[["What are 20% of QBI and 20% of taxable income?","20% x 100,000 = 20,000 and 20% x 60,000 = 12,000."],["Which is smaller?","12,000, so that is the deduction."]]}},{"i":"REG-IV-C-0027","t":"Owen Blake, single, is a sole proprietor with a 2026 Schedule C net profit of $90,000. He deducts $12,000 for a SEP-IRA contribution and the deductible part of self-employment tax, and has no self-employed health insurance. His taxable income before the QBI deduction is $160,000, with no net capital gain, and is below the threshold. What is his QBI deduction?","mc":{"s":"Owen Blake, single, is a sole proprietor with a 2026 Schedule C net profit of $90,000. He deducts $12,000 for a SEP-IRA contribution and the deductible part of self-employment tax, and has no self-employed health insurance. His taxable income before the QBI deduction is $160,000, with no net capital gain, and is below the threshold. What is his QBI deduction?","d":"","o":["$14,328","$15,600","$16,728","$18,000"],"a":1,"cite":"IRC §199A(c)(1); Reg §1.199A-3(b)(1); Pub 535","rat":"QBI is net of the deductions attributable to the business: half of SE tax ($6,358) and the SEP contribution ($12,000).","ex":["QBI is net of the deductions attributable to the business: half of SE tax ($6,358) and the SEP contribution ($12,000). QBI = $90,000 - $6,358 - $12,000 = $71,642. Deduction = 20% x $71,642 = $14,328.","Subtracts the SEP contribution but not the deduction for half of self-employment tax.","Subtracts half of SE tax but not the SEP contribution.","Uses gross Schedule C profit. QBI is reduced by the self-employed deductions."],"wt":["","calc","calc","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"QBI is reduced by deductions attributable to the business, including half of SE tax and retirement contributions.","from":"2026-07-01","calc":1,"steps":["Half of SE tax = 90,000 x 0.9235 x 0.153 / 2 = 6,358","QBI = 90,000 - 6,358 - 12,000 = 71,642","Deduction = 20% x 71,642 = 14,328 (below the 20% x 160,000 limit)"],"gd":[["What is half of the SE tax?","90,000 x 0.9235 x 0.153 / 2 = 6,358."],["What is QBI after business-attributable deductions?","90,000 - 6,358 - 12,000 = 71,642."],["What is 20% of it?","14,328."]]}},{"i":"REG-IV-C-0028","t":"Vera Lund, a single filer, owns a manufacturing business (not a service business) with $400,000 of qualified business income for 2026. The business paid $60,000 of W-2 wages and has $100,000 of unadjusted basis of qualified property. Her taxable income before the QBI deduction is $600,000, which is well above the top of the phase-in range. What is her QBI deduction?","mc":{"s":"Vera Lund, a single filer, owns a manufacturing business (not a service business) with $400,000 of qualified business income for 2026. The business paid $60,000 of W-2 wages and has $100,000 of unadjusted basis of qualified property. Her taxable income before the QBI deduction is $600,000, which is well above the top of the phase-in range. What is her QBI deduction?","d":"","o":["$17,500","$30,000","$80,000","$120,000"],"a":2,"cite":"IRC §199A(b)(2); Pub 535","rat":"Above the phase-in range, the deduction is limited to the greater of 50% of W-2 wages ($30,000) or 25% of wages plus 2.5% of property ($17,500).","ex":["Uses the alternative wage-and-property formula ($17,500) even though 50% of wages is greater.","Above the phase-in range, the deduction is limited to the greater of 50% of W-2 wages ($30,000) or 25% of wages plus 2.5% of property ($17,500). That $30,000 is below 20% of QBI ($80,000) and 20% of taxable income ($120,000).","Uses 20% of QBI and ignores the W-2 wage and property limitation.","Uses 20% of taxable income, which is not the binding limit."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Above the phase-in range, the QBI deduction is limited to the greater of 50% of W-2 wages or 25% of wages plus 2.5% of property.","from":"2026-07-01","calc":1,"steps":["20% x QBI = 80,000","Wage limit = greater of 50% x 60,000 = 30,000 or 25% x 60,000 + 2.5% x 100,000 = 17,500 = 30,000","Deduction = lesser of 80,000 or 30,000 (and 120,000) = 30,000"],"gd":[["What is 20% of QBI?","20% x 400,000 = 80,000."],["What is the wage and property limit above the phase-in?","The greater of 50% x 60,000 = 30,000 or 25% x 60,000 + 2.5% x 100,000 = 17,500, so 30,000."],["Which amount controls?","30,000 is below 80,000 and below 20% of taxable income, 120,000."]]}},{"i":"REG-IV-C-0029","t":"For purposes of the qualified business income deduction, which of the following businesses is a specified service trade or business?","mc":{"s":"For purposes of the qualified business income deduction, which of the following businesses is a specified service trade or business?","d":"","o":["An engineering firm","A bakery","A hardware store","A medical practice"],"a":4,"cite":"IRC §199A(d)(2); Reg §1.199A-5; Pub 535","rat":"Health is a specified service field.","ex":["Engineering and architecture are expressly excluded from the specified service definition.","Retail food production is a product business, not a specified service business.","Retail sales are not a specified service trade or business.","Health is a specified service field. A specified service business gets a reduced or no deduction when taxable income is above the threshold."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Health and other listed professional fields are specified service businesses; engineering, architecture and retail are not.","from":"2026-01-01","gd":[["Which fields are specified service trades?","Health, law, accounting, consulting and similar personal-service fields."],["Which listed business is one?","The medical practice; engineering, bakeries and hardware stores are not."]]}},{"i":"REG-IV-C-0030","t":"Dr. Mia Torres, single, has $70,000 of qualified business income from her medical practice, a specified service business. Her taxable income before the QBI deduction is $150,000, which is below the threshold at which the specified service limit begins. What is her QBI deduction?","mc":{"s":"Dr. Mia Torres, single, has $70,000 of qualified business income from her medical practice, a specified service business. Her taxable income before the QBI deduction is $150,000, which is below the threshold at which the specified service limit begins. What is her QBI deduction?","d":"","o":["$0","$14,000","$30,000","$70,000"],"a":2,"cite":"IRC §199A(d)(3); IRC §199A(e)(2); Pub 535","rat":"Below the threshold, a specified service business is treated like any other business and no wage limit applies: 20% x $70,000 = $14,000.","ex":["Denies the deduction to a service business. The exclusion applies only when taxable income is above the threshold (phase-in) range.","Below the threshold, a specified service business is treated like any other business and no wage limit applies: 20% x $70,000 = $14,000.","Uses taxable income instead of QBI. The deduction is 20% of the lesser.","Uses QBI in full without the 20% rate."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Below the threshold, a specified service business gets the full 20% QBI deduction with no wage limit.","from":"2026-07-01","calc":1,"steps":["Taxable income below the threshold: specified service limits do not apply","20% x 70,000 = 14,000 (below 20% x 150,000)"],"gd":[["Do specified-service limits apply below the threshold?","No, it is treated like any other business."],["What is the deduction?","20% x 70,000 = 14,000."]]}},{"i":"REG-IV-C-0031","t":"Review the exhibit, which lists the proposed Schedule A entries for Jim and Beth Carter (married filing jointly, 2026). Which entry is not allowable?","mc":{"s":"Review the exhibit, which lists the proposed Schedule A entries for Jim and Beth Carter (married filing jointly, 2026). Which entry is not allowable?","d":"","o":["Unreimbursed employee business expenses of $3,500","State income tax of $22,000 and real property tax of $9,000, within the applicable cap","Home mortgage interest of $28,000 on a $500,000 acquisition mortgage on the main home","Medical expenses of $9,000 above 7.5% of AGI"],"a":1,"cite":"IRC §67(g); IRC §164(a); IRC §163(h); Pub 17","rat":"Unreimbursed employee expenses are miscellaneous itemized deductions, which are not allowed for 2026.","ex":["Unreimbursed employee expenses are miscellaneous itemized deductions, which are not allowed for 2026.","State and local income and property taxes are deductible on Schedule A up to the cap.","Interest on acquisition debt below $750,000 is qualified residence interest.","The deductible amount is the excess over the AGI floor. This entry is allowable."],"wt":["","trap","trap","trap"],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Unreimbursed employee business expenses are miscellaneous itemized deductions and are not allowed in 2026.","tb":[["Schedule A entry","Amount"],["State income tax","$22,000"],["Real property tax","$9,000"],["Home mortgage interest ($500,000 acquisition debt)","$28,000"],["Medical expenses over 7.5% of AGI","$9,000"],["Unreimbursed employee business expenses","$3,500"]],"from":"2026-07-01","gd":[["Which itemized deductions are allowed for 2026?","State and local taxes within the cap, qualified mortgage interest, and medical over 7.5% of AGI."],["Which proposed entry falls under an unallowed category?","The employee business expense entry, since that category of itemized deduction is suspended for 2026."]]}},{"i":"REG-IV-C-0032","t":"Consider two calculations for the same married couple, who have modified AGI of $520,000 and paid $50,000 of state and local taxes. Under the 2025 rules the cap is $40,000, reduced by 30% of modified AGI over $500,000. Under the 2026 rules the cap is $40,400, reduced by 30% of modified AGI over $505,000. Both are subject to a $10,000 floor. How much larger is the allowable deduction under the 2026 rules than under the 2025 rules?","mc":{"s":"Consider two calculations for the same married couple, who have modified AGI of $520,000 and paid $50,000 of state and local taxes. Under the 2025 rules the cap is $40,000, reduced by 30% of modified AGI over $500,000. Under the 2026 rules the cap is $40,400, reduced by 30% of modified AGI over $505,000. Both are subject to a $10,000 floor. How much larger is the allowable deduction under the 2026 rules than under the 2025 rules?","d":"","o":["$0","$400","$1,500","$1,900"],"a":4,"cite":"IRC §164(b)(6); Pub 17","rat":"2025 limit: $40,000 - 30% x $20,000 = $34,000.","ex":["Assumes the deduction is the same because taxes paid exceed both caps. Each year's cap is different.","Compares only the base caps and ignores the different phase-down thresholds.","Compares only the reductions ($6,000 vs $4,500) and omits the higher base cap.","2025 limit: $40,000 - 30% x $20,000 = $34,000. 2026 limit: $40,400 - 30% x $15,000 = $35,900. Both are below the $50,000 paid, so the difference is $1,900."],"wt":["concept","calc","calc",""],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The SALT cap equals the base cap less 30% of MAGI over the threshold, so different thresholds change the allowed amount.","from":"2026-07-01","calc":1,"steps":["2025 cap = 40,000 - 6,000 = 34,000","2026 cap = 40,400 - 4,500 = 35,900","35,900 - 34,000 = 1,900"],"gd":[["What is the 2025 cap for this couple?","40,000 - 30% x 20,000 = 34,000."],["What is the 2026 cap?","40,400 - 30% x 15,000 = 35,900."],["Are both below the 50,000 paid, and what is the difference?","Yes, so 35,900 - 34,000 = 1,900."]]}},{"i":"REG-IV-C-0033","t":"Review the exhibit for Kai Nomura's 2026 return. Kai has a Schedule C net profit of $90,000 and reports a QBI deduction of $18,000. Which explanation identifies the error?","mc":{"s":"Review the exhibit for Kai Nomura's 2026 return. Kai has a Schedule C net profit of $90,000 and reports a QBI deduction of $18,000. Which explanation identifies the error?","d":"","o":["QBI must be reduced by the standard deduction before applying 20%","QBI must include the $4,200 of tax-exempt interest to reflect all income","QBI must be reduced by the deductible part of self-employment tax, the SEP contribution, and self-employed health insurance","The deduction should be 30%, because Kai is single and has no employees"],"a":3,"cite":"IRC §199A(c); Reg §1.199A-3(b)(1); Pub 535","rat":"QBI is computed after the deductions attributable to the business, including half of SE tax, self-employed health insurance, and retirement plan contributions.","ex":["The standard deduction affects the taxable income limit only, not QBI itself.","Tax-exempt interest and other investment income are not QBI.","QBI is computed after the deductions attributable to the business, including half of SE tax, self-employed health insurance, and retirement plan contributions.","The rate is 20% of QBI for any qualified business."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"QBI must be reduced by half of SE tax, self-employed health insurance and retirement plan contributions before applying 20%.","tb":[["Item","Amount"],["Schedule C net profit","$90,000"],["Deductible part of SE tax","$6,358"],["SEP-IRA contribution","$12,000"],["Self-employed health insurance deduction","$6,000"],["QBI deduction reported (20% x $90,000)","$18,000"]],"from":"2026-01-01","gd":[["What is QBI compared with Schedule C profit?","QBI is net of deductions attributable to the business."],["Which deductions does Kai's 90,000 need to reduce by?","Half of SE tax, the SEP contribution and self-employed health insurance."]]}},{"i":"REG-IV-C-0034","t":"Two single taxpayers each have $300,000 of qualified business income, pay $100,000 of W-2 wages, and have no qualified property. Each has taxable income well above the top of the phase-in range. Kim's business is a law practice. Lou's business is a machine shop. How much more is Lou's QBI deduction than Kim's?","mc":{"s":"Two single taxpayers each have $300,000 of qualified business income, pay $100,000 of W-2 wages, and have no qualified property. Each has taxable income well above the top of the phase-in range. Kim's business is a law practice. Lou's business is a machine shop. How much more is Lou's QBI deduction than Kim's?","d":"","o":["$0","$25,000","$50,000","$60,000"],"a":3,"cite":"IRC §199A(b)(2), (d)(3); Pub 535","rat":"Kim's law practice is a specified service business, so above the phase-in range she gets no deduction.","ex":["Assumes both receive the same deduction. A specified service business gets no deduction above the phase-in range.","Uses 25% of W-2 wages, which is smaller than the 50% of wages limit.","Kim's law practice is a specified service business, so above the phase-in range she gets no deduction. Lou's deduction is the lesser of 20% of QBI ($60,000) or 50% of wages ($50,000): $50,000. Difference: $50,000.","Uses 20% of QBI for Lou and ignores the wage limit."],"wt":["concept","limit","","concept"],"tags":{"area":"IV","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A specified service business gets no QBI deduction above the phase-in range, while others are limited to 50% of W-2 wages.","from":"2026-07-01","calc":1,"steps":["Kim (specified service, above range) = 0","Lou = lesser of 20% x 300,000 = 60,000 or greater of 50,000 or 25,000 = 50,000","50,000 - 0 = 50,000"],"gd":[["What does Kim's law practice get above the phase-in range?","Nothing, since a specified service business gets no deduction there."],["What is Lou's deduction?","The lesser of 20% x 300,000 = 60,000 or 50% x 100,000 = 50,000, so 50,000."],["What is the difference?","50,000 - 0 = 50,000."]]}},{"i":"REG-IV-C-0035","t":"Review the exhibit for Grace Ohara's 2026 return. She claimed a $7,500 deduction for a contribution to a traditional IRA. Which statement is correct?","mc":{"s":"Review the exhibit for Grace Ohara's 2026 return. She claimed a $7,500 deduction for a contribution to a traditional IRA. Which statement is correct?","d":"","o":["Her IRA deduction is correct, because any contribution up to $7,500 is deductible for every taxpayer","Her IRA deduction should be $3,750, because she is halfway through the phase-out range","Her IRA deduction should be $7,500, but only if she itemizes","Her IRA deduction should be $0, because her MAGI exceeds the top of the phase-out range for a single taxpayer covered by a workplace plan"],"a":4,"cite":"IRC §219(g); Pub 590-A; Notice 2025-67","rat":"She is covered by an employer plan, and her $95,000 MAGI is above $91,000, so a contribution is not deductible (it may be a nondeductible contribution).","ex":["Deductibility depends on whether the taxpayer is covered by a workplace plan and on MAGI.","The phase-out range ends at $91,000, and her MAGI of $95,000 is above it.","The IRA deduction is an adjustment to income, available whether or not she itemizes.","She is covered by an employer plan, and her $95,000 MAGI is above $91,000, so a contribution is not deductible (it may be a nondeductible contribution)."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A plan-covered single taxpayer's IRA deduction is zero when MAGI exceeds the top of the phase-out range.","tb":[["Item","Detail"],["Filing status","Single"],["Covered by employer retirement plan","Yes (W-2 box 13 checked)"],["Modified AGI before IRA deduction","$95,000"],["2026 phase-out range (covered, single)","$81,000 to $91,000"],["IRA deduction claimed","$7,500"]],"from":"2026-01-01","gd":[["Is Grace covered by an employer plan, and which range applies?","Yes, so the 81,000 to 91,000 range for a single covered filer applies."],["Where does her MAGI of 95,000 fall?","Above the top of the range, so no deduction is allowed."]]}},{"i":"REG-IV-C-0036","t":"An automated check flags a mismatch for Ron Alvarez, age 41, who has self-only coverage under a qualifying high-deductible plan. The 2026 HSA limit for self-only coverage is $4,400. His Form W-2 box 12 code W shows $1,500 of employer contributions, and Form 5498-SA shows he personally contributed $4,900. His return claims an HSA deduction of $4,900. What HSA deduction is allowed?","mc":{"s":"An automated check flags a mismatch for Ron Alvarez, age 41, who has self-only coverage under a qualifying high-deductible plan. The 2026 HSA limit for self-only coverage is $4,400. His Form W-2 box 12 code W shows $1,500 of employer contributions, and Form 5498-SA shows he personally contributed $4,900. His return claims an HSA deduction of $4,900. What HSA deduction is allowed?","d":"","o":["$1,500","$2,900","$4,400","$4,900"],"a":2,"cite":"IRC §223(b); IRC §4973(a); Pub 969","rat":"The limit includes employer contributions.","ex":["This is the employer amount, which is excluded from wages rather than deducted.","The limit includes employer contributions. Ron's own deductible contributions are limited to $4,400 - $1,500 = $2,900. The remaining $2,000 is an excess contribution subject to a 6% excise tax unless withdrawn.","Ignores the employer contribution, which uses part of the annual limit.","Deducts everything contributed without applying the annual limit."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The HSA annual limit includes employer contributions, so the personal deduction is the limit minus employer amounts; excess is subject to a 6% excise tax.","from":"2026-01-01","calc":1,"steps":["Annual limit = 4,400","Less employer contribution 1,500 = 2,900","Deduction = lesser of 4,900 or 2,900 = 2,900"],"gd":[["Does the HSA limit include employer contributions?","Yes."],["What is Ron's own deductible amount?","4,400 - 1,500 = 2,900."],["What happens to the rest?","The remaining 2,000 is an excess contribution subject to a 6% excise tax unless withdrawn."]]}},{"i":"REG-IV-C-0037","t":"Compare two homeowners in 2026. Ann bought her main home in 2024 with a $600,000 mortgage. Ben took out a $600,000 home equity loan on his main home in 2024 and used the entire amount to buy a boat and take a vacation. Each paid $36,000 of interest. Which statement is correct?","mc":{"s":"Compare two homeowners in 2026. Ann bought her main home in 2024 with a $600,000 mortgage. Ben took out a $600,000 home equity loan on his main home in 2024 and used the entire amount to buy a boat and take a vacation. Each paid $36,000 of interest. Which statement is correct?","d":"","o":["Ann's interest is deductible qualified residence interest; Ben's is not","Both deduct all of the interest, because both loans are secured by a main home","Neither deducts the interest, because personal interest is not deductible in any case","Ann's interest is not deductible; Ben's is, because equity loans are deductible up to $100,000"],"a":1,"cite":"IRC §163(h)(2)(D), (h)(3); Pub 936","rat":"Interest on acquisition debt, within the $750,000 limit, is deductible.","ex":["Interest on acquisition debt, within the $750,000 limit, is deductible. Home equity debt is qualified only if used to buy, build, or substantially improve the home.","Being secured by the home is not enough. The debt's use determines whether it is acquisition debt.","Qualified residence interest is an exception to the personal interest disallowance.","The $100,000 home equity rule is not current law. Debt used for personal spending is not qualified."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Home mortgage interest is deductible on acquisition debt within $750,000; home equity debt qualifies only if used to buy, build or improve the home.","from":"2026-07-01","gd":[["When is home mortgage interest deductible?","On acquisition debt within 750,000, or home equity debt used to buy, build or improve the home."],["How do the two homeowners compare?","Ann's loan bought the home so its interest qualifies; Ben's loan bought a boat and vacation, so his does not."]]}}],"4":[{"i":"REG-IV-D-0001","t":"Sandra Kim, a single taxpayer, had a net capital loss of $12,000 for 2026, made up of a $5,000 short-term loss and a $7,000 long-term loss, and had no other capital transactions. How is the loss treated?","mc":{"s":"Sandra Kim, a single taxpayer, had a net capital loss of $12,000 for 2026, made up of a $5,000 short-term loss and a $7,000 long-term loss, and had no other capital transactions. How is the loss treated?","d":"","o":["$12,000 is deductible against ordinary income in 2026","$3,000 is deductible in 2026, and the remaining $9,000 is permanently lost","$3,000 is deductible against ordinary income in 2026, and $9,000 is carried forward indefinitely, retaining its short-term or long-term character","$3,000 is deductible in 2026, and the remaining $9,000 carries forward for only five years"],"a":3,"cite":"IRC §1211(b); IRC §1212(b)(1); Pub 550","rat":"An individual's net capital loss is deductible up to $3,000 per year against ordinary income.","ex":["Deductions of net capital loss against ordinary income are capped at $3,000 ($1,500 if married filing separately).","The excess is not lost. Individuals carry it forward indefinitely.","An individual's net capital loss is deductible up to $3,000 per year against ordinary income. Any excess carries forward with no time limit and keeps its character.","The five-year limit applies to charitable contribution carryforwards, not capital losses. A capital loss carryforward has no expiration for individuals."],"wt":["limit","concept","","limit"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"An individual's net capital loss is deductible up to $3,000 per year, with the excess carried forward indefinitely keeping its character.","from":"2026-01-01","gd":[["What is the annual limit on net capital loss against ordinary income?","3,000."],["What happens to the excess and its character?","9,000 carries forward indefinitely and keeps its short-term or long-term character."]]}},{"i":"REG-IV-D-0002","t":"Tom and Uma Park are married and file separate returns for 2026. Tom has a $10,000 net capital loss and no other capital transactions. Uma has no capital transactions. How much of Tom's net capital loss may he deduct against ordinary income in 2026?","mc":{"s":"Tom and Uma Park are married and file separate returns for 2026. Tom has a $10,000 net capital loss and no other capital transactions. Uma has no capital transactions. How much of Tom's net capital loss may he deduct against ordinary income in 2026?","d":"","o":["$1,500","$3,000","$5,000","$10,000"],"a":1,"cite":"IRC §1211(b); Pub 550","rat":"The annual limit on the deduction of net capital losses against ordinary income is $3,000, but only $1,500 for a married person filing separately.","ex":["The annual limit on the deduction of net capital losses against ordinary income is $3,000, but only $1,500 for a married person filing separately.","The $3,000 limit applies to single filers and joint returns. A married person filing separately is limited to $1,500.","The limit is not half of the loss. It is a fixed $1,500 for married filing separately.","There is no rule allowing the full net capital loss against ordinary income."],"wt":["","limit","calc","concept"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The annual net capital loss deduction is $3,000, or $1,500 for married filing separately.","from":"2026-01-01","gd":[["What is the general net capital loss limit per year?","3,000."],["What is it for a married person filing separately?","1,500."]]}},{"i":"REG-IV-D-0003","t":"Which taxpayer's rental real estate activities are not automatically treated as passive under the real estate professional rules?","mc":{"s":"Which taxpayer's rental real estate activities are not automatically treated as passive under the real estate professional rules?","d":"","o":["Sam, who performed 900 hours in real estate but also works 2,000 hours at a full-time job","Tia, who performed 500 hours in real estate and no other work","Uri, an employee of a real estate firm who owns 2% of it and works there 1,800 hours","Rita, who performed 900 hours of services in real property businesses in which she materially participates, more than half of her 1,600 hours in total of personal services"],"a":4,"cite":"IRC §469(c)(7); Pub 925","rat":"To qualify, an individual must spend more than half of her personal service time and more than 750 hours in real property trades or businesses in which she materially participates.","ex":["His real estate hours are less than half of his total working time.","She spent all her time in real estate but did not reach the 750-hour minimum.","Work as an employee counts only if the employee owns more than 5% of the employer.","To qualify, an individual must spend more than half of her personal service time and more than 750 hours in real property trades or businesses in which she materially participates."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Real estate professional status requires more than half of personal service time and over 750 hours in real property businesses where she materially participates.","from":"2026-01-01","gd":[["What two tests define a real estate professional?","More than half of personal service time and more than 750 hours in real property trades in which she materially participates."],["Who meets both?","The person with 900 hours that exceeded half of her 1,600 total; the others fail on hours, time share or ownership."]]}},{"i":"REG-IV-D-0004","t":"A partner's share of a partnership loss for 2026 exceeds his outside basis in the partnership at year end. How is the excess loss treated?","mc":{"s":"A partner's share of a partnership loss for 2026 exceeds his outside basis in the partnership at year end. How is the excess loss treated?","d":"","o":["It is not deductible in 2026 and is carried forward indefinitely until the partner has basis to absorb it","It is deductible in 2026 as an ordinary loss, and basis becomes negative","It is converted into a capital loss deductible up to $3,000 per year","It is lost permanently if not used in 2026"],"a":1,"cite":"IRC §704(d); Pub 541","rat":"Losses are allowed only to the extent of the partner's basis at year end.","ex":["Losses are allowed only to the extent of the partner's basis at year end. The disallowed amount carries forward with no expiration.","Basis cannot go below zero from losses. The deduction is limited to basis.","A disallowed partnership loss keeps its character and is not treated as a capital loss.","The excess carries forward indefinitely and is allowed when basis is restored."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A partner's loss is allowed only to the extent of outside basis; the excess carries forward indefinitely until basis is restored.","from":"2026-01-01","gd":[["Up to what amount can a partner deduct a partnership loss?","His outside basis at year end."],["What happens to the excess?","It is not deductible now and carries forward indefinitely until basis exists."]]}},{"i":"REG-IV-D-0005","t":"Which loss is deductible on an individual's 2026 income tax return?","mc":{"s":"Which loss is deductible on an individual's 2026 income tax return?","d":"","o":["A $6,000 loss on the sale of the taxpayer's family car","A $9,000 loss on the sale of the taxpayer's main home","A $4,000 loss on the sale of investment stock held for two years","A $1,500 loss on the sale of the taxpayer's furniture used in the home"],"a":3,"cite":"IRC §165(c); Pub 544","rat":"Losses on property held for investment are deductible (as capital losses subject to the limits).","ex":["Losses on personal-use property are not deductible.","A loss on the sale of a personal residence is not deductible.","Losses on property held for investment are deductible (as capital losses subject to the limits).","Household furniture is personal-use property, and a loss on its sale is not deductible."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Losses on personal-use property such as a car, home or furniture are not deductible, but investment property losses are.","from":"2026-01-01","gd":[["Which losses are deductible for an individual?","Losses on property held for investment or business, as capital losses subject to limits."],["Which listed loss is on investment property?","The stock held for two years; personal-use property losses are not deductible."]]}},{"i":"REG-IV-D-0006","t":"Lena sold 100 shares of ABC Corp. at a loss on December 10, 2026. Which of the following purchases would cause her loss to be disallowed under the wash sale rule?","mc":{"s":"Lena sold 100 shares of ABC Corp. at a loss on December 10, 2026. Which of the following purchases would cause her loss to be disallowed under the wash sale rule?","d":"","o":["A purchase of 100 shares of XYZ Corp., a competitor of ABC, on December 12, 2026","A purchase of 100 shares of ABC Corp. on January 15, 2027","A purchase of 100 shares of ABC Corp. on October 20, 2026","A purchase by her IRA of 100 shares of ABC Corp. on December 27, 2026"],"a":4,"cite":"IRC §1091(a); Rev. Rul. 2008-5; Pub 550","rat":"A purchase of substantially identical stock within 30 days before or after the sale, including a purchase by the taxpayer's IRA, triggers the wash sale rule.","ex":["Stock of a different company is not substantially identical, even in the same industry.","January 15 is 36 days after the sale, outside the 61-day window.","October 20 is 51 days before the sale, outside the window that starts 30 days before.","A purchase of substantially identical stock within 30 days before or after the sale, including a purchase by the taxpayer's IRA, triggers the wash sale rule."],"wt":["concept","limit","limit",""],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A wash sale arises from buying substantially identical stock, including by the taxpayer's IRA, within 30 days before or after the sale.","from":"2026-01-01","gd":[["What does the wash sale rule cover?","A purchase of substantially identical stock within 30 days before or after the loss sale."],["Which listed purchase falls in the window and involves the same stock?","A purchase by her IRA of ABC shares on December 27; a different company, a date beyond 30 days, or a purchase 30 days later than the window are out."]]}},{"i":"REG-IV-D-0007","t":"Bill breeds racehorses as a hobby with no profit motive. In 2026 the activity produced $8,000 of income and $12,000 of expenses. How is the activity treated for the year?","mc":{"s":"Bill breeds racehorses as a hobby with no profit motive. In 2026 the activity produced $8,000 of income and $12,000 of expenses. How is the activity treated for the year?","d":"","o":["The $8,000 is included in gross income, and the $12,000 of expenses is not deductible","Bill reports a $4,000 loss from the activity on Schedule C","The $8,000 is excluded from gross income because it is a hobby","The $8,000 is included, and $8,000 of expenses is deductible as an itemized deduction"],"a":1,"cite":"IRC §183(a)-(b); IRC §67(g); Pub 535","rat":"Hobby income is taxable, but hobby expenses are miscellaneous itemized deductions, which are not allowed, so no loss arises.","ex":["Hobby income is taxable, but hobby expenses are miscellaneous itemized deductions, which are not allowed, so no loss arises.","A hobby cannot generate a loss. The activity is not a trade or business.","Income from a hobby is taxable.","Before 2018 hobby expenses were deductible up to income as itemized deductions. They are not deductible now."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Hobby income is taxable, but hobby expenses are not deductible, so no loss arises.","from":"2026-07-01","gd":[["Is hobby income taxable?","Yes, 8,000 is included."],["Are hobby expenses deductible?","No, they are miscellaneous itemized deductions that are not allowed, so no loss arises."]]}},{"i":"REG-IV-D-0008","t":"Sara Lund, a single taxpayer, had a $10,000 short-term capital loss and a $4,000 long-term capital gain in 2026, and no other capital transactions. What net capital loss carryforward does she have to 2027?","mc":{"s":"Sara Lund, a single taxpayer, had a $10,000 short-term capital loss and a $4,000 long-term capital gain in 2026, and no other capital transactions. What net capital loss carryforward does she have to 2027?","d":"","o":["$3,000","$4,000","$6,000","$10,000"],"a":1,"cite":"IRC §1211(b); IRC §1212(b); Pub 550","rat":"The net capital loss is $10,000 - $4,000 = $6,000.","ex":["The net capital loss is $10,000 - $4,000 = $6,000. She deducts $3,000 against ordinary income and carries forward the remaining $3,000.","Reports the $4,000 long-term gain as the carryforward. The carryforward is the net loss less the $3,000 deducted.","Reports the net loss ($6,000) as the carryforward without deducting the $3,000 used in 2026.","Ignores the $4,000 gain and the $3,000 deduction."],"wt":["","calc","calc","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net short-term loss after offsetting long-term gain is deducted up to $3,000, with the remainder carried forward.","from":"2026-01-01","calc":1,"steps":["Net = 10,000 ST loss - 4,000 LT gain = 6,000 net loss","Deduct 3,000 in 2026","Carryforward = 6,000 - 3,000 = 3,000"],"gd":[["What is the net capital loss?","10,000 - 4,000 = 6,000."],["How much is deducted in 2026?","3,000."],["What carries forward?","6,000 - 3,000 = 3,000."]]}},{"i":"REG-IV-D-0009","t":"Dana Woo actively participates in a rental house she owns. For 2026 the rental produced a $30,000 loss, and she has no passive income. Her modified AGI is $120,000 before the loss. What rental loss may Dana deduct against nonpassive income in 2026?","mc":{"s":"Dana Woo actively participates in a rental house she owns. For 2026 the rental produced a $30,000 loss, and she has no passive income. Her modified AGI is $120,000 before the loss. What rental loss may Dana deduct against nonpassive income in 2026?","d":"","o":["$0","$15,000","$25,000","$30,000"],"a":2,"cite":"IRC §469(i); Pub 925","rat":"The $25,000 special allowance is reduced by 50% of MAGI above $100,000: $25,000 - 50% x $20,000 = $15,000.","ex":["Disallows the entire loss. The special allowance is reduced but not fully phased out until MAGI reaches $150,000.","The $25,000 special allowance is reduced by 50% of MAGI above $100,000: $25,000 - 50% x $20,000 = $15,000. The remaining $15,000 is suspended.","Ignores the phase-out that begins at $100,000 of MAGI.","Deducts the entire loss, ignoring the passive activity loss limit."],"wt":["limit","","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The $25,000 rental loss allowance is reduced by 50% of MAGI above $100,000 for active participants.","from":"2026-01-01","calc":1,"steps":["Excess MAGI = 120,000 - 100,000 = 20,000","Reduction = 50% x 20,000 = 10,000","Allowance = 25,000 - 10,000 = 15,000","Suspended = 30,000 - 15,000 = 15,000"],"gd":[["What is the special allowance and how is it reduced?","25,000 reduced by 50% of MAGI above 100,000."],["What is the reduction?","50% x (120,000 - 100,000) = 10,000."],["What is deductible and what is suspended?","25,000 - 10,000 = 15,000 deductible and 30,000 - 15,000 = 15,000 suspended."]]}},{"i":"REG-IV-D-0010","t":"Adam Ruiz materially participates in a partnership business (not a passive activity). His share of the 2026 partnership loss is $70,000. At the end of 2026 his outside basis is $60,000 and his at-risk amount is $50,000 (before considering the current-year loss). What amount of the loss may Adam deduct in 2026?","mc":{"s":"Adam Ruiz materially participates in a partnership business (not a passive activity). His share of the 2026 partnership loss is $70,000. At the end of 2026 his outside basis is $60,000 and his at-risk amount is $50,000 (before considering the current-year loss). What amount of the loss may Adam deduct in 2026?","d":"","o":["$10,000","$50,000","$60,000","$70,000"],"a":2,"cite":"IRC §704(d); IRC §465(a); Pub 925","rat":"Losses are limited first by outside basis ($60,000) and then by the amount at risk ($50,000).","ex":["This is the amount limited by basis ($10,000), not the deductible amount.","Losses are limited first by outside basis ($60,000) and then by the amount at risk ($50,000). Adam deducts $50,000, and $20,000 is carried forward.","Applies only the basis limitation and ignores the at-risk limit.","Deducts the entire loss, ignoring both limits."],"wt":["calc","","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Partnership losses are limited first by outside basis, then by the amount at risk, with the excess carried forward.","from":"2026-01-01","calc":1,"steps":["Basis limit = 60,000","At-risk limit = 50,000","Deduction = lesser of 70,000, 60,000 and 50,000 = 50,000"],"gd":[["In what order do loss limits apply?","Basis first, then at risk."],["What are the two limits?","Basis 60,000 and at risk 50,000."],["What is the deduction?","The lesser of 70,000, 60,000 and 50,000, so 50,000."]]}},{"i":"REG-IV-D-0011","t":"On November 1, 2026, Grant sold 100 shares of stock for $16,000. His basis was $20,000. On November 20, 2026, he bought 100 identical shares for $15,500. What is Grant's basis in the newly purchased shares?","mc":{"s":"On November 1, 2026, Grant sold 100 shares of stock for $16,000. His basis was $20,000. On November 20, 2026, he bought 100 identical shares for $15,500. What is Grant's basis in the newly purchased shares?","d":"","o":["$15,500","$16,000","$19,500","$20,000"],"a":3,"cite":"IRC §1091(d); Pub 550","rat":"The $4,000 loss is disallowed and added to the basis of the replacement shares: $15,500 + $4,000 = $19,500.","ex":["Uses cost only. The disallowed loss carries over into the replacement shares' basis.","Uses the proceeds of the first sale, which has no connection to the new basis.","The $4,000 loss is disallowed and added to the basis of the replacement shares: $15,500 + $4,000 = $19,500.","Uses the old shares' basis. The new basis is the new cost plus the disallowed loss."],"wt":["concept","calc","","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A wash sale's disallowed loss is added to the replacement shares' basis.","from":"2026-01-01","calc":1,"steps":["Loss on first sale = 20,000 - 16,000 = 4,000 (disallowed)","New basis = 15,500 + 4,000 = 19,500","Holding period also tacks"],"gd":[["What is the loss on the first sale?","20,000 - 16,000 = 4,000, disallowed as a wash sale."],["What is the replacement basis?","15,500 + 4,000 = 19,500."]]}},{"i":"REG-IV-D-0012","t":"Lila sold 100 shares of stock in December 2026 for $16,000. Her basis was $20,000. Within 30 days she bought 60 identical shares. What loss may Lila deduct on the sale?","mc":{"s":"Lila sold 100 shares of stock in December 2026 for $16,000. Her basis was $20,000. Within 30 days she bought 60 identical shares. What loss may Lila deduct on the sale?","d":"","o":["$0","$1,600","$2,400","$4,000"],"a":2,"cite":"IRC §1091(a); Reg §1.1091-1(c)","rat":"The wash sale applies to the 60 replaced shares.","ex":["Disallows the entire loss. Only the loss on the 60 shares replaced is disallowed.","The wash sale applies to the 60 replaced shares. Disallowed loss = $4,000 x 60/100 = $2,400. Allowed = $4,000 - $2,400 = $1,600.","This is the disallowed portion, not the allowed loss.","Deducts the full loss and ignores the wash sale on the 60 replacement shares."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A wash sale disallows the loss only on the replaced shares, in proportion to shares repurchased.","from":"2026-01-01","calc":1,"steps":["Total loss = 20,000 - 16,000 = 4,000","Disallowed = 4,000 x 60/100 = 2,400","Allowed = 1,600"],"gd":[["What is the total loss?","20,000 - 16,000 = 4,000."],["How much is disallowed for the 60 replaced shares?","4,000 x 60/100 = 2,400."],["What is allowed?","4,000 - 2,400 = 1,600."]]}},{"i":"REG-IV-D-0013","t":"Cara Bell sold stock with a $20,000 basis to her brother for $14,000 in 2026, its fair market value. In 2027 the brother sold the same stock to an unrelated buyer for $24,000. What gain does the brother recognize in 2027?","mc":{"s":"Cara Bell sold stock with a $20,000 basis to her brother for $14,000 in 2026, its fair market value. In 2027 the brother sold the same stock to an unrelated buyer for $24,000. What gain does the brother recognize in 2027?","d":"","o":["$0","$4,000","$6,000","$10,000"],"a":2,"cite":"IRC §267(a)(1); IRC §267(d); Pub 544","rat":"Cara's $6,000 loss on the sale to a related person is disallowed.","ex":["Treats the whole gain as eliminated. The brother reduces his gain only by the $6,000 loss that Cara could not deduct, leaving $4,000.","Cara's $6,000 loss on the sale to a related person is disallowed. Her brother's basis is his $14,000 cost, and on his later sale he may reduce his $10,000 gain by the disallowed loss: $4,000.","This is Cara's disallowed loss, not the brother's gain.","Ignores the reduction for the disallowed loss."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A loss on a sale to a related person is disallowed, but the buyer may reduce later gain by that disallowed loss.","from":"2026-01-01","calc":1,"steps":["Brother's basis = 14,000","Realized gain = 24,000 - 14,000 = 10,000","Reduced by disallowed loss 6,000: recognized = 4,000"],"gd":[["Is the sister's loss on a sale to a related person allowed?","No, the 6,000 loss is disallowed."],["What is the brother's realized gain on his later sale?","24,000 - 14,000 = 10,000."],["How is it reduced?","By the disallowed 6,000 loss, so 10,000 - 6,000 = 4,000 recognized."]]}},{"i":"REG-IV-D-0014","t":"Nolan Pierce has a net operating loss carryforward of $100,000 from 2025. His 2026 taxable income before the NOL deduction is $70,000. What is his NOL deduction for 2026, and what NOL remains?","mc":{"s":"Nolan Pierce has a net operating loss carryforward of $100,000 from 2025. His 2026 taxable income before the NOL deduction is $70,000. What is his NOL deduction for 2026, and what NOL remains?","d":"","o":["A $70,000 deduction, with $30,000 remaining to carry forward","A $100,000 deduction, with no NOL remaining","A $56,000 deduction, with $44,000 remaining to carry forward","A $56,000 deduction, with the remaining $44,000 lost"],"a":3,"cite":"IRC §172(a)(2); IRC §172(b)(1)(A); Pub 536","rat":"For NOLs arising after 2017, the deduction is limited to 80% of taxable income before the NOL: 80% x $70,000 = $56,000.","ex":["Deducts 100% of taxable income. The post-2017 NOL deduction is limited to 80%.","The NOL deduction cannot exceed 80% of taxable income before the NOL deduction.","For NOLs arising after 2017, the deduction is limited to 80% of taxable income before the NOL: 80% x $70,000 = $56,000. The remaining $44,000 carries forward indefinitely.","The excess carries forward indefinitely for NOLs arising after 2017."],"wt":["limit","limit","","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"For NOLs arising after 2017, the deduction is limited to 80% of taxable income, with the excess carried forward indefinitely.","from":"2026-01-01","gd":[["What limit applies to post-2017 NOL deductions?","80% of taxable income before the NOL."],["What is the deduction?","80% x 70,000 = 56,000."],["What remains?","100,000 - 56,000 = 44,000, carried forward indefinitely."]]}},{"i":"REG-IV-D-0015","t":"Tom Ruiz is single and has a 2026 loss of $300,000 from a sole proprietorship that is his only business. He also earned $400,000 of wages. Assume the 2026 excess business loss threshold for a single filer is $256,000. What business loss may Tom deduct in 2026, and what happens to the rest?","mc":{"s":"Tom Ruiz is single and has a 2026 loss of $300,000 from a sole proprietorship that is his only business. He also earned $400,000 of wages. Assume the 2026 excess business loss threshold for a single filer is $256,000. What business loss may Tom deduct in 2026, and what happens to the rest?","d":"","o":["$300,000 is deductible because his wages exceed the loss","$44,000 is deductible, and $256,000 is carried forward","$256,000 is deductible, and the $44,000 excess is lost","$256,000 is deductible, and the $44,000 excess is carried forward as an NOL"],"a":4,"cite":"IRC §461(l); Form 461","rat":"The excess business loss limit disallows business losses above the threshold.","ex":["Wages do not allow additional business losses. The threshold applies to net business losses.","Reverses the amounts. The threshold is the amount that may be deducted.","The disallowed excess is carried forward as a net operating loss, not lost.","The excess business loss limit disallows business losses above the threshold. The disallowed amount is treated as an NOL carryforward."],"wt":["concept","calc","concept",""],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Excess business losses above the threshold are disallowed and carried forward as an NOL.","from":"2026-07-01","gd":[["What does the excess business loss limit do?","Disallows business losses above the threshold, here 256,000."],["How much is disallowed and how is it treated?","300,000 - 256,000 = 44,000, carried forward as an NOL."]]}},{"i":"REG-IV-D-0016","t":"Erin Shaw owns a rental property with $20,000 of suspended passive losses and has no passive income. She is considering two ways to dispose of it, each of which would occur at a price equal to her adjusted basis. Option 1: sell the entire interest to an unrelated buyer in a taxable sale. Option 2: give the property to her daughter. How much greater is Erin's allowable deduction for suspended losses in 2026 under Option 1 than under Option 2?","mc":{"s":"Erin Shaw owns a rental property with $20,000 of suspended passive losses and has no passive income. She is considering two ways to dispose of it, each of which would occur at a price equal to her adjusted basis. Option 1: sell the entire interest to an unrelated buyer in a taxable sale. Option 2: give the property to her daughter. How much greater is Erin's allowable deduction for suspended losses in 2026 under Option 1 than under Option 2?","d":"","o":["$0","$20,000","$25,000","$40,000"],"a":2,"cite":"IRC §469(g)(1), (j)(6); Pub 925","rat":"A fully taxable disposition of the entire interest to an unrelated party releases the suspended losses ($20,000).","ex":["Assumes the disposition method does not matter. A taxable sale releases the suspended losses; a gift does not.","A fully taxable disposition of the entire interest to an unrelated party releases the suspended losses ($20,000). A gift does not; the suspended losses are added to the donee's basis and are not deductible by the donor. Difference: $20,000.","Uses the $25,000 rental allowance, which is unrelated to releasing suspended losses on disposition.","Double counts the suspended loss."],"wt":["concept","","concept","calc"],"tags":{"area":"IV","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A fully taxable disposition of the entire passive interest to an unrelated party releases suspended losses; a gift does not.","from":"2026-01-01","calc":1,"steps":["Sale to unrelated party: 20,000 released","Gift: 0 released (added to donee's basis)","Difference = 20,000"],"gd":[["What happens to suspended passive losses on a fully taxable sale of the entire interest to an unrelated party?","They are released and deductible, here 20,000."],["What happens on a gift?","Nothing is released; the losses are added to the donee's basis."],["What is the difference?","20,000 - 0 = 20,000."]]}},{"i":"REG-IV-D-0017","t":"Review the exhibit for Erik Long's 2026 return, which shows a $7,000 net capital loss deducted against wages. What capital loss carryforward should be reported to 2027?","mc":{"s":"Review the exhibit for Erik Long's 2026 return, which shows a $7,000 net capital loss deducted against wages. What capital loss carryforward should be reported to 2027?","d":"","o":["$0","$3,000","$4,000","$7,000"],"a":3,"cite":"IRC §1211(b); IRC §1212(b); Pub 550","rat":"The net capital loss is $9,000 - $2,000 = $7,000.","ex":["Allows the whole $7,000 as a deduction as the draft does. The limit is $3,000.","This is the amount deductible in 2026, not the carryforward.","The net capital loss is $9,000 - $2,000 = $7,000. Only $3,000 may be deducted against ordinary income, leaving a $4,000 carryforward.","Reports the full net loss as a carryforward without deducting the $3,000 allowed."],"wt":["concept","calc","","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The net capital loss deduction is capped at $3,000, and the excess carries forward.","tb":[["Schedule D item","Amount"],["Short-term capital gain","$2,000"],["Long-term capital loss","($9,000)"],["Net capital loss","($7,000)"],["Deducted on Form 1040 (draft)","($7,000)"],["Carryforward reported (draft)","$0"]],"from":"2026-01-01","calc":1,"steps":["Net loss = 2,000 - 9,000 = 7,000","Deduct 3,000","Carryforward = 7,000 - 3,000 = 4,000"],"gd":[["What is the net capital loss?","9,000 - 2,000 = 7,000."],["How much can be deducted against ordinary income?","3,000."],["What carries forward?","7,000 - 3,000 = 4,000."]]}},{"i":"REG-IV-D-0018","t":"Review the exhibit for Bo and Meg Tran, who file jointly and have modified AGI of $135,000 before any rental loss. The draft return deducts a $30,000 loss from a rental property in which Meg actively participates against wages. They have no passive income. What rental loss is allowed in 2026?","mc":{"s":"Review the exhibit for Bo and Meg Tran, who file jointly and have modified AGI of $135,000 before any rental loss. The draft return deducts a $30,000 loss from a rental property in which Meg actively participates against wages. They have no passive income. What rental loss is allowed in 2026?","d":"","o":["$7,500","$17,500","$25,000","$30,000"],"a":1,"cite":"IRC §469(i)(2), (i)(3)(A); Pub 925","rat":"The $25,000 special allowance is reduced by 50% of the excess of MAGI over $100,000: $25,000 - 50% x $35,000 = $7,500.","ex":["The $25,000 special allowance is reduced by 50% of the excess of MAGI over $100,000: $25,000 - 50% x $35,000 = $7,500.","This is the amount of the reduction ($17,500), not the remaining allowance.","Allows the full $25,000 allowance and ignores the phase-out for modified AGI above $100,000.","Deducts the entire loss as in the draft, ignoring the passive activity loss limit."],"wt":["","calc","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The $25,000 rental allowance is reduced by 50% of MAGI above $100,000.","tb":[["Item","Amount"],["Wages","$120,000"],["Interest income","$15,000"],["Modified AGI before rental loss","$135,000"],["Rental loss deducted (draft)","$30,000"],["Passive income","$0"]],"from":"2026-01-01","calc":1,"steps":["Excess MAGI = 135,000 - 100,000 = 35,000","Reduction = 17,500","Allowance = 25,000 - 17,500 = 7,500"],"gd":[["How does the special allowance phase out?","25,000 reduced by 50% of MAGI above 100,000."],["What is the reduction?","50% x (135,000 - 100,000) = 17,500."],["What is allowed?","25,000 - 17,500 = 7,500."]]}},{"i":"REG-IV-D-0019","t":"An automated check flags a mismatch on Pranav Rao's return. His Form 1099-B shows an $8,000 loss on the sale of stock, but with $3,000 of loss disallowed as a wash sale (adjustment code W). His draft Schedule D reports the full $8,000 loss. What loss should he report on Schedule D?","mc":{"s":"An automated check flags a mismatch on Pranav Rao's return. His Form 1099-B shows an $8,000 loss on the sale of stock, but with $3,000 of loss disallowed as a wash sale (adjustment code W). His draft Schedule D reports the full $8,000 loss. What loss should he report on Schedule D?","d":"","o":["$3,000","$5,000","$8,000","$11,000"],"a":2,"cite":"IRC §1091(a), (d); Form 8949 instructions","rat":"The wash sale adjustment disallows $3,000 of the loss, so she reports a $5,000 loss.","ex":["This is the disallowed portion, not the allowed loss.","The wash sale adjustment disallows $3,000 of the loss, so she reports a $5,000 loss. The disallowed $3,000 is added to the basis of the replacement shares.","Reports the full unadjusted loss and ignores the 1099-B adjustment.","Adds the disallowed loss instead of subtracting it."],"wt":["calc","","concept","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":1},"asof":"2026-09-29","rl":"A Form 1099-B wash sale adjustment reduces the reportable loss by the disallowed amount.","from":"2026-01-01","calc":1,"steps":["Loss before adjustment 8,000","Wash sale adjustment (code W) +3,000 to proceeds/basis: loss reduced","Allowed loss = 8,000 - 3,000 = 5,000"],"gd":[["How much of the 8,000 loss does the wash sale disallow?","3,000."],["What loss is reported?","8,000 - 3,000 = 5,000, with the disallowed 3,000 added to the replacement shares' basis."]]}},{"i":"REG-IV-D-0020","t":"Two taxpayers each have $8,000 of revenue and $12,000 of expenses from an activity in 2026. Shawn's activity is a business carried on for profit. Tara's activity is a hobby. Treating Shawn's business loss as a negative amount of income and ignoring all other items, by how much does the income Tara includes from the activity exceed Shawn's result?","mc":{"s":"Two taxpayers each have $8,000 of revenue and $12,000 of expenses from an activity in 2026. Shawn's activity is a business carried on for profit. Tara's activity is a hobby. Treating Shawn's business loss as a negative amount of income and ignoring all other items, by how much does the income Tara includes from the activity exceed Shawn's result?","d":"","o":["$4,000","$8,000","$12,000","$20,000"],"a":3,"cite":"IRC §183(a)-(b); IRC §162(a); Pub 535","rat":"Shawn deducts the $4,000 loss (a $4,000 reduction), while Tara includes the $8,000 of income with no deduction.","ex":["This is only Shawn's loss and ignores Tara's inclusion.","Compares only Tara's inclusion and omits Shawn's loss deduction.","Shawn deducts the $4,000 loss (a $4,000 reduction), while Tara includes the $8,000 of income with no deduction. Tara's income is $8,000 - (-$4,000) = $12,000 more.","Adds all revenue and expenses. The difference is between the two net results."],"wt":["calc","calc","","calc"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A business loss is deductible while hobby income is taxable with no deduction, so the difference is the income plus the loss.","from":"2026-07-01","calc":1,"steps":["Shawn: 8,000 - 12,000 = (4,000) reduction to income","Tara: +8,000 income, expenses not deductible","Difference = 8,000 - (-4,000) = 12,000"],"gd":[["What is Shawn's result as a business?","8,000 - 12,000 = a 4,000 loss that reduces income."],["What is Tara's result as a hobby?","8,000 of income with no deduction for the 12,000."],["What is the difference?","8,000 - (-4,000) = 12,000."]]}},{"i":"REG-IV-D-0021","t":"Two single taxpayers each lose $70,000 on stock that becomes worthless in 2026 and each has no other capital transactions. Vic's stock qualifies as small business stock eligible for ordinary loss treatment and was originally issued to him for money. Wade's stock is ordinary stock. What is the difference between Vic's and Wade's total loss deductions against ordinary income in 2026?","mc":{"s":"Two single taxpayers each lose $70,000 on stock that becomes worthless in 2026 and each has no other capital transactions. Vic's stock qualifies as small business stock eligible for ordinary loss treatment and was originally issued to him for money. Wade's stock is ordinary stock. What is the difference between Vic's and Wade's total loss deductions against ordinary income in 2026?","d":"","o":["$20,000","$50,000","$53,000","$67,000"],"a":2,"cite":"IRC §1244(a)-(b); IRC §165(g); IRC §1211(b); Pub 550","rat":"Vic deducts $50,000 as an ordinary loss and the remaining $20,000 as a capital loss limited to $3,000: $53,000.","ex":["Uses the capital loss portion of Vic's loss as the difference.","Vic deducts $50,000 as an ordinary loss and the remaining $20,000 as a capital loss limited to $3,000: $53,000. Wade's capital loss is limited to $3,000. Difference: $50,000.","This is Vic's total deduction, not the difference from Wade's.","Assumes Vic can deduct all $70,000 as an ordinary loss. The ordinary limit for a single filer is $50,000."],"wt":["calc","","calc","limit"],"tags":{"area":"IV","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Section 1244 stock allows ordinary loss up to $50,000 for a single filer; the rest is a capital loss limited to $3,000.","from":"2026-01-01","calc":1,"steps":["Vic: ordinary 50,000 + capital 3,000 (limited) = 53,000","Wade: capital 3,000","53,000 - 3,000 = 50,000"],"gd":[["How much of Vic's loss is ordinary?","50,000, the ordinary loss limit for a single filer on eligible small business stock."],["What is Vic's total deduction?","Ordinary 50,000 plus capital loss limited to 3,000, so 53,000."],["What is Wade's and the difference?","Wade only deducts 3,000, so 53,000 - 3,000 = 50,000."]]}},{"i":"REG-IV-D-0022","t":"Zoe Marsh is a limited partner in a partnership (a passive activity for her). At the end of 2026 her outside basis is $40,000 and her at-risk amount is $30,000, before the current-year loss. Her share of the partnership's 2026 loss is $45,000. She also has $12,000 of passive income from a different passive investment. Applying the loss limitations in the proper order, what loss may she deduct in 2026?","mc":{"s":"Zoe Marsh is a limited partner in a partnership (a passive activity for her). At the end of 2026 her outside basis is $40,000 and her at-risk amount is $30,000, before the current-year loss. Her share of the partnership's 2026 loss is $45,000. She also has $12,000 of passive income from a different passive investment. Applying the loss limitations in the proper order, what loss may she deduct in 2026?","d":"","o":["$12,000","$30,000","$40,000","$45,000"],"a":1,"cite":"IRC §704(d); IRC §465; IRC §469(a), (d); Pub 925","rat":"The loss passes the basis limit ($40,000) and at-risk limit ($30,000), and the passive activity limit then allows the loss only to the extent of passive income ($12,000).","ex":["The loss passes the basis limit ($40,000) and at-risk limit ($30,000), and the passive activity limit then allows the loss only to the extent of passive income ($12,000).","Stops after the at-risk limit and ignores the passive activity rules.","Applies only the basis limitation.","Deducts the entire loss without applying basis, at-risk, or passive limits."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Loss limits apply in order: basis, at-risk, then passive activity, which allows losses up to passive income.","from":"2026-01-01","calc":1,"steps":["Basis: min(45,000, 40,000) = 40,000","At-risk: min(40,000, 30,000) = 30,000","Passive: min(30,000, 12,000 passive income) = 12,000"],"gd":[["What is the deduction after the basis limit?","min(45,000, 40,000) = 40,000."],["What follows after the at-risk limit?","min(40,000, 30,000) = 30,000."],["What does the passive limit allow?","Only passive income, min(30,000, 12,000) = 12,000."]]}},{"i":"REG-IV-D-0023","t":"Compare two taxpayers who each sold stock at a $5,000 loss on December 10, 2026, and bought identical replacement stock on December 20, 2026. Kim bought the replacement stock in her taxable brokerage account. Lee's IRA bought the replacement stock. Which statement is correct?","mc":{"s":"Compare two taxpayers who each sold stock at a $5,000 loss on December 10, 2026, and bought identical replacement stock on December 20, 2026. Kim bought the replacement stock in her taxable brokerage account. Lee's IRA bought the replacement stock. Which statement is correct?","d":"","o":["Both losses are disallowed; Kim adds the loss to the basis of the replacement stock, but Lee's disallowed loss is not added to his IRA basis","Kim's loss is disallowed and Lee's loss is allowed, because an IRA is a separate taxpayer","Both losses are allowed, because a wash sale requires the same account to buy the stock","Both losses are disallowed and both add the disallowed loss to the basis of the replacement stock"],"a":1,"cite":"IRC §1091(a), (d); Rev. Rul. 2008-5; Pub 550","rat":"The wash sale rule applies to purchases by the taxpayer's IRA as well, but the disallowed loss cannot be added to IRA basis, so it is permanently lost.","ex":["The wash sale rule applies to purchases by the taxpayer's IRA as well, but the disallowed loss cannot be added to IRA basis, so it is permanently lost.","The IRS treats a purchase by the taxpayer's own IRA as a wash sale. The IRA is not a separate taxpayer for this purpose.","The rule does not depend on the account. Purchases by the taxpayer, spouse, or IRA can trigger it.","Basis of an IRA investment does not increase for the disallowed loss, so Lee cannot recover it."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The wash sale rule applies to IRA purchases, but the disallowed loss cannot be added to IRA basis and is lost.","from":"2026-01-01","gd":[["Does a wash sale apply to a purchase by the taxpayer's IRA?","Yes, the loss is disallowed for both."],["Where does the disallowed loss go for each account?","It adds to the replacement stock basis in the taxable account but cannot add to IRA basis, so it is lost."]]}},{"i":"REG-IV-D-0024","t":"An individual's 2026 return deducts a net operating loss carryforward of $90,000 against taxable income of $100,000 before the NOL deduction. The NOL arose in 2025. What NOL deduction is allowed for 2026?","mc":{"s":"An individual's 2026 return deducts a net operating loss carryforward of $90,000 against taxable income of $100,000 before the NOL deduction. The NOL arose in 2025. What NOL deduction is allowed for 2026?","d":"","o":["$10,000","$80,000","$90,000","$100,000"],"a":2,"cite":"IRC §172(a)(2); Pub 536","rat":"For NOLs arising after 2017, the deduction is limited to 80% of taxable income before the NOL: 80% x $100,000 = $80,000, which is below the $90,000 carryforward.","ex":["This is 100% of taxable income less the carryforward, which has no meaning here.","For NOLs arising after 2017, the deduction is limited to 80% of taxable income before the NOL: 80% x $100,000 = $80,000, which is below the $90,000 carryforward.","Deducts the full carryforward. The 80% limit reduces the deduction to $80,000.","Deducts all taxable income, which the 80% limit prevents."],"wt":["concept","","limit","limit"],"tags":{"area":"IV","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The NOL deduction for post-2017 losses is limited to 80% of taxable income before the NOL.","from":"2026-01-01","calc":1,"steps":["80% x 100,000 = 80,000","Lesser of 80,000 or 90,000 = 80,000","Remaining NOL 10,000 carries forward"],"gd":[["What limits the NOL deduction for a 2025 loss?","80% of taxable income before the NOL."],["What is the limit?","80% x 100,000 = 80,000."],["Which is smaller, that or the 90,000 carryforward?","80,000, with 10,000 carried forward."]]}},{"i":"REG-IV-D-0025","t":"Review the Schedule D entries in the exhibit for Rob Cruz's 2026 return. Which entry must be removed because the loss is not deductible?","mc":{"s":"Review the Schedule D entries in the exhibit for Rob Cruz's 2026 return. Which entry must be removed because the loss is not deductible?","d":"","o":["The $5,000 loss on stock held three years","The $2,000 gain on a coin collection","The $6,000 loss on the sale of his personal car","The $1,000 loss on worthless stock"],"a":3,"cite":"IRC §165(c); Pub 544","rat":"Losses on personal-use property such as a family car are not deductible.","ex":["A loss on investment stock is deductible as a capital loss, subject to the limits.","A gain on a collectible is reportable and taxable. It is not a loss entry.","Losses on personal-use property such as a family car are not deductible.","A loss on securities that became worthless during the year is deductible as a capital loss."],"wt":["trap","trap","","trap"],"tags":{"area":"IV","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Losses on personal-use property such as a family car are not deductible, unlike investment and worthless stock losses.","tb":[["Item","Amount"],["Stock held three years, sold","($5,000)"],["Family car, sold (personal use)","($6,000)"],["Coin collection, sold","$2,000"],["Stock that became worthless in 2026","($1,000)"]],"from":"2026-01-01","gd":[["Which losses are deductible?","Losses on investment or business property, including worthless stock."],["Which entry is a personal-use loss?","The family car sale; a coin gain is only income to report."]]}},{"i":"REG-IV-D-0026","t":"Alex and Bea Cole are married. Alex has a $10,000 net capital loss and Bea has an $8,000 net capital gain, both from investment sales. Compare filing a joint return with filing separate returns. What is the difference between the combined amount added to (or subtracted from) taxable income from these capital transactions on separate returns, and on a joint return?","mc":{"s":"Alex and Bea Cole are married. Alex has a $10,000 net capital loss and Bea has an $8,000 net capital gain, both from investment sales. Compare filing a joint return with filing separate returns. What is the difference between the combined amount added to (or subtracted from) taxable income from these capital transactions on separate returns, and on a joint return?","d":"","o":["$1,500","$2,000","$8,500","$10,000"],"a":3,"cite":"IRC §1211(b); Pub 550","rat":"On a joint return the amounts are netted: $8,000 - $10,000 = $2,000 net loss, fully deductible.","ex":["Uses only Alex's separate limit.","Uses only the joint return net loss and ignores the separate return results.","On a joint return the amounts are netted: $8,000 - $10,000 = $2,000 net loss, fully deductible. Separately, Alex deducts $1,500 and Bea reports $8,000, for a net $6,500 of income. The separate-return result is $8,500 higher.","Uses the loss amount and ignores that netting on a joint return offsets the gain."],"wt":["calc","calc","","calc"],"tags":{"area":"IV","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"On a joint return capital gains and losses net together, while separate returns face the $1,500 loss limit and full gain inclusion.","from":"2026-01-01","calc":1,"steps":["Joint: 8,000 - 10,000 = (2,000)","Separate: Alex (1,500) deductible; Bea +8,000 = 6,500","6,500 - (-2,000) = 8,500"],"gd":[["What is the joint-return result?","8,000 - 10,000 = a 2,000 net loss, fully deductible."],["What is the separate-return result?","Alex deducts 1,500 and Bea reports 8,000, net 6,500 of income."],["What is the difference?","6,500 - (-2,000) = 8,500."]]}}],"5":[{"i":"REG-IV-E-0001","t":"Keiko Mori's husband died in August 2026. She has not remarried and has no dependents. What is Keiko's filing status for 2026?","mc":{"s":"Keiko Mori's husband died in August 2026. She has not remarried and has no dependents. What is Keiko's filing status for 2026?","d":"","o":["Single","Qualifying surviving spouse","Head of household","Married filing jointly"],"a":4,"cite":"IRC §7703(a); IRC §6013(a)(2); Pub 501","rat":"A taxpayer whose spouse died during the year and who has not remarried by year end may file jointly with the deceased spouse for the year of death.","ex":["Marital status is determined at year end, but a surviving spouse who has not remarried may use the joint return for the year of death.","This status applies to the two years after the year of death, and only if the taxpayer supports a dependent child.","Head of household requires an unmarried taxpayer with a qualifying person who lived with her. Keiko is considered married for 2026 and has no dependents.","A taxpayer whose spouse died during the year and who has not remarried by year end may file jointly with the deceased spouse for the year of death."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A spouse who has not remarried by year end may file jointly with the deceased spouse for the year of death.","from":"2026-01-01","gd":[["Who may file jointly in the year of a spouse's death?","A survivor who has not remarried by year end."],["What is the status for Keiko in 2026?","Married filing jointly with the deceased spouse."]]}},{"i":"REG-IV-E-0002","t":"For 2026, which unmarried taxpayer qualifies to file as head of household?","mc":{"s":"For 2026, which unmarried taxpayer qualifies to file as head of household?","d":"","o":["Jasmine, who paid more than half the cost of a home that was the main home of her 8-year-old son for the entire year","Kurt, who paid all the costs of a home in which his unrelated friend lived for the entire year","Luis, who paid more than half the cost of a home where his 12-year-old daughter lived for 5 months","Marta, whose 25-year-old son (not a student) lived with her all year and earned $20,000"],"a":1,"cite":"IRC §2(b)(1); Pub 501","rat":"Head of household requires paying more than half the cost of keeping up a home that is the main home of a qualifying person for more than half the year.","ex":["Head of household requires paying more than half the cost of keeping up a home that is the main home of a qualifying person for more than half the year.","An unrelated person who qualifies as a dependent only because she lived with the taxpayer is not a qualifying person for head of household.","The qualifying child must live with him for more than half the year.","He is not a qualifying child because of his age, and he is not a qualifying relative because his gross income is too high."],"wt":["","concept","limit","concept"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Head of household requires an unmarried taxpayer paying over half the cost of a home that is the main home of a qualifying person for over half the year.","from":"2026-01-01","gd":[["What does head of household require?","Unmarried, paying more than half the cost of a home that is the main home of a qualifying person for more than half the year."],["Which person meets that?","The one whose 8-year-old son lived with her all year; friends, short stays and a non-qualifying adult son fail."]]}},{"i":"REG-IV-E-0003","t":"Which of the following individuals may qualify as the taxpayer's qualifying relative even though the individual does not live in the taxpayer's home, assuming the support test and gross income test are met?","mc":{"s":"Which of the following individuals may qualify as the taxpayer's qualifying relative even though the individual does not live in the taxpayer's home, assuming the support test and gross income test are met?","d":"","o":["The taxpayer's first cousin, who lives in another city","An unrelated friend, who lives in another city","The taxpayer's father-in-law, who lives in his own apartment","A former neighbor, who lives in the same town"],"a":3,"cite":"IRC §152(d)(2); Pub 501","rat":"Certain relatives, including parents and in-laws, qualify as qualifying relatives without living with the taxpayer.","ex":["A cousin is not in the listed relationships. A cousin qualifies only if he lives with the taxpayer all year as a member of the household.","An unrelated person qualifies only if she lives with the taxpayer all year as a member of the household.","Certain relatives, including parents and in-laws, qualify as qualifying relatives without living with the taxpayer.","There is no relationship, and no household membership."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Parents and in-laws can be qualifying relatives without living with the taxpayer; cousins and unrelated persons must live in the household all year.","from":"2026-01-01","gd":[["Which relatives qualify as qualifying relatives without living in the taxpayer's home?","Parents, in-laws, children and certain other close relatives."],["Which listed person is in that group?","The father-in-law living in his own apartment."]]}},{"i":"REG-IV-E-0004","t":"Which of the following individuals is a qualifying child of the taxpayer for 2026? Assume each is a U.S. citizen, is unmarried, and is the taxpayer's child.","mc":{"s":"Which of the following individuals is a qualifying child of the taxpayer for 2026? Assume each is a U.S. citizen, is unmarried, and is the taxpayer's child.","d":"","o":["Cam, age 17, who lived with the taxpayer all year and paid for 60% of his own support with wages","Dee, age 22, who is not a student, is not disabled, and lived with the taxpayer all year","Eli, age 16, who lived with the taxpayer for only 4 months","Ben, age 20, a full-time student, who lived with the taxpayer all year and provided 30% of his own support"],"a":4,"cite":"IRC §152(c)(1); IRC §152(c)(3); Pub 501","rat":"A child under age 24 who is a full-time student, lives with the taxpayer for more than half the year, and does not provide more than half of his own support is a qualifying child.","ex":["A qualifying child must not provide more than half of his own support.","A child age 19 or older must be a full-time student under age 24 (or permanently disabled).","The child must live with the taxpayer for more than half the year.","A child under age 24 who is a full-time student, lives with the taxpayer for more than half the year, and does not provide more than half of his own support is a qualifying child."],"wt":["limit","concept","limit",""],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A qualifying child meets age, residency and support tests: under 19 or a full-time student under 24, lives over half the year, and does not provide over half own support.","from":"2026-01-01","gd":[["What must a child meet to be a qualifying child?","Relationship, residence for more than half the year, age, and not providing more than half of own support."],["Which child meets all tests?","The full-time student under 24 who lived with the taxpayer all year and provided 30% of his own support."]]}},{"i":"REG-IV-E-0005","t":"Rosa Vega's husband died in 2025. In 2026 she has not remarried, and she maintains a home that is the main home of her 10-year-old daughter, whom she can claim as a dependent. Rosa filed a joint return for 2025. What is Rosa's most beneficial filing status for 2026?","mc":{"s":"Rosa Vega's husband died in 2025. In 2026 she has not remarried, and she maintains a home that is the main home of her 10-year-old daughter, whom she can claim as a dependent. Rosa filed a joint return for 2025. What is Rosa's most beneficial filing status for 2026?","d":"","o":["Qualifying surviving spouse","Married filing jointly","Head of household","Single"],"a":1,"cite":"IRC §2(a); IRC §7703(a); Pub 501","rat":"For two years following the year of death, a taxpayer with a dependent child who has not remarried may use qualifying surviving spouse status, with the joint return rates and standard deduction.","ex":["For two years following the year of death, a taxpayer with a dependent child who has not remarried may use qualifying surviving spouse status, with the joint return rates and standard deduction.","She is not married at the end of 2026, and the spouse is deceased, so she cannot file jointly for 2026.","She qualifies, but head of household has a lower standard deduction and less favorable rates than qualifying surviving spouse.","She has a qualifying option with more favorable rates and a larger standard deduction than single."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A qualifying surviving spouse with a dependent child may use joint rates for two years after the year of death.","from":"2026-01-01","gd":[["For how many years after the year of death can a qualifying surviving spouse status be used?","Two years."],["Does Rosa meet the conditions and what does it give?","She has a dependent child and has not remarried, so she gets joint rates and the joint standard deduction."]]}},{"i":"REG-IV-E-0006","t":"Nadia is legally separated from her husband under a decree of separate maintenance as of December 31, 2026, has no children, and does not qualify for any other special filing status. What is her filing status for 2026?","mc":{"s":"Nadia is legally separated from her husband under a decree of separate maintenance as of December 31, 2026, has no children, and does not qualify for any other special filing status. What is her filing status for 2026?","d":"","o":["Married filing jointly","Married filing separately","Single","Qualifying surviving spouse"],"a":3,"cite":"IRC §7703(a)(2); Pub 501","rat":"A taxpayer legally separated under a decree of divorce or separate maintenance at year end is treated as unmarried and files as single (or head of household if she qualifies).","ex":["She is not considered married for the year because of the decree.","She is treated as unmarried under the decree, so married filing separately does not apply.","A taxpayer legally separated under a decree of divorce or separate maintenance at year end is treated as unmarried and files as single (or head of household if she qualifies).","This status requires the spouse to have died, and a dependent child."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A taxpayer legally separated by decree of separate maintenance at year end is treated as unmarried and files as single or head of household.","from":"2026-01-01","gd":[["How is a taxpayer legally separated under a decree of separate maintenance treated at year end?","As unmarried."],["Which status does Nadia use with no children?","Single."]]}},{"i":"REG-IV-E-0007","t":"Eva Lindqvist's husband moved out on March 1, 2026, and they lived apart for the rest of the year. They are still legally married. Their 9-year-old son lived with Eva all year, and Eva paid more than half the cost of keeping up the home. Which filing status is available to Eva for 2026 because she is treated as unmarried?","mc":{"s":"Eva Lindqvist's husband moved out on March 1, 2026, and they lived apart for the rest of the year. They are still legally married. Their 9-year-old son lived with Eva all year, and Eva paid more than half the cost of keeping up the home. Which filing status is available to Eva for 2026 because she is treated as unmarried?","d":"","o":["Married filing jointly","Single","Qualifying surviving spouse","Head of household"],"a":4,"cite":"IRC §7703(b); IRC §2(b); Pub 501","rat":"A married taxpayer whose spouse did not live in the home for the last six months of the year, who pays more than half the cost of the home and has a qualifying child living with her, is considered unmarried and may file as head of household.","ex":["Joint filing requires treatment as married. Under the abandoned spouse rules she is considered unmarried for 2026.","She qualifies for the more favorable head of household status.","Her spouse has not died, and this status requires a deceased spouse.","A married taxpayer whose spouse did not live in the home for the last six months of the year, who pays more than half the cost of the home and has a qualifying child living with her, is considered unmarried and may file as head of household."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A married taxpayer whose spouse left the home for the last six months and who keeps up a home for a qualifying child may file as head of household.","from":"2026-01-01","gd":[["What lets a married taxpayer be treated as unmarried?","The spouse did not live in the home for the last six months, she pays more than half the cost, and a qualifying child lives with her."],["Which status does that allow?","Head of household."]]}},{"i":"REG-IV-E-0008","t":"Pia and her former husband divorced. Their 8-year-old son lived with Pia for more than half of 2026. Pia signed Form 8332 releasing her claim to the child for 2026 to her former husband. Which statement is correct?","mc":{"s":"Pia and her former husband divorced. Their 8-year-old son lived with Pia for more than half of 2026. Pia signed Form 8332 releasing her claim to the child for 2026 to her former husband. Which statement is correct?","d":"","o":["The former husband may claim the child tax credit for the son, but Pia may still use the son to file as head of household","The former husband may claim the child tax credit and file as head of household because of the son","Pia loses head of household status because she released her claim to the child","The release is invalid unless it is attached by the custodial parent for each future year"],"a":1,"cite":"IRC §152(e); IRC §2(b); Pub 501","rat":"Form 8332 lets the noncustodial parent claim the child tax credit and dependent status, but only the custodial parent may claim head of household status.","ex":["Form 8332 lets the noncustodial parent claim the child tax credit and dependent status, but only the custodial parent may claim head of household status.","Head of household status stays with the custodial parent, even if she releases the dependency claim.","Head of household is based on where the child lives, not on who claims the dependency.","A release can be for a single year or for multiple years; a release for 2026 is valid."],"wt":["","concept","concept","trap"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Form 8332 releases the child tax credit claim to the noncustodial parent, but only the custodial parent may file as head of household.","from":"2026-01-01","gd":[["What does Form 8332 release?","The child tax credit and dependency claim to the noncustodial parent."],["Who can still claim head of household status?","Only the custodial parent, so Pia keeps it."]]}},{"i":"REG-IV-E-0009","t":"Five siblings each provide 20% of the support of their mother, who has no income and lives in her own home. No sibling provides more than half of her support. Which statement is correct?","mc":{"s":"Five siblings each provide 20% of the support of their mother, who has no income and lives in her own home. No sibling provides more than half of her support. Which statement is correct?","d":"","o":["No sibling may claim her, because no one provides more than half of her support","Each sibling claims 20% of the dependency","One sibling who provides more than 10% may claim the mother as a dependent if the other siblings sign written statements waiving their claim","Any sibling who wishes may claim her, without written statements from the others"],"a":3,"cite":"IRC §152(d)(3); Pub 501","rat":"Under a multiple support agreement, any one contributor of more than 10% may claim the dependent if the others who could have claimed her agree in writing.","ex":["A multiple support agreement lets one of the group claim her despite the support test.","A dependent cannot be split among taxpayers; only one taxpayer claims the dependent.","Under a multiple support agreement, any one contributor of more than 10% may claim the dependent if the others who could have claimed her agree in writing.","Signed statements are required, and Form 2120 is attached to the return."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Under a multiple support agreement, one contributor of more than 10% may claim the dependent if the other eligible contributors agree in writing.","from":"2026-01-01","gd":[["What rule covers a dependent supported by several people none of whom pays over half?","A multiple support agreement."],["Who may claim the mother and what is needed?","One contributor of more than 10%, with written statements from the others who could have claimed her."]]}},{"i":"REG-IV-E-0010","t":"Kira Tan, single and age 30, had $12,000 of wages in 2026, and net earnings from a freelance business of $500 (before self-employment tax adjustments). She had no other income. Assume her gross income is below her standard deduction. Which statement is correct?","mc":{"s":"Kira Tan, single and age 30, had $12,000 of wages in 2026, and net earnings from a freelance business of $500 (before self-employment tax adjustments). She had no other income. Assume her gross income is below her standard deduction. Which statement is correct?","d":"","o":["Kira does not have to file, because her gross income is below the standard deduction","Kira must file only if she owes income tax","Kira must file only if her net earnings exceed $5,000","Kira must file a return because her net earnings from self-employment were at least $400"],"a":4,"cite":"IRC §6012(a)(1); IRC §6017; Pub 501","rat":"A person with net earnings from self-employment of $400 or more must file a return, even if gross income is below the standard deduction.","ex":["The gross income test does not override the filing requirement for self-employment income.","Filing is required because of the self-employment income, regardless of whether she owes income tax.","The self-employment filing threshold is $400.","A person with net earnings from self-employment of $400 or more must file a return, even if gross income is below the standard deduction."],"wt":["concept","concept","limit",""],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A person with net self-employment earnings of $400 or more must file a return regardless of gross income or tax owed.","from":"2026-01-01","gd":[["What is the self-employment filing threshold?","Net earnings from self-employment of 400 or more."],["Does Kira meet it?","Yes, so she must file even though her gross income is below the standard deduction."]]}},{"i":"REG-IV-E-0011","t":"Drew Ames, age 16, is claimed as a dependent on his parents' 2026 return. He earned $4,000 from a summer job and had $1,200 of interest income. Assume the 2026 standard deduction for a dependent is the greater of $1,350 or earned income plus $450, but no more than $16,100. What is Drew's taxable income?","mc":{"s":"Drew Ames, age 16, is claimed as a dependent on his parents' 2026 return. He earned $4,000 from a summer job and had $1,200 of interest income. Assume the 2026 standard deduction for a dependent is the greater of $1,350 or earned income plus $450, but no more than $16,100. What is Drew's taxable income?","d":"","o":["$0","$750","$3,850","$5,200"],"a":2,"cite":"IRC §63(c)(5); Pub 501","rat":"AGI is $5,200.","ex":["Uses the regular $16,100 standard deduction. A dependent's standard deduction is limited.","AGI is $5,200. His standard deduction is the greater of $1,350 or $4,000 + $450 = $4,450, so $4,450. Taxable income = $5,200 - $4,450 = $750.","Uses only the $1,350 minimum. The deduction is increased to earned income plus $450.","Allows no standard deduction."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A dependent's standard deduction is the greater of the minimum or earned income plus $450, capped at the regular amount.","from":"2026-07-01","calc":1,"steps":["AGI = 4,000 + 1,200 = 5,200","Standard deduction = greater of 1,350 or 4,000 + 450 = 4,450","Taxable income = 5,200 - 4,450 = 750"],"gd":[["What is Drew's AGI?","4,000 + 1,200 = 5,200."],["What is his standard deduction?","The greater of 1,350 or 4,000 + 450 = 4,450, so 4,450."],["What is taxable income?","5,200 - 4,450 = 750."]]}},{"i":"REG-IV-E-0012","t":"Sue Grant provides 60% of the support for her mother. Her mother's 2026 income consists of $12,000 of Social Security benefits (not taxable), $3,000 of taxable interest, and $1,500 of dividends. Her mother lives in her own home. Assume the 2026 gross income limit for a qualifying relative is $5,300. Which statement is correct?","mc":{"s":"Sue Grant provides 60% of the support for her mother. Her mother's 2026 income consists of $12,000 of Social Security benefits (not taxable), $3,000 of taxable interest, and $1,500 of dividends. Her mother lives in her own home. Assume the 2026 gross income limit for a qualifying relative is $5,300. Which statement is correct?","d":"","o":["Her mother meets the gross income test, because her gross income is $4,500","Her mother fails the gross income test, because her total income is $16,500","Her mother fails the support test, because she pays for her own housing","Her mother cannot be a qualifying relative because she does not live with Sue"],"a":1,"cite":"IRC §152(d)(1); IRC §152(d)(2)(C); Pub 501","rat":"Gross income for the dependency test excludes nontaxable Social Security benefits: $3,000 + $1,500 = $4,500, below the limit.","ex":["Gross income for the dependency test excludes nontaxable Social Security benefits: $3,000 + $1,500 = $4,500, below the limit. The mother is a qualifying relative.","Nontaxable Social Security benefits are not part of gross income.","The support test is met if Sue provides more than half of her total support, which she does (60%).","A parent qualifies as a qualifying relative without living with the taxpayer."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Nontaxable Social Security is excluded from gross income in the qualifying relative gross income test.","from":"2026-01-01","gd":[["Is nontaxable Social Security counted in gross income for the dependency test?","No."],["What is the mother's gross income and does it meet the limit?","3,000 + 1,500 = 4,500, below 5,300, so she is a qualifying relative."]]}},{"i":"REG-IV-E-0013","t":"An unmarried taxpayer with a qualifying child is deciding between filing as single and filing as head of household for 2026. Assume the 2026 standard deduction is $16,100 for single and $24,150 for head of household, and the taxpayer's marginal rate is 22%. Considering only the difference in the standard deduction, by how much does head of household status reduce the tax?","mc":{"s":"An unmarried taxpayer with a qualifying child is deciding between filing as single and filing as head of household for 2026. Assume the 2026 standard deduction is $16,100 for single and $24,150 for head of household, and the taxpayer's marginal rate is 22%. Considering only the difference in the standard deduction, by how much does head of household status reduce the tax?","d":"","o":["$1,771","$3,542","$5,313","$8,050"],"a":1,"cite":"IRC §63(c)(2); Pub 501","rat":"The extra standard deduction is $8,050.","ex":["The extra standard deduction is $8,050. At a 22% marginal rate, the tax reduction is $1,771.","Doubles the tax effect by applying the rate to twice the difference in deductions.","Applies the rate to the whole head of household standard deduction, not the difference.","This is the difference in the deductions, not the tax effect."],"wt":["","calc","calc","calc"],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Head of household's tax saving equals the extra standard deduction times the marginal rate.","from":"2026-07-01","calc":1,"steps":["24,150 - 16,100 = 8,050","8,050 x 22% = 1,771"],"gd":[["What is the extra standard deduction for head of household?","24,150 - 16,100 = 8,050."],["What is the tax reduction at 22%?","8,050 x 22% = 1,771."]]}},{"i":"REG-IV-E-0014","t":"Compare filing separately with filing jointly for a married couple. Which statement about married filing separately is correct?","mc":{"s":"Compare filing separately with filing jointly for a married couple. Which statement about married filing separately is correct?","d":"","o":["Each spouse may independently choose between the standard deduction and itemizing","Spouses filing separately may each claim the American opportunity credit","If one spouse itemizes deductions, the other spouse must also itemize, and cannot claim the standard deduction","Each spouse may deduct up to $3,000 of net capital losses"],"a":3,"cite":"IRC §63(c)(6)(A); IRC §25A(g)(6); IRC §1211(b); Pub 501","rat":"Spouses filing separately must both itemize or both take the standard deduction.","ex":["The choice is linked. If one spouse itemizes, the other's standard deduction is zero.","Married taxpayers filing separately cannot claim the American opportunity or lifetime learning credits.","Spouses filing separately must both itemize or both take the standard deduction.","The limit for married filing separately is $1,500 per spouse."],"wt":["concept","concept","","limit"],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Spouses filing separately must both itemize or both take the standard deduction, and lose education credits.","from":"2026-01-01","gd":[["Must married-filing-separately spouses use the same deduction method?","Yes, both itemize or both take the standard deduction."],["Which listed statement is that?","If one spouse itemizes, the other cannot claim the standard deduction."]]}},{"i":"REG-IV-E-0015","t":"Review the exhibit for Ted Brill's 2026 return, which claims head of household status. Which correction is required?","mc":{"s":"Review the exhibit for Ted Brill's 2026 return, which claims head of household status. Which correction is required?","d":"","o":["Change the filing status to married filing jointly, because the divorce was not final until December 15","Change the filing status to qualifying surviving spouse, because he supports a child","No change, because he paid more than half the costs of his home","Change the filing status to single, because his son did not live with him for more than half the year"],"a":4,"cite":"IRC §2(b)(1)(A); IRC §7703(a); Pub 501","rat":"Head of household requires that the qualifying child live with the taxpayer for more than half the year.","ex":["The divorce was final before year end, so Ted is unmarried for the year.","This status requires that a spouse died in one of the two preceding years.","Paying half the costs is only one requirement. The residency test is not met.","Head of household requires that the qualifying child live with the taxpayer for more than half the year. The son lived with Ted only 5 months."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Head of household requires the qualifying child to live with the taxpayer for more than half the year.","tb":[["Fact","Detail"],["Divorce decree final","December 15, 2026"],["Son (age 7) lived with Ted","5 months (August through December)"],["Son lived with his mother","7 months"],["Ted's share of household costs","100% of his own apartment"],["Filing status on draft","Head of household"]],"from":"2026-01-01","gd":[["What must be true of the child's residence for head of household?","The qualifying child lives with the taxpayer for more than half the year."],["Did the son live with Ted more than half the year?","No, only 5 of 12 months, so Ted files as single."]]}},{"i":"REG-IV-E-0016","t":"Review the exhibit for Jo Reyes's 2026 return. She claimed her daughter Lea as a qualifying child. Which statement is correct?","mc":{"s":"Review the exhibit for Jo Reyes's 2026 return. She claimed her daughter Lea as a qualifying child. Which statement is correct?","d":"","o":["Lea is not a qualifying child because she is age 24, but she may be a qualifying relative if Jo provides more than half her support and Lea's gross income is under the limit","Lea is a qualifying child, because she is a full-time student","Lea is a qualifying child, because she lived with Jo all year","Lea cannot be claimed as any type of dependent, because she is over age 23"],"a":1,"cite":"IRC §152(c)(3); IRC §152(d); Pub 501","rat":"The age test requires a child under age 24 (for students).","ex":["The age test requires a child under age 24 (for students). Lea is 24, so she fails as a qualifying child, though she may still qualify as a qualifying relative.","Full-time students must be under age 24 at year end.","Residency is met, but the age test is not.","Lea may still qualify as a qualifying relative, which has no age test."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A qualifying child must be under 24 if a student; a child who fails may still be a qualifying relative, which has no age test.","tb":[["Fact","Detail"],["Lea's age on December 31, 2026","24"],["Full-time student","Yes, all year"],["Lived with Jo","All year"],["Lea's gross income","$3,000"],["Jo's share of Lea's support","70%"],["Claimed on draft return","Qualifying child"]],"from":"2026-01-01","gd":[["What is the age test for a student qualifying child?","Under age 24."],["Where does Lea, age 24, stand, and what alternative remains?","She fails as a qualifying child but may be a qualifying relative if Jo provides more than half her support and gross income is under the limit."]]}},{"i":"REG-IV-E-0017","t":"An automated check flags that both Mia and her former husband Jon claimed their son on their 2026 returns. They are divorced with no Form 8332. The son lived with Mia for 200 nights and with Jon for 165 nights. Which statement is correct?","mc":{"s":"An automated check flags that both Mia and her former husband Jon claimed their son on their 2026 returns. They are divorced with no Form 8332. The son lived with Mia for 200 nights and with Jon for 165 nights. Which statement is correct?","d":"","o":["Jon may claim the son, because he pays more of the support","Each parent may claim half of the benefits","Mia may claim the son, because she is the custodial parent (the parent with whom he lived more nights)","The parent with the higher AGI may claim the son"],"a":3,"cite":"IRC §152(e); IRC §152(c)(4); Pub 501","rat":"For divorced parents, the custodial parent is the one with whom the child lived for the greater number of nights.","ex":["For a divorced child, the custodial parent claims the child, unless a release is signed.","A child may be claimed by only one taxpayer for a given year.","For divorced parents, the custodial parent is the one with whom the child lived for the greater number of nights. The noncustodial parent needs Form 8332.","The higher-AGI tiebreaker applies only if the child lived with each parent an equal amount of time, or in some cases with no parent."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"For divorced parents without Form 8332, the custodial parent is the one with whom the child lived more nights.","from":"2026-01-01","gd":[["For divorced parents without Form 8332, who is the custodial parent?","The parent with whom the child lived more nights."],["Who is that here?","Mia, with 200 nights against 165."]]}},{"i":"REG-IV-E-0018","t":"Review the exhibit for Nora Blake's 2026 return, which claims qualifying surviving spouse status. Which correction is required?","mc":{"s":"Review the exhibit for Nora Blake's 2026 return, which claims qualifying surviving spouse status. Which correction is required?","d":"","o":["Change the status to married filing jointly, because her spouse died in 2025","Change the status to head of household, because she is unmarried","No change, because her spouse died within the last two years","Change the status to single, because Nora has no dependent child"],"a":4,"cite":"IRC §2(a); Pub 501","rat":"Qualifying surviving spouse status requires a dependent child.","ex":["Joint filing with a deceased spouse is available only for the year of death.","Head of household requires a qualifying person, and she has none.","The two-year window is not enough. She must also maintain a home for a dependent child.","Qualifying surviving spouse status requires a dependent child. Without one, Nora is single."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Qualifying surviving spouse status requires a dependent child; without one the taxpayer files as single.","tb":[["Fact","Detail"],["Spouse died","2025"],["Remarried","No"],["Dependent children","None"],["Filing status on draft","Qualifying surviving spouse"]],"from":"2026-01-01","gd":[["What does qualifying surviving spouse status require besides a recent death and no remarriage?","A dependent child."],["Does Nora have one?","No, so she files as single."]]}}],"6":[{"i":"REG-IV-F-0001","t":"Which of the following credits can result in a refund even when it exceeds the taxpayer's income tax liability?","mc":{"s":"Which of the following credits can result in a refund even when it exceeds the taxpayer's income tax liability?","d":"","o":["The earned income credit","The lifetime learning credit","The credit for child and dependent care expenses","The foreign tax credit"],"a":1,"cite":"IRC §32; IRC §25A(c); IRC §21; IRC §27; Pub 596","rat":"The earned income credit is fully refundable.","ex":["The earned income credit is fully refundable. Any amount above the tax liability is paid to the taxpayer.","The lifetime learning credit is nonrefundable and can only reduce tax to zero.","The dependent care credit is nonrefundable for individuals.","The foreign tax credit is nonrefundable and limited to U.S. tax on foreign income."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The earned income credit is refundable, while the lifetime learning, dependent care and foreign tax credits are nonrefundable.","from":"2026-01-01","gd":[["What is a refundable credit?","One that pays out above the tax liability."],["Which listed credit is fully refundable?","The earned income credit; the others only reduce tax to zero."]]}},{"i":"REG-IV-F-0002","t":"For a calendar-year individual, what is the due date of the fourth required installment of 2026 estimated tax?","mc":{"s":"For a calendar-year individual, what is the due date of the fourth required installment of 2026 estimated tax?","d":"","o":["December 31, 2026","January 31, 2027","January 15, 2027","April 15, 2027"],"a":3,"cite":"IRC §6654(c)(2); Pub 505","rat":"The four installments for a calendar-year individual are due April 15, June 15, and September 15 of the tax year and January 15 of the following year.","ex":["The fourth installment is not due at the end of the tax year.","January 31 is the due date for many information returns, not the estimated tax installment.","The four installments for a calendar-year individual are due April 15, June 15, and September 15 of the tax year and January 15 of the following year.","April 15, 2027 is the due date of the 2026 return and the first installment for 2027."],"wt":["limit","limit","","limit"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Calendar-year individual estimated tax installments are due April 15, June 15, September 15 and January 15 of the next year.","from":"2026-01-01","gd":[["What are the four installment dates?","April 15, June 15, September 15 of the tax year, and a date in January of the next year."],["Which date is the fourth?","January 15, 2027."]]}},{"i":"REG-IV-F-0003","t":"Aaron Chen's 2025 adjusted gross income was $210,000 and his 2025 tax was $40,000. He expects his 2026 tax to be $55,000. To avoid the estimated tax penalty for 2026 by using the prior-year safe harbor, what must his required annual payment be at least?","mc":{"s":"Aaron Chen's 2025 adjusted gross income was $210,000 and his 2025 tax was $40,000. He expects his 2026 tax to be $55,000. To avoid the estimated tax penalty for 2026 by using the prior-year safe harbor, what must his required annual payment be at least?","d":"","o":["100% of his 2025 tax","90% of his 2025 tax","110% of his 2026 tax","110% of his 2025 tax"],"a":4,"cite":"IRC §6654(d)(1)(B)-(C); Pub 505","rat":"Because his prior-year AGI exceeded $150,000, the prior-year safe harbor is 110% of the 2025 tax.","ex":["The 100% safe harbor applies only when prior-year AGI was $150,000 or less.","The 90% rule applies to the current-year tax, not to the prior-year tax.","The 110% factor applies to the prior-year tax. The current-year safe harbor is 90%.","Because his prior-year AGI exceeded $150,000, the prior-year safe harbor is 110% of the 2025 tax."],"wt":["limit","concept","concept",""],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"If prior-year AGI exceeds $150,000, the prior-year safe harbor is 110% of last year's tax.","from":"2026-01-01","gd":[["What is Aaron's prior-year AGI and what does that trigger?","210,000, above 150,000."],["What safe harbor percentage applies?","110% of the 2025 tax."]]}},{"i":"REG-IV-F-0004","t":"Tim Ross's total tax for 2026 was $8,400. Federal income tax withholding was $7,500, and he made no estimated payments. His prior-year tax was $9,000. What is the estimated tax penalty consequence?","mc":{"s":"Tim Ross's total tax for 2026 was $8,400. Federal income tax withholding was $7,500, and he made no estimated payments. His prior-year tax was $9,000. What is the estimated tax penalty consequence?","d":"","o":["No penalty applies, because the tax due after withholding is less than $1,000","A penalty applies, because withholding was less than 90% of the current-year tax","A penalty applies, because he made no estimated tax payments","A penalty applies, unless he pays the entire $900 by April 15"],"a":1,"cite":"IRC §6654(e)(1); Pub 505","rat":"There is no addition to tax if the tax shown on the return, less withholding, is under $1,000.","ex":["There is no addition to tax if the tax shown on the return, less withholding, is under $1,000. Here it is $900.","Withholding was 89.3%, but the under-$1,000 exception applies, so there is no penalty.","Withholding counts as payments, and the exception applies when the amount owed is under $1,000.","The exception applies automatically. Paying by April 15 avoids interest and late payment penalties, but not this rule."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"No estimated tax penalty applies if tax due after withholding is under $1,000.","from":"2026-01-01","gd":[["What is the tax due after withholding?","8,400 - 7,500 = 900."],["Is it below the penalty threshold?","Yes, under 1,000, so no addition to tax applies."]]}},{"i":"REG-IV-F-0005","t":"Which rate schedule applies to the taxable income of a qualifying surviving spouse?","mc":{"s":"Which rate schedule applies to the taxable income of a qualifying surviving spouse?","d":"","o":["The single rate schedule","The head of household rate schedule","The married filing jointly rate schedule","The married filing separately rate schedule"],"a":3,"cite":"IRC §1(a)-(d); IRC §2(a); Pub 501","rat":"A qualifying surviving spouse uses the joint return rates and the joint standard deduction.","ex":["Single rates apply to unmarried individuals who are not heads of household or surviving spouses.","A qualifying surviving spouse gets more favorable rates than head of household.","A qualifying surviving spouse uses the joint return rates and the joint standard deduction.","This schedule applies to married individuals who file separate returns."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A qualifying surviving spouse uses the married filing jointly rates and standard deduction.","from":"2026-01-01","gd":[["Which rates and standard deduction does a qualifying surviving spouse use?","The joint return rates and joint standard deduction."],["Which schedule is that?","Married filing jointly."]]}},{"i":"REG-IV-F-0006","t":"Which of the following is included in net investment income for purposes of the 3.8% net investment income tax?","mc":{"s":"Which of the following is included in net investment income for purposes of the 3.8% net investment income tax?","d":"","o":["Wages received from an employer","Social Security benefits","Interest on a bond issued by the taxpayer's home state","Gain on the sale of investment stock"],"a":4,"cite":"IRC §1411(c)(1); Pub 505","rat":"Net investment income includes interest, dividends, capital gains, rents, and royalties (unless derived in the ordinary course of a trade or business).","ex":["Wages are earned income and are not net investment income.","Social Security benefits are not net investment income.","Tax-exempt interest is excluded from net investment income.","Net investment income includes interest, dividends, capital gains, rents, and royalties (unless derived in the ordinary course of a trade or business)."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Net investment income includes interest, dividends, capital gains, rents and royalties, but not wages, Social Security or tax-exempt interest.","from":"2026-01-01","gd":[["What does net investment income include?","Interest, dividends, capital gains, rents and royalties outside an active business."],["Which listed item is that?","Gain on the sale of investment stock; wages, Social Security and home-state bond interest are excluded."]]}},{"i":"REG-IV-F-0007","t":"Which of the following items is an adjustment or preference item that increases alternative minimum taxable income for an individual?","mc":{"s":"Which of the following items is an adjustment or preference item that increases alternative minimum taxable income for an individual?","d":"","o":["The bargain element on the exercise of incentive stock options in the year of exercise, if the shares are not sold","Interest on a general obligation bond issued by the taxpayer's home state","A cash contribution to a public charity","Home mortgage interest on acquisition debt"],"a":1,"cite":"IRC §56(b)(3); IRC §422; Form 6251 instructions","rat":"The excess of the stock's value over the exercise price is an AMT adjustment in the year of exercise, although it is not regular taxable income.","ex":["The excess of the stock's value over the exercise price is an AMT adjustment in the year of exercise, although it is not regular taxable income.","Interest on ordinary municipal bonds is exempt from both regular tax and the AMT.","Charitable contributions are allowed for AMT purposes and are not an adjustment.","Qualified housing interest is allowed for AMT."],"wt":["","concept","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The bargain element of unsold incentive stock options is an AMT adjustment; municipal interest, charitable gifts and qualified mortgage interest are not.","from":"2026-01-01","gd":[["What is the ISO bargain element in the year of exercise?","The excess of stock value over exercise price, not regular income if shares are unsold."],["How is it treated for AMT?","It is an AMT adjustment that increases alternative minimum taxable income."]]}},{"i":"REG-IV-F-0008","t":"In 2026, Dee paid alternative minimum tax caused entirely by the exercise of incentive stock options, a deferral item. In which way may she recover the AMT paid?","mc":{"s":"In 2026, Dee paid alternative minimum tax caused entirely by the exercise of incentive stock options, a deferral item. In which way may she recover the AMT paid?","d":"","o":["Through an immediate refund of the AMT","She cannot recover it, because AMT is a permanent tax","Through the minimum tax credit, which reduces regular tax in later years to the extent it exceeds the tentative minimum tax","Through a deduction against ordinary income in 2026"],"a":3,"cite":"IRC §53(a)-(c); Form 8801 instructions","rat":"AMT paid on deferral items generates a minimum tax credit carried forward indefinitely against regular tax in later years.","ex":["The credit is nonrefundable and is used only against later regular tax.","AMT caused by deferral items is recoverable through the credit.","AMT paid on deferral items generates a minimum tax credit carried forward indefinitely against regular tax in later years.","AMT is recovered as a credit and not as a deduction."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"AMT paid on deferral items such as ISO exercises generates a nonrefundable minimum tax credit carried forward against later regular tax.","from":"2026-01-01","gd":[["What kind of AMT item is an incentive stock option exercise?","A deferral item."],["How is AMT on deferral items recovered?","Through the minimum tax credit carried forward indefinitely against regular tax."]]}},{"i":"REG-IV-F-0009","t":"Which of the following children is subject to the kiddie tax on unearned income for 2026? Each has $6,500 of interest and dividend income, no earned income, and a living parent.","mc":{"s":"Which of the following children is subject to the kiddie tax on unearned income for 2026? Each has $6,500 of interest and dividend income, no earned income, and a living parent.","d":"","o":["Nell, age 20, who is not a student and provides all her own support","Owen, age 30, who is a full-time employee","Pam, age 16, who is married and files a joint return with her spouse","Max, age 15, who is claimed as a dependent by his parents"],"a":4,"cite":"IRC §1(g)(2); Form 8615 instructions; Pub 929","rat":"The kiddie tax applies to a child under 19 (or a full-time student under 24 whose earned income does not exceed half of support) with unearned income above the threshold.","ex":["She is too old for the rules and is not a student, so her income is taxed at her own rates.","The kiddie tax applies only to children within the age limits.","A child who files a joint return is not subject to the kiddie tax.","The kiddie tax applies to a child under 19 (or a full-time student under 24 whose earned income does not exceed half of support) with unearned income above the threshold."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The kiddie tax applies to a child under 19, or a full-time student under 24, who has unearned income above the threshold and a living parent.","from":"2026-01-01","gd":[["Who is subject to the kiddie tax?","A child under 19, or a full-time student under 24 in certain cases, with unearned income above the threshold."],["Which listed child fits?","The 15-year-old dependent of his parents."]]}},{"i":"REG-IV-F-0010","t":"For 2026, which dependent qualifies for the child tax credit? Assume the taxpayer's income is below all phase-out ranges.","mc":{"s":"For 2026, which dependent qualifies for the child tax credit? Assume the taxpayer's income is below all phase-out ranges.","d":"","o":["A 16-year-old daughter who has a Social Security number and lives with the taxpayer all year","A 17-year-old son who has a Social Security number","A 12-year-old nephew who has only an individual taxpayer identification number (ITIN)","A 9-year-old niece who lived with the taxpayer for 3 months of the year"],"a":1,"cite":"IRC §24(c), (h); Pub 972","rat":"The credit requires a qualifying child under 17 at year end with a valid Social Security number.","ex":["The credit requires a qualifying child under 17 at year end with a valid Social Security number.","A child must be under 17 at the end of the year. A 17-year-old may qualify only for the smaller credit for other dependents.","The child must have a Social Security number valid for employment.","A qualifying child must live with the taxpayer for more than half the year."],"wt":["","limit","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The child tax credit requires a qualifying child under 17 with a valid SSN who lives with the taxpayer more than half the year.","from":"2026-07-01","gd":[["What does the child tax credit require?","A qualifying child under 17 at year end with a valid Social Security number."],["Which dependent meets both conditions and residence?","The 16-year-old with a Social Security number living with the taxpayer all year."]]}},{"i":"REG-IV-F-0011","t":"For 2026, which taxpayer is eligible for the earned income credit? Assume each has a valid Social Security number and the 2026 investment income limit is $12,200.","mc":{"s":"For 2026, which taxpayer is eligible for the earned income credit? Assume each has a valid Social Security number and the 2026 investment income limit is $12,200.","d":"","o":["A single taxpayer with no children, $30,000 of earned income, and $15,000 of investment income","A single taxpayer with a child, $10,000 of Social Security benefits, and no earned income","A married couple filing jointly with two children, $30,000 of earned income, and $1,000 of interest income","A taxpayer who is a nonresident alien for the whole year with $20,000 of U.S. wages"],"a":3,"cite":"IRC §32(a), (c), (i); Pub 596","rat":"An eligible taxpayer needs earned income, a valid SSN, and investment income within the limit.","ex":["Investment income above the limit disqualifies the taxpayer.","The credit requires earned income; Social Security benefits are not earned income.","An eligible taxpayer needs earned income, a valid SSN, and investment income within the limit. Married couples filing jointly may claim the credit.","A nonresident alien cannot claim the earned income credit, except in limited elections."],"wt":["limit","concept","","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The earned income credit requires earned income, a valid SSN, investment income within the limit and not being a nonresident alien.","from":"2026-01-01","gd":[["What does the earned income credit require?","Earned income, a valid Social Security number, and investment income within the limit."],["Which taxpayer meets all of these?","The married couple filing jointly with two children, 30,000 of earned income and only 1,000 of interest; the others have excess investment income, no earned income, or nonresident alien status."]]}},{"i":"REG-IV-F-0012","t":"For the American opportunity credit, which of the following expenses of an eligible student in the first four years of postsecondary education qualifies?","mc":{"s":"For the American opportunity credit, which of the following expenses of an eligible student in the first four years of postsecondary education qualifies?","d":"","o":["Room and board while attending school","Interest on the student's education loans","Transportation to and from campus","Tuition and fees required for enrollment, and required course materials"],"a":4,"cite":"IRC §25A(b)(1), (f); Pub 970","rat":"Qualified expenses include tuition, required fees, and books, supplies and equipment required for the courses.","ex":["Room and board is a personal expense and is not a qualified education expense.","Loan interest is not a qualified expense. It may be deductible separately.","Transportation is a personal expense and is not a qualified expense.","Qualified expenses include tuition, required fees, and books, supplies and equipment required for the courses."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"American opportunity credit expenses are tuition, required fees and required course materials, not room and board, loan interest or transportation.","from":"2026-01-01","gd":[["What does the American opportunity credit count as qualified expenses?","Tuition, required fees, and books, supplies and equipment required for the courses."],["Which listed expenses are excluded?","Room and board, loan interest and transportation, so only tuition and required materials qualify."]]}},{"i":"REG-IV-F-0013","t":"Ivan paid $8,000 of foreign income tax on foreign source income in 2026. Which statement about the treatment of the foreign tax is correct?","mc":{"s":"Ivan paid $8,000 of foreign income tax on foreign source income in 2026. Which statement about the treatment of the foreign tax is correct?","d":"","o":["Ivan may choose a credit against U.S. tax, limited to the U.S. tax on his foreign source income, or an itemized deduction","Ivan must claim the credit, and a deduction is not allowed","Ivan may claim the full $8,000 as a credit even if it exceeds his U.S. tax on the foreign income","Ivan may claim both a credit and an itemized deduction for the same taxes"],"a":1,"cite":"IRC §901; IRC §904(a); IRC §164(a); Pub 514","rat":"Foreign income taxes may be claimed as a credit (limited) or as an itemized deduction, not both for the same year.","ex":["Foreign income taxes may be claimed as a credit (limited) or as an itemized deduction, not both for the same year.","The taxpayer chooses between the credit and the deduction.","The credit is limited to the U.S. tax attributable to foreign source income.","The same tax cannot be both credited and deducted."],"wt":["","concept","limit","concept"],"tags":{"area":"IV","group":"F","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Foreign income tax may be claimed as a limited credit or an itemized deduction, but not both for the same year.","from":"2026-01-01","gd":[["May foreign income tax be both credited and deducted for the same year?","No, one or the other."],["What limits the credit?","The U.S. tax on the foreign source income; the alternative is an itemized deduction."]]}},{"i":"REG-IV-F-0014","t":"Gwen Alder, a single taxpayer, has 2026 taxable income of $145,000, all of it ordinary income. Use the 2026 rate schedule shown in the exhibit. What is her income tax?","mc":{"s":"Gwen Alder, a single taxpayer, has 2026 taxable income of $145,000, all of it ordinary income. Use the 2026 rate schedule shown in the exhibit. What is her income tax?","d":"","o":["$21,324","$27,398","$31,900","$34,800"],"a":2,"cite":"IRC §1(c); Pub 17","rat":"Tax = 10% x $12,400 + 12% x ($50,400 - $12,400) + 22% x ($105,700 - $50,400) + 24% x ($145,000 - $105,700) = $1,240 + $4,560 + $12,166 + $9,432 = $27,398.","ex":["Uses the married filing jointly schedule.","Tax = 10% x $12,400 + 12% x ($50,400 - $12,400) + 22% x ($105,700 - $50,400) + 24% x ($145,000 - $105,700) = $1,240 + $4,560 + $12,166 + $9,432 = $27,398.","Applies 22% to all income, ignoring the brackets.","Applies the top marginal rate to all taxable income instead of using the progressive brackets."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Income tax is computed progressively by bracket using the schedule for the taxpayer's filing status.","tb":[["Taxable income over","But not over","Rate"],["$0","$12,400","10%"],["$12,400","$50,400","12%"],["$50,400","$105,700","22%"],["$105,700","$201,775","24%"],["$201,775","$256,225","32%"],["$256,225","$640,600","35%"],["$640,600","no limit","37%"]],"from":"2026-07-01","calc":1,"steps":["10% x 12,400 = 1,240","12% x 38,000 = 4,560","22% x 55,300 = 12,166","24% x 39,300 = 9,432","Total = 27,398"],"gd":[["What are the bracket widths through 24%?","12,400 at 10%, 38,000 at 12%, 55,300 at 22%, and the remaining 145,000 - 105,700 = 39,300 at 24%."],["What is each bracket's tax?","1,240, 4,560, 12,166 and 9,432."],["What is the total?","27,398."]]}},{"i":"REG-IV-F-0015","t":"Hal Voss, a single taxpayer, has 2026 taxable income of $60,050, consisting of $40,050 of ordinary income and $20,000 of long-term capital gain. The 0% rate for long-term capital gain applies to taxable income up to $49,450 for single filers, and 15% applies above that (up to $545,500). Use the ordinary rate schedule in the exhibit. What is Hal's income tax?","mc":{"s":"Hal Voss, a single taxpayer, has 2026 taxable income of $60,050, consisting of $40,050 of ordinary income and $20,000 of long-term capital gain. The 0% rate for long-term capital gain applies to taxable income up to $49,450 for single filers, and 15% applies above that (up to $545,500). Use the ordinary rate schedule in the exhibit. What is Hal's income tax?","d":"","o":["$4,558","$6,148","$7,558","$7,923"],"a":2,"cite":"IRC §1(h); Pub 550","rat":"Ordinary tax on $40,050 = $1,240 + 12% x $27,650 = $4,558.","ex":["Omits the tax on the capital gain above the 0% band.","Ordinary tax on $40,050 = $1,240 + 12% x $27,650 = $4,558. The gain fills the 0% band from $40,050 to $49,450 ($9,400) and the remaining $10,600 is taxed at 15% = $1,590. Total = $6,148.","Taxes the entire gain at 15% and ignores the 0% band left below $49,450.","Taxes the gain as ordinary income."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Qualified long-term gain fills the 0% band above ordinary taxable income, and the remainder is taxed at 15%.","tb":[["Taxable income over","But not over","Rate"],["$0","$12,400","10%"],["$12,400","$50,400","12%"],["$50,400","$105,700","22%"],["$105,700","$201,775","24%"],["$201,775","$256,225","32%"],["$256,225","$640,600","35%"],["$640,600","no limit","37%"]],"from":"2026-07-01","calc":1,"steps":["Ordinary tax = 1,240 + 12% x (40,050 - 12,400) = 4,558","0% band remaining = 49,450 - 40,050 = 9,400","Gain taxed at 15% = 20,000 - 9,400 = 10,600 x 15% = 1,590","Total = 4,558 + 1,590 = 6,148"],"gd":[["What is the ordinary tax on 40,050?","1,240 + 12% x 27,650 = 4,558."],["How much of the 0% band is left for the gain?","49,450 - 40,050 = 9,400."],["What is the tax on the rest of the gain and the total?","20,000 - 9,400 = 10,600 x 15% = 1,590, so 4,558 + 1,590 = 6,148."]]}},{"i":"REG-IV-F-0016","t":"Ella Fox, a single taxpayer, has modified AGI of $235,000 for 2026, which includes $50,000 of net investment income. What is her net investment income tax?","mc":{"s":"Ella Fox, a single taxpayer, has modified AGI of $235,000 for 2026, which includes $50,000 of net investment income. What is her net investment income tax?","d":"","o":["$1,330","$1,900","$3,230","$8,930"],"a":1,"cite":"IRC §1411(a)(1); IRC §1411(b); Form 8960 instructions","rat":"The tax is 3.8% of the lesser of net investment income ($50,000) or MAGI over the $200,000 threshold ($35,000): 3.8% x $35,000 = $1,330.","ex":["The tax is 3.8% of the lesser of net investment income ($50,000) or MAGI over the $200,000 threshold ($35,000): 3.8% x $35,000 = $1,330.","Applies 3.8% to all net investment income instead of the lesser amount.","Uses a $150,000 threshold. The net investment income tax threshold for single filers is $200,000.","Applies 3.8% to all MAGI. Only the lesser of investment income or the excess over the threshold is taxed."],"wt":["","calc","limit","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net investment income tax is 3.8% of the lesser of net investment income or MAGI over the threshold.","from":"2026-01-01","calc":1,"steps":["Excess MAGI = 235,000 - 200,000 = 35,000","Lesser of 50,000 or 35,000 = 35,000","3.8% x 35,000 = 1,330"],"gd":[["What are the two figures compared for the NIIT?","Net investment income 50,000 and MAGI over 200,000, which is 35,000."],["Which is lower?","35,000."],["What is the tax?","3.8% x 35,000 = 1,330."]]}},{"i":"REG-IV-F-0017","t":"Marcus Hale, a single employee, earned $260,000 of wages in 2026, with no self-employment income. The additional Medicare tax rate is 0.9% on wages above $200,000 for single filers. What is the additional Medicare tax on his wages?","mc":{"s":"Marcus Hale, a single employee, earned $260,000 of wages in 2026, with no self-employment income. The additional Medicare tax rate is 0.9% on wages above $200,000 for single filers. What is the additional Medicare tax on his wages?","d":"","o":["$540","$990","$2,340","$5,400"],"a":1,"cite":"IRC §3101(b)(2); IRC §3102(f); Form 8959 instructions","rat":"The tax applies only to wages above the threshold: 0.9% x $60,000 = $540.","ex":["The tax applies only to wages above the threshold: 0.9% x $60,000 = $540.","Uses a $150,000 threshold. The additional Medicare tax threshold for single filers is $200,000.","Applies 0.9% to all wages instead of only the excess over $200,000.","Uses 9% instead of the 0.9% additional Medicare tax rate."],"wt":["","limit","calc","limit"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Additional Medicare tax is 0.9% of wages above the $200,000 single threshold.","from":"2026-01-01","calc":1,"steps":["Excess wages = 260,000 - 200,000 = 60,000","0.9% x 60,000 = 540"],"gd":[["On what amount does the additional Medicare tax apply?","Wages above 200,000."],["What is the excess and the tax?","260,000 - 200,000 = 60,000, and 0.9% x 60,000 = 540."]]}},{"i":"REG-IV-F-0018","t":"Sam and Lee Ortiz file jointly for 2026 with AGI of $150,000 and have three dependent children, ages 8, 15, and 18 (the 18-year-old is a full-time student and a dependent). All have Social Security numbers. Assume the credit is $2,200 for each qualifying child under 17 and $500 for each other dependent, and that tax liability is large enough to use the credits. What total credit may they claim?","mc":{"s":"Sam and Lee Ortiz file jointly for 2026 with AGI of $150,000 and have three dependent children, ages 8, 15, and 18 (the 18-year-old is a full-time student and a dependent). All have Social Security numbers. Assume the credit is $2,200 for each qualifying child under 17 and $500 for each other dependent, and that tax liability is large enough to use the credits. What total credit may they claim?","d":"","o":["$4,400","$4,900","$6,600","$7,100"],"a":2,"cite":"IRC §24(a), (h)(4); Pub 972","rat":"The 8- and 15-year-olds are qualifying children under 17 ($2,200 each = $4,400).","ex":["Omits the $500 credit for the 18-year-old dependent.","The 8- and 15-year-olds are qualifying children under 17 ($2,200 each = $4,400). The 18-year-old qualifies for the $500 credit for other dependents. Total: $4,900.","Applies the child tax credit to all three children. The 18-year-old is not under 17.","Counts the 18-year-old under both credits."],"wt":["calc","","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The child tax credit covers each dependent under 17, and other dependents get the smaller credit.","from":"2026-07-01","calc":1,"steps":["Under 17: 2 x 2,200 = 4,400","Other dependent (age 18): 500","Total = 4,900"],"gd":[["Which children get the larger credit?","Those under 17: the 8- and 15-year-olds, 2 x 2,200 = 4,400."],["What does the 18-year-old dependent get?","The 500 credit for other dependents."],["What is the total?","4,400 + 500 = 4,900."]]}},{"i":"REG-IV-F-0019","t":"Rita Cole, a single parent, has one 5-year-old child who is a qualifying child and no income tax liability for 2026. Her earned income is $12,500. The credit is $2,200 per child, of which at most $1,700 per child is refundable, and the refundable amount is limited to 15% of earned income above $2,500. What refundable child tax credit may Rita receive?","mc":{"s":"Rita Cole, a single parent, has one 5-year-old child who is a qualifying child and no income tax liability for 2026. Her earned income is $12,500. The credit is $2,200 per child, of which at most $1,700 per child is refundable, and the refundable amount is limited to 15% of earned income above $2,500. What refundable child tax credit may Rita receive?","d":"","o":["$1,500","$1,700","$1,875","$2,200"],"a":1,"cite":"IRC §24(d); Pub 972","rat":"The refundable amount is the lesser of $1,700 or 15% x ($12,500 - $2,500) = $1,500.","ex":["The refundable amount is the lesser of $1,700 or 15% x ($12,500 - $2,500) = $1,500. Rita receives $1,500.","Uses the per-child refundable maximum and ignores the earned income limit.","Applies 15% to all earned income rather than only earned income above $2,500.","Uses the full credit. Only the refundable portion can be received without tax liability."],"wt":["","concept","calc","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The refundable child tax credit is the lesser of the per-child refundable cap or 15% of earned income above $2,500.","from":"2026-07-01","calc":1,"steps":["15% x (12,500 - 2,500) = 1,500","Cap per child = 1,700","Refundable credit = lesser = 1,500"],"gd":[["What is the earned income above the base?","12,500 - 2,500 = 10,000, and 15% of it is 1,500."],["What is the per-child refundable cap?","1,700."],["Which is smaller?","1,500."]]}},{"i":"REG-IV-F-0020","t":"Nia and Paul Park file jointly for 2026 with modified AGI of $170,000. Their daughter is a first-year college student with $4,000 of qualified expenses. The American opportunity credit is 100% of the first $2,000 of expenses plus 25% of the next $2,000, phased out between $160,000 and $180,000 of modified AGI for joint filers. Forty percent of the credit after the phase-out is refundable. What is the nonrefundable part of the credit?","mc":{"s":"Nia and Paul Park file jointly for 2026 with modified AGI of $170,000. Their daughter is a first-year college student with $4,000 of qualified expenses. The American opportunity credit is 100% of the first $2,000 of expenses plus 25% of the next $2,000, phased out between $160,000 and $180,000 of modified AGI for joint filers. Forty percent of the credit after the phase-out is refundable. What is the nonrefundable part of the credit?","d":"","o":["$500","$750","$1,250","$1,500"],"a":2,"cite":"IRC §25A(b), (d); Pub 970","rat":"Full credit = $2,000 + 25% x $2,000 = $2,500.","ex":["This is the refundable part ($500), not the nonrefundable part.","Full credit = $2,000 + 25% x $2,000 = $2,500. Half is phased out, leaving $1,250. Forty percent ($500) is refundable, so the nonrefundable part is $750.","This is the total credit after the phase-out, before separating the refundable part.","Ignores the phase-out for modified AGI within the range."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The American opportunity credit is phased out ratably by MAGI, and 40% of the credit is refundable.","from":"2026-01-01","calc":1,"steps":["Credit = 2,000 + 25% x 2,000 = 2,500","Phase-out: 2,500 x (1 - 10,000/20,000) = 1,250","Refundable = 40% x 1,250 = 500","Nonrefundable = 750"],"gd":[["What is the full credit?","2,000 + 25% x 2,000 = 2,500."],["How much is left after the phase-out at 170,000?","Halfway through the 20,000 range, so 1,250."],["What are the refundable and nonrefundable parts?","40% x 1,250 = 500 refundable, so 1,250 - 500 = 750 nonrefundable."]]}},{"i":"REG-IV-F-0021","t":"Cal Bruno's 2026 taxable income is $100,000, including $25,000 of foreign source income on which he paid $8,000 of foreign income tax. His U.S. tax before credits is $20,000. What foreign tax credit may he claim for 2026?","mc":{"s":"Cal Bruno's 2026 taxable income is $100,000, including $25,000 of foreign source income on which he paid $8,000 of foreign income tax. His U.S. tax before credits is $20,000. What foreign tax credit may he claim for 2026?","d":"","o":["$3,000","$5,000","$8,000","$20,000"],"a":2,"cite":"IRC §904(a); IRC §904(c); Pub 514","rat":"The credit is limited to U.S.","ex":["This is the excess foreign tax carried over ($3,000), not the credit allowed.","The credit is limited to U.S. tax x foreign source income / taxable income = $20,000 x $25,000 / $100,000 = $5,000. The remaining $3,000 may be carried back one year or forward ten years.","Claims all foreign tax paid, ignoring the credit limitation.","Uses all U.S. tax as the credit. The credit cannot exceed the U.S. tax on foreign source income."],"wt":["calc","","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The foreign tax credit is limited to U.S. tax times foreign source income over taxable income, with the excess carried back or forward.","from":"2026-01-01","calc":1,"steps":["Limit = 20,000 x 25,000 / 100,000 = 5,000","Credit = lesser of 8,000 or 5,000 = 5,000"],"gd":[["What limits the foreign tax credit?","U.S. tax x foreign source income / taxable income."],["What is the limit?","20,000 x 25,000 / 100,000 = 5,000."],["Which is smaller than the 8,000 paid?","5,000, so that is the credit."]]}},{"i":"REG-IV-F-0022","t":"Review the exhibit for Carlos and Diana Ruiz, who file jointly for 2026 with taxable income of $240,000, all ordinary. Their draft return computes tax of $53,256 using the single rate schedule. What is the correct tax using the married filing jointly schedule?","mc":{"s":"Review the exhibit for Carlos and Diana Ruiz, who file jointly for 2026 with taxable income of $240,000, all ordinary. Their draft return computes tax of $53,256 using the single rate schedule. What is the correct tax using the married filing jointly schedule?","d":"","o":["$42,796","$52,800","$53,256","$57,600"],"a":1,"cite":"IRC §1(a); Pub 17","rat":"Tax = 10% x $24,800 + 12% x $76,000 + 22% x $110,600 + 24% x $28,600 = $2,480 + $9,120 + $24,332 + $6,864 = $42,796.","ex":["Tax = 10% x $24,800 + 12% x $76,000 + 22% x $110,600 + 24% x $28,600 = $2,480 + $9,120 + $24,332 + $6,864 = $42,796.","Applies 22% to all taxable income.","This is the draft amount, computed with the single schedule.","Applies 24% to all taxable income."],"wt":["","calc","concept","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Tax on joint taxable income must be computed with the married filing jointly bracket schedule.","tb":[["Taxable income over","But not over","Rate"],["$0","$24,800","10%"],["$24,800","$100,800","12%"],["$100,800","$211,400","22%"],["$211,400","$403,550","24%"],["$403,550","$512,450","32%"],["$512,450","$768,700","35%"],["$768,700","no limit","37%"]],"from":"2026-07-01","calc":1,"steps":["10% x 24,800 = 2,480","12% x 76,000 = 9,120","22% x 110,600 = 24,332","24% x 28,600 = 6,864","Total = 42,796"],"gd":[["Which schedule applies to joint filers?","The married filing jointly schedule with a 24,800 first bracket."],["What are the bracket amounts?","2,480, 9,120, 24,332 and 6,864."],["What is the total?","42,796."]]}},{"i":"REG-IV-F-0023","t":"Review the exhibit for a joint return for 2026. The couple has two children under 17 and the draft return claims a $4,400 child tax credit. Modified AGI is $412,300. The credit is $2,200 per child and is reduced by $50 for each $1,000 (or fraction) of modified AGI over $400,000. What is the correct credit?","mc":{"s":"Review the exhibit for a joint return for 2026. The couple has two children under 17 and the draft return claims a $4,400 child tax credit. Modified AGI is $412,300. The credit is $2,200 per child and is reduced by $50 for each $1,000 (or fraction) of modified AGI over $400,000. What is the correct credit?","d":"","o":["$650","$3,750","$3,800","$4,400"],"a":2,"cite":"IRC §24(b); Pub 972","rat":"The excess is $12,300, which rounds up to 13 increments of $1,000.","ex":["This is the amount of the reduction ($650), not the credit that remains.","The excess is $12,300, which rounds up to 13 increments of $1,000. Reduction = 13 x $50 = $650. Credit = $4,400 - $650 = $3,750.","Rounds the excess down to 12 increments. A fraction of $1,000 counts as a full increment.","Claims the full credit and ignores the reduction for modified AGI above $400,000."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The child tax credit phase-down counts each $1,000 or fraction of MAGI over the threshold as a full increment.","tb":[["Item","Amount"],["Modified AGI","$412,300"],["Filing status","Married filing jointly"],["Threshold","$400,000"],["Draft credit","$4,400"]],"from":"2026-07-01","calc":1,"steps":["Excess = 412,300 - 400,000 = 12,300 -> 13 increments","Reduction = 13 x 50 = 650","Credit = 4,400 - 650 = 3,750"],"gd":[["How far over the threshold is MAGI?","412,300 - 400,000 = 12,300, or 13 increments of 1,000."],["What is the reduction?","13 x 50 = 650."],["What is the credit?","4,400 - 650 = 3,750."]]}},{"i":"REG-IV-F-0024","t":"Review the exhibit for Jon Marsh, a single taxpayer, whose draft 2026 return shows no AMT. He exercised incentive stock options and kept the shares. Assume the AMT exemption is $90,100 (not phased out at his income) and the AMT rate is 26% on the first $244,500 of AMT base and 28% above it. His regular tax on $300,000 of taxable income is shown in the exhibit. What is his alternative minimum tax for 2026?","mc":{"s":"Review the exhibit for Jon Marsh, a single taxpayer, whose draft 2026 return shows no AMT. He exercised incentive stock options and kept the shares. Assume the AMT exemption is $90,100 (not phased out at his income) and the AMT rate is 26% on the first $244,500 of AMT base and 28% above it. His regular tax on $300,000 of taxable income is shown in the exhibit. What is his alternative minimum tax for 2026?","d":"","o":["$0","$9,625","$14,515","$34,853"],"a":2,"cite":"IRC §55(a)-(b); IRC §56(b)(1)(A); IRC §56(b)(3); IRC §57(a)(5); Form 6251 instructions","rat":"AMTI = $300,000 + $40,400 (state and local taxes) + $60,000 (option bargain element) + $5,000 (private activity bond interest) = $405,400.","ex":["This is the draft return, which ignores the adjustments and preferences.","AMTI = $300,000 + $40,400 (state and local taxes) + $60,000 (option bargain element) + $5,000 (private activity bond interest) = $405,400. Base = $405,400 - $90,100 = $315,300. Tentative minimum tax = 26% x $244,500 + 28% x $70,800 = $83,394. AMT = $83,394 - $73,769 = $9,625.","Applies 28% to the entire AMT base.","Omits the AMT exemption, which reduces the amount subject to the AMT rates."],"wt":["concept","","calc","calc"],"tags":{"area":"IV","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"AMTI adds back SALT, ISO bargain element and private activity bond interest, subtracts the exemption, and AMT is the excess over regular tax.","tb":[["Item","Amount"],["Regular taxable income","$300,000"],["State and local taxes deducted on Schedule A","$40,400"],["Incentive stock option bargain element (shares not sold)","$60,000"],["Private activity bond interest (exempt for regular tax)","$5,000"],["Regular tax","$73,769"],["AMT reported on draft","$0"]],"from":"2026-07-01","calc":1,"steps":["AMTI = 300,000 + 40,400 + 60,000 + 5,000 = 405,400","Base = 405,400 - 90,100 = 315,300","Tentative minimum tax = 26% x 244,500 + 28% x 70,800 = 63,570 + 19,824 = 83,394","AMT = 83,394 - 73,769 = 9,625"],"gd":[["Which items are added to regular taxable income for AMTI?","State and local taxes 40,400, the option bargain element 60,000 and private activity bond interest 5,000."],["What are AMTI and the AMT base?","300,000 + 40,400 + 60,000 + 5,000 = 405,400, less exemption 90,100 = 315,300."],["What is the tentative tax and the AMT?","26% x 244,500 + 28% x 70,800 = 83,394, so 83,394 - 73,769 = 9,625."]]}},{"i":"REG-IV-F-0025","t":"Review the exhibit for a single taxpayer whose 2026 alternative minimum taxable income is $560,000. The draft Form 6251 uses the full exemption of $90,100. The exemption is reduced by 50 cents for each dollar of AMTI above $500,000. What exemption amount should be used?","mc":{"s":"Review the exhibit for a single taxpayer whose 2026 alternative minimum taxable income is $560,000. The draft Form 6251 uses the full exemption of $90,100. The exemption is reduced by 50 cents for each dollar of AMTI above $500,000. What exemption amount should be used?","d":"","o":["$30,100","$60,100","$75,100","$90,100"],"a":2,"cite":"IRC §55(d)(2)-(3); Form 6251 instructions","rat":"Excess AMTI = $60,000.","ex":["Subtracts the whole excess AMTI ($60,000) instead of half of it.","Excess AMTI = $60,000. Reduction = 50% x $60,000 = $30,000. Exemption = $90,100 - $30,000 = $60,100.","Uses a 25% phase-out rate, which was the rate before 2026.","This is the draft's full exemption, which ignores the phase-out."],"wt":["calc","","limit","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The AMT exemption phases out at 50 cents per dollar of AMTI above the threshold.","tb":[["Item","Amount"],["AMTI","$560,000"],["Phase-out threshold (single)","$500,000"],["Full exemption (single)","$90,100"],["Exemption used on draft","$90,100"]],"from":"2026-07-01","calc":1,"steps":["Excess = 560,000 - 500,000 = 60,000","Reduction = 50% x 60,000 = 30,000","Exemption = 90,100 - 30,000 = 60,100"],"gd":[["How much does AMTI exceed the threshold?","560,000 - 500,000 = 60,000."],["What is the reduction?","50% x 60,000 = 30,000."],["What is the exemption?","90,100 - 30,000 = 60,100."]]}},{"i":"REG-IV-F-0026","t":"A first-year college student's parents, whose income is below the phase-out range, paid $6,000 of qualified tuition and required course materials for her in 2026. They may claim either the American opportunity credit (100% of the first $2,000 plus 25% of the next $2,000) or the lifetime learning credit (20% of up to $10,000 of expenses), but not both for the same student. By how much is the larger credit greater than the smaller?","mc":{"s":"A first-year college student's parents, whose income is below the phase-out range, paid $6,000 of qualified tuition and required course materials for her in 2026. They may claim either the American opportunity credit (100% of the first $2,000 plus 25% of the next $2,000) or the lifetime learning credit (20% of up to $10,000 of expenses), but not both for the same student. By how much is the larger credit greater than the smaller?","d":"","o":["$1,300","$2,500","$3,700","$6,000"],"a":1,"cite":"IRC §25A(b), (c), (e)(1); Pub 970","rat":"American opportunity credit = $2,000 + $500 = $2,500.","ex":["American opportunity credit = $2,000 + $500 = $2,500. Lifetime learning credit = 20% x $6,000 = $1,200. The difference is $1,300.","Treats the lifetime learning credit as zero.","Adds the two credits. Only one may be claimed for the same student.","Uses the total expenses as the difference."],"wt":["","calc","concept","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Only one of the American opportunity or lifetime learning credits may be claimed per student, so the difference is the two credits' gap.","from":"2026-01-01","calc":1,"steps":["AOTC = 2,000 + 25% x 2,000 = 2,500","LLC = 20% x 6,000 = 1,200","2,500 - 1,200 = 1,300"],"gd":[["What is the American opportunity credit on 6,000 of expenses?","2,000 + 25% x 2,000 = 2,500."],["What is the lifetime learning credit?","20% x 6,000 = 1,200."],["What is the difference?","2,500 - 1,200 = 1,300."]]}},{"i":"REG-IV-F-0027","t":"Aaron's 2025 AGI was $210,000 and his 2025 tax was $40,000. He expects 2026 tax of $55,000. He can avoid the estimated tax penalty by paying either 90% of his 2026 tax or 110% of his 2025 tax. By how much is the lesser required annual payment below the greater?","mc":{"s":"Aaron's 2025 AGI was $210,000 and his 2025 tax was $40,000. He expects 2026 tax of $55,000. He can avoid the estimated tax penalty by paying either 90% of his 2026 tax or 110% of his 2025 tax. By how much is the lesser required annual payment below the greater?","d":"","o":["$5,500","$9,500","$15,000","$49,500"],"a":1,"cite":"IRC §6654(d)(1)(B)-(C); Pub 505","rat":"The 2026 safe harbor is 90% x $55,000 = $49,500.","ex":["The 2026 safe harbor is 90% x $55,000 = $49,500. The prior-year safe harbor is 110% x $40,000 = $44,000. The prior-year safe harbor is lower by $5,500.","Uses 100% of the prior-year tax. Prior-year AGI over $150,000 requires 110%.","Compares full current tax to 100% of prior-year tax.","Uses the current-year safe harbor as the difference."],"wt":["","limit","calc","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The estimated tax safe harbor is 90% of current tax or 110% of prior-year tax if prior AGI exceeds $150,000.","from":"2026-01-01","calc":1,"steps":["90% x 55,000 = 49,500","110% x 40,000 = 44,000","49,500 - 44,000 = 5,500"],"gd":[["What is the current-year safe harbor?","90% x 55,000 = 49,500."],["What is the prior-year safe harbor?","110% x 40,000 = 44,000."],["What is the gap?","49,500 - 44,000 = 5,500."]]}},{"i":"REG-IV-F-0028","t":"Eli Grant, a single taxpayer with MAGI far above $200,000, sold all his S corporation stock in 2026 and realized a $200,000 gain. The S corporation's assets included active business assets and investment assets. If the corporation had sold all its assets at fair market value on the sale date, $20,000 of gain would be from investment assets, and $180,000 would be from active trade or business assets in which Eli materially participates. What is Eli's net investment income tax on the stock gain?","mc":{"s":"Eli Grant, a single taxpayer with MAGI far above $200,000, sold all his S corporation stock in 2026 and realized a $200,000 gain. The S corporation's assets included active business assets and investment assets. If the corporation had sold all its assets at fair market value on the sale date, $20,000 of gain would be from investment assets, and $180,000 would be from active trade or business assets in which Eli materially participates. What is Eli's net investment income tax on the stock gain?","d":"","o":["$760","$3,800","$6,840","$7,600"],"a":1,"cite":"IRC §1411(c)(4); Reg §1.1411-7; Form 8960 instructions","rat":"Gain on a disposition of S corporation stock is net investment income only to the extent of the net gain that would be taken into account on a deemed asset sale of the passive assets: $20,000.","ex":["Gain on a disposition of S corporation stock is net investment income only to the extent of the net gain that would be taken into account on a deemed asset sale of the passive assets: $20,000. Tax = 3.8% x $20,000 = $760.","Taxes half of the stock gain. The taxable part is the gain on the investment assets in the deemed asset sale ($20,000).","Taxes the gain attributable to the active business assets, which is excluded.","Treats the entire stock gain as investment income."],"wt":["","calc","concept","concept"],"tags":{"area":"IV","group":"F","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Gain on S corporation stock is net investment income only to the extent of gain on passive assets in a deemed asset sale.","from":"2026-01-01","calc":1,"steps":["Deemed sale gain from investment assets = 20,000","3.8% x 20,000 = 760"],"gd":[["Which part of the gain counts as net investment income?","Only what a deemed asset sale would produce from passive or investment assets, 20,000."],["What is the tax?","3.8% x 20,000 = 760."]]}},{"i":"REG-IV-F-0029","t":"Review the exhibit for the 2026 return of Fern Lowe, whose 15-year-old son has $6,500 of interest and dividend income and no earned income. The draft return taxes all of the son's income at his own rate. Assume the kiddie tax threshold is $2,700 (the first $1,350 is offset by his standard deduction and the next $1,350 is taxed at his rate). What amount of the son's income is taxed at Fern's marginal rate?","mc":{"s":"Review the exhibit for the 2026 return of Fern Lowe, whose 15-year-old son has $6,500 of interest and dividend income and no earned income. The draft return taxes all of the son's income at his own rate. Assume the kiddie tax threshold is $2,700 (the first $1,350 is offset by his standard deduction and the next $1,350 is taxed at his rate). What amount of the son's income is taxed at Fern's marginal rate?","d":"","o":["$1,350","$3,800","$5,150","$6,500"],"a":2,"cite":"IRC §1(g); Form 8615 instructions; Pub 929","rat":"Net unearned income = $6,500 - $2,700 = $3,800.","ex":["This is the amount taxed at the child's own rate.","Net unearned income = $6,500 - $2,700 = $3,800. This amount is taxed at the parent's marginal rate.","Subtracts only the child's standard deduction and ignores the additional $1,350 that is taxed at the child's own rate.","Taxes all of the son's income at the parent's rate. The first $2,700 is not subject to the parent's rate."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"F","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Kiddie tax unearned income above the threshold, after the standard deduction and child-rate band, is taxed at the parent's rate.","tb":[["Item","Amount"],["Child's age","15"],["Interest and dividends","$6,500"],["Earned income","$0"],["Parent's marginal rate","24%"]],"from":"2026-01-01","calc":1,"steps":["Net unearned income = 6,500 - 2,700 = 3,800","3,800 is taxed at the parent's marginal rate"],"gd":[["How much of the son's income is net unearned income?","6,500 - 2,700 = 3,800."],["At whose rate is it taxed?","The parent's marginal rate."]]}},{"i":"REG-IV-F-0030","t":"Review the exhibit for Tomas Vega's 2026 self-employment tax. The draft return shows $8,478 of self-employment tax on $60,000 of net earnings. Tomas also had $150,000 of wages subject to Social Security tax. Assume the 2026 Social Security wage base is $184,500. What is the correct self-employment tax?","mc":{"s":"Review the exhibit for Tomas Vega's 2026 self-employment tax. The draft return shows $8,478 of self-employment tax on $60,000 of net earnings. Tomas also had $150,000 of wages subject to Social Security tax. Assume the 2026 Social Security wage base is $184,500. What is the correct self-employment tax?","d":"","o":["$1,607","$5,885","$8,478","$9,180"],"a":2,"cite":"IRC §1401(a)-(b); IRC §1402(a); IRC §1402(b); Pub 334","rat":"Net earnings from self-employment = $60,000 x 92.35% = $55,410.","ex":["Includes only the Medicare portion and omits the remaining Social Security tax.","Net earnings from self-employment = $60,000 x 92.35% = $55,410. Only $184,500 - $150,000 = $34,500 is subject to the 12.4% Social Security tax: $4,278. Medicare tax is 2.9% x $55,410 = $1,607. Total = $5,885.","This is the draft's amount, ignoring the wage base reduced by wages.","Applies 15.3% to the full $60,000 without the 92.35% factor or wage base."],"wt":["calc","","concept","calc"],"tags":{"area":"IV","group":"F","skill":"Application","diff":3},"asof":"2026-09-29","rl":"SE tax applies the 12.4% Social Security rate only to earnings up to the wage base less wages, plus 2.9% Medicare on 92.35% of net earnings.","tb":[["Item","Amount"],["Net profit from Schedule C","$60,000"],["W-2 wages subject to Social Security tax","$150,000"],["Draft SE tax (net profit x 92.35% x 15.3%)","$8,478"]],"from":"2026-01-01","calc":1,"steps":["Net earnings = 60,000 x 0.9235 = 55,410","SS: 12.4% x (184,500 - 150,000) = 4,278","Medicare: 2.9% x 55,410 = 1,607","Total = 5,885"],"gd":[["What are net earnings from self-employment?","60,000 x 0.9235 = 55,410."],["How much is subject to the 12.4% Social Security tax given the wage base?","184,500 - 150,000 = 34,500, so 4,278."],["What is Medicare and the total?","2.9% x 55,410 = 1,607, so 4,278 + 1,607 = 5,885."]]}}]};
